(354617,39402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki bu uçuş için cam kenarı koltuğu aylar önce ...'::text,'ayırtmış'::text,'ayırtıyormuş'::text,'ayırtmış'::text,'Dinle, duydum ki bu uçuş için cam kenarı koltuğu aylar önce ayırtmış.'::text),
(354618,39402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy már hónapokkal ezelőtt ... az ablak melletti ülést erre a repülésre.'::text,'lefoglalta'::text,'foglalta'::text,'lefoglalta'::text,'Figyelj, azt hallottam, hogy már hónapokkal ezelőtt lefoglalta az ablak melletti ülést erre a repülésre.'::text),
(354621,39403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also anscheinend wurde ihm der Saft mitten im Flug ...'::text,'serviert'::text,'serviert'::text,'servierend'::text,'Okay, also anscheinend wurde ihm der Saft mitten im Flug serviert.'::text),
(354625,39403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, сік йому ... посеред польоту.'::text,'подали'::text,'подав'::text,'подаючи'::text,'Короче, кажуть, сік йому подали посеред польоту.'::text),
(354624,39403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer el zumo le ... a mitad del vuelo.'::text,'fue servido'::text,'sirvió'::text,'sirviendo'::text,'Vale, pues al parecer el zumo le fue servido a mitad del vuelo.'::text),
(354623,39403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, alors apparemment le jus lui ... au milieu du vol.'::text,'a été servi'::text,'a servi'::text,'servant'::text,'Ok, alors apparemment le jus lui a été servi au milieu du vol.'::text),
(354626,39403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan meyve suyu ona uçuşun ortasında ...'::text,'servis edilmiş'::text,'servis etmiş'::text,'servis ederek'::text,'Tamam, anlaşılan meyve suyu ona uçuşun ortasında servis edilmiş.'::text),
(354627,39403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag a gyümölcslevet a repülés felénél ... neki.'::text,'szolgálták fel'::text,'szolgálta fel'::text,'felszolgálva'::text,'Oké, szóval állítólag a gyümölcslevet a repülés felénél szolgálták fel neki.'::text),
(354630,39404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... ein Profi beim Fliegen sein, du filmst den Start so smooth.'::text,'musst'::text,'kannst nicht'::text,'musst nicht'::text,'Ehrlich, du musst ein Profi beim Fliegen sein, du filmst den Start so smooth.'::text),
(354634,39404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... бути профі в перельотах, ти так плавно знімаєш зліт.'::text,'маєш'::text,'не можеш'::text,'можеш і не'::text,'Чесно, ти маєш бути профі в перельотах, ти так плавно знімаєш зліт.'::text),
(354633,39404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... ser un pro de los vuelos, grabas el despegue con muchísima soltura.'::text,'debes de'::text,'no puedes'::text,'podrías no'::text,'Sinceramente, tú debes de ser un pro de los vuelos, grabas el despegue con muchísima soltura.'::text),
(354632,39404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... être un pro des vols, tu filmes le décollage tellement bien.'::text,'dois'::text,'ne peux pas'::text,'pourrais ne pas'::text,'Franchement, tu dois être un pro des vols, tu filmes le décollage tellement bien.'::text),
(354635,39404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, uçuşlarda profesyonel ..., kalkışı çok akıcı çekiyorsun.'::text,'olmalısın'::text,'olamazsın'::text,'olmayabilirsin'::text,'Açıkçası, uçuşlarda profesyonel olmalısın, kalkışı çok akıcı çekiyorsun.'::text),
(354636,39404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... profi vagy a repülésekben, olyan simán veszed fel a felszállást.'::text,'biztosan'::text,'biztosan nem'::text,'talán nem'::text,'Őszintén, biztosan profi vagy a repülésekben, olyan simán veszed fel a felszállást.'::text),
(354639,39405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Flugvideo, ... du bei Sonnenuntergang gefilmt hast, sieht ehrlich mega aus.'::text,'das'::text,'der'::text,'wo'::text,'Dein Flugvideo, das du bei Sonnenuntergang gefilmt hast, sieht ehrlich mega aus.'::text),
(354643,39405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоє відео з польоту, ... ти зняв на заході сонця, чесно виглядає неймовірно.'::text,'яке'::text,'хто'::text,'де'::text,'Твоє відео з польоту, яке ти зняв на заході сонця, чесно виглядає неймовірно.'::text),
(354642,39405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu vídeo del vuelo, ... grabaste al atardecer, sinceramente se ve increíble.'::text,'que'::text,'quien'::text,'donde'::text,'Tu vídeo del vuelo, que grabaste al atardecer, sinceramente se ve increíble.'::text),
(354641,39405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ta vidéo du vol, ... tu as filmée au coucher du soleil, est franchement incroyable.'::text,'que'::text,'qui'::text,'où'::text,'Ta vidéo du vol, que tu as filmée au coucher du soleil, est franchement incroyable.'::text),
(354644,39405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımında ... uçuş videon açıkçası harika görünüyor.'::text,'çektiğin'::text,'çeken'::text,'çektiğin yerdeki'::text,'Gün batımında çektiğin uçuş videon açıkçası harika görünüyor.'::text),
(354645,39405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A repülős videód, ... naplementekor vettél fel, őszintén elképesztő.'::text,'amit'::text,'aki'::text,'ahol'::text,'A repülős videód, amit naplementekor vettél fel, őszintén elképesztő.'::text),
(354648,39406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er meinte, der Flug ... der langweiligste Tag seines Lebens, klar.'::text,'war'::text,'war'::text,'ist'::text,'Er meinte, der Flug war der langweiligste Tag seines Lebens, klar.'::text),
(354652,39406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що політ ... найнуднішим днем у його житті, звісно.'::text,'був'::text,'був'::text,'є'::text,'Він сказав, що політ був найнуднішим днем у його житті, звісно.'::text),
(354651,39406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que el vuelo ... el día más aburrido de su vida, obviamente.'::text,'había sido'::text,'ha sido'::text,'es'::text,'Dijo que el vuelo había sido el día más aburrido de su vida, obviamente.'::text),
(354650,39406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que le vol ... le jour le plus ennuyeux de sa vie, évidemment.'::text,'avait été'::text,'a été'::text,'est'::text,'Il a dit que le vol avait été le jour le plus ennuyeux de sa vie, évidemment.'::text),
(354653,39406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçuşun hayatının en sıkıcı günü ... söyledi, tabii ki.'::text,'olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'Uçuşun hayatının en sıkıcı günü olduğunu söyledi, tabii ki.'::text),
(354654,39406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a repülés ... élete legunalmasabb napja, persze.'::text,'volt'::text,'volt'::text,NULL::text,'Azt mondta, hogy a repülés volt élete legunalmasabb napja, persze.'::text),
(354657,39407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... Flüge; offensichtlich hat sich nichts geändert.'::text,'hasste früher'::text,'hasste immer'::text,'war es gewohnt zu hassen'::text,'Er hasste früher Flüge; offensichtlich hat sich nichts geändert.'::text),
(354661,39407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... перельоти; очевидно, нічого не змінилося.'::text,'колись ненавидів'::text,'бувало, ненавидів'::text,'звик ненавидіти'::text,'Він колись ненавидів перельоти; очевидно, нічого не змінилося.'::text),
(354660,39407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... odiar los vuelos; está claro que nada ha cambiado.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Él solía odiar los vuelos; está claro que nada ha cambiado.'::text),
(354659,39407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... détester les vols ; visiblement, rien n''a changé.'::text,'avait l''habitude de'::text,'avait l''habitude de'::text,'était habitué à'::text,'Il avait l''habitude de détester les vols ; visiblement, rien n''a changé.'::text),
(354662,39407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden uçuşlardan ...; belli ki hiçbir şey değişmemiş.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Eskiden uçuşlardan nefret ederdi; belli ki hiçbir şey değişmemiş.'::text),
(354663,39407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a repülést; láthatóan semmi sem változott.'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva, hogy utálja'::text,'Régen utálta a repülést; láthatóan semmi sem változott.'::text),
(354666,39408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro ist lowkey besessen davon, jede Sekunde dieses Flugs zu ..., ohne Witz.'::text,'filmen'::text,'filmen'::text,'filmen'::text,'Bro ist lowkey besessen davon, jede Sekunde dieses Flugs zu filmen, ohne Witz.'::text),
(354670,39408,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Братан реально помішаний на тому, щоб ... кожну секунду цього польоту, без жартів.'::text,'знімати'::text,'знімати'::text,'знімати'::text,'Братан реально помішаний на тому, щоб знімати кожну секунду цього польоту, без жартів.'::text),
(354669,39408,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tío está medio obsesionado con ... cada segundo de este vuelo, en serio.'::text,'grabar'::text,'grabar'::text,'grabar'::text,'El tío está medio obsesionado con grabar cada segundo de este vuelo, en serio.'::text),
(354668,39408,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gars est grave obsédé par le fait de ... chaque seconde de ce vol, sans mentir.'::text,'filmer'::text,'filmer'::text,'filmer'::text,'Le gars est grave obsédé par le fait de filmer chaque seconde de ce vol, sans mentir.'::text),
(354671,39408,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka bu uçuşun her saniyesini ... kafayı takmış, cidden.'::text,'çekmeye'::text,'çekmeye'::text,'çekmek'::text,'Kanka bu uçuşun her saniyesini çekmeye kafayı takmış, cidden.'::text),
(354672,39408,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tesó eléggé rá van kattanva, hogy ... ennek a repülésnek minden másodpercét, komolyan.'::text,'filmezze'::text,'filmezze'::text,'filmez'::text,'A tesó eléggé rá van kattanva, hogy filmezze ennek a repülésnek minden másodpercét, komolyan.'::text),
(354675,39409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... das Flugzeug am Ende seines Flugs über der Stadt.'::text,'sinkt'::text,'sinkt'::text,'sank'::text,'Gerade sinkt das Flugzeug am Ende seines Flugs über der Stadt.'::text),
(354679,39409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз літак ... над містом наприкінці його польоту.'::text,'знижується'::text,'знижується'::text,'знизився'::text,'Саме зараз літак знижується над містом наприкінці його польоту.'::text),
(354678,39409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el avión ... sobre la ciudad al final de su vuelo.'::text,'está descendiendo'::text,'desciende'::text,'ha descendido'::text,'Ahora mismo el avión está descendiendo sobre la ciudad al final de su vuelo.'::text),
(354677,39409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, l''avion ... au-dessus de la ville à la fin de son vol.'::text,'descend'::text,'descend'::text,'est descendu'::text,'En ce moment, l''avion descend au-dessus de la ville à la fin de son vol.'::text),
(354680,39409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda uçak, uçuşunun sonunda şehrin üzerinde ...'::text,'alçalıyor'::text,'alçalır'::text,'alçaldı'::text,'Şu anda uçak, uçuşunun sonunda şehrin üzerinde alçalıyor.'::text),
(354681,39409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a gép a város felett a repülése végén.'::text,'ereszkedik'::text,'ereszkedik'::text,'ereszkedett le'::text,'Épp most ereszkedik a gép a város felett a repülése végén.'::text),
(355062,39452,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend ... der Fluss so schnell, seit der Schnee angefangen hat zu schmelzen.'::text,'fließt'::text,'fließt'::text,'floss'::text,'Hör mal, anscheinend fließt der Fluss so schnell, seit der Schnee angefangen hat zu schmelzen.'::text),
(355066,39452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, річка ... так швидко, відколи почав танути сніг.'::text,'тече'::text,'тече'::text,'текла'::text,'Слухай, кажуть, річка тече так швидко, відколи почав танути сніг.'::text),
(355065,39452,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer el río ... así de rápido desde que empezó a derretirse la nieve.'::text,'está fluyendo'::text,'ha fluido'::text,'fluyó'::text,'Oye, al parecer el río está fluyendo así de rápido desde que empezó a derretirse la nieve.'::text),
(355064,39452,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la rivière ... aussi vite depuis que la neige a commencé à fondre.'::text,'coule'::text,'coule'::text,'a coulé'::text,'Écoute, apparemment la rivière coule aussi vite depuis que la neige a commencé à fondre.'::text),
(355067,39452,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan kar erimeye başladığından beri nehir bu kadar hızlı ...'::text,'akıyor'::text,'akıyor'::text,'aktı'::text,'Dinle, anlaşılan kar erimeye başladığından beri nehir bu kadar hızlı akıyor.'::text),
(355068,39452,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a folyó azóta ... ilyen gyorsan, hogy elkezdett olvadni a hó.'::text,'folyik'::text,'folyik'::text,'folyt'::text,'Figyelj, állítólag a folyó azóta folyik ilyen gyorsan, hogy elkezdett olvadni a hó.'::text),
(355071,39453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis er aufstand, ... das Boot schon auf dem fließenden Wasser davon, komplett weg.'::text,'trieb'::text,'trieb'::text,'treibt'::text,'Bro, bis er aufstand, trieb das Boot schon auf dem fließenden Wasser davon, komplett weg.'::text),
(355075,39453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки він підвівся, човник уже ... по течії, реально зник.'::text,'відплив'::text,'відплив'::text,'пливе'::text,'Бро, поки він підвівся, човник уже відплив по течії, реально зник.'::text),
(355074,39453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para cuando se levantó, el barquito ya ... flotando por la corriente, se fue de verdad.'::text,'se había alejado'::text,'se ha alejado'::text,'se aleja'::text,'Bro, para cuando se levantó, el barquito ya se había alejado flotando por la corriente, se fue de verdad.'::text),
(355073,39453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le temps qu''il se lève, le bateau ... sur l''eau qui coule, disparu pour de vrai.'::text,'s''était éloigné'::text,'s''est éloigné'::text,'s''éloigne'::text,'Frérot, le temps qu''il se lève, le bateau s''était éloigné sur l''eau qui coule, disparu pour de vrai.'::text),
(355076,39453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o ayağa kalkana kadar kayık akan suda çoktan ..., resmen gitti.'::text,'sürüklenip gitmişti'::text,'sürüklenip gitti'::text,'sürükleniyor'::text,'Kanka, o ayağa kalkana kadar kayık akan suda çoktan sürüklenip gitmişti, resmen gitti.'::text),
(355077,39453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire felállt, a hajó már ... a sodró vízen, tényleg eltűnt.'::text,'elúszott'::text,'elúszott'::text,'úszik'::text,'Tesó, mire felállt, a hajó már elúszott a sodró vízen, tényleg eltűnt.'::text),
(355080,39454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, morgen um diese Zeit ... der Fluss genauso schnell, und das Boot ist längst weg.'::text,'fließt'::text,'fließt'::text,'fließt'::text,'Alter, morgen um diese Zeit fließt der Fluss genauso schnell, und das Boot ist längst weg.'::text),
(355084,39454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, завтра в цей час річка ... так само швидко, а човник буде вже давно далеко.'::text,'буде текти'::text,'потече'::text,'тече'::text,'Чувак, завтра в цей час річка буде текти так само швидко, а човник буде вже давно далеко.'::text),
(355083,39454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mañana a esta hora el río ... igual de rápido y el barquito ya estará lejísimos.'::text,'estará fluyendo'::text,'fluirá'::text,'fluye'::text,'Tío, mañana a esta hora el río estará fluyendo igual de rápido y el barquito ya estará lejísimos.'::text),
(355082,39454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, demain à la même heure, la rivière ... tout aussi vite, et le bateau sera loin depuis longtemps.'::text,'coulera'::text,'coulera'::text,'coule'::text,'Mec, demain à la même heure, la rivière coulera tout aussi vite, et le bateau sera loin depuis longtemps.'::text),
(355085,39454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte nehir aynı hızla ... ve kayık çoktan gitmiş olacak.'::text,'akıyor olacak'::text,'akacak'::text,'akıyor'::text,'Kanka, yarın bu saatte nehir aynı hızla akıyor olacak ve kayık çoktan gitmiş olacak.'::text),
(355086,39454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, holnap ilyenkor a folyó ugyanilyen gyorsan ..., a hajó meg már rég messze lesz.'::text,'fog folyni'::text,'fog folyni'::text,'folyik'::text,'Haver, holnap ilyenkor a folyó ugyanilyen gyorsan fog folyni, a hajó meg már rég messze lesz.'::text),
(355089,39455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Renntag um 10 Uhr ... der Fluss schnell genug, um das Ziel für das Bootsrennen zu erreichen.'::text,'fließt'::text,'fließt'::text,'fließt'::text,'Am Renntag um 10 Uhr fließt der Fluss schnell genug, um das Ziel für das Bootsrennen zu erreichen.'::text),
(355093,39455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У день перегонів о 10:00 річка ... достатньо швидко, щоб виконати ціль для перегонів човнів.'::text,'буде текти'::text,'потече'::text,'тече'::text,'У день перегонів о 10:00 річка буде текти достатньо швидко, щоб виконати ціль для перегонів човнів.'::text),
(355092,39455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El día de la regata, a las 10:00, el río ... lo bastante rápido para cumplir el objetivo de la carrera.'::text,'estará fluyendo'::text,'fluirá'::text,'fluye'::text,'El día de la regata, a las 10:00, el río estará fluyendo lo bastante rápido para cumplir el objetivo de la carrera.'::text),
(355091,39455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jour de la course, à 10 h, la rivière ... assez vite pour atteindre l''objectif de la course de bateaux.'::text,'coulera'::text,'coulera'::text,'coule'::text,'Le jour de la course, à 10 h, la rivière coulera assez vite pour atteindre l''objectif de la course de bateaux.'::text),
(355094,39455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarış günü saat 10.00''da nehir, tekne yarışı hedefini tutturacak kadar hızlı ...'::text,'akıyor olacak'::text,'akacak'::text,'akıyor'::text,'Yarış günü saat 10.00''da nehir, tekne yarışı hedefini tutturacak kadar hızlı akıyor olacak.'::text),
(355095,39455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A verseny napján délelőtt 10-kor a folyó elég gyorsan ... ahhoz, hogy teljesüljön a hajóverseny célja.'::text,'fog folyni'::text,'fog folyni'::text,'folyik'::text,'A verseny napján délelőtt 10-kor a folyó elég gyorsan fog folyni ahhoz, hogy teljesüljön a hajóverseny célja.'::text),
(355098,39456,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Fluss flussabwärts ..., geht er flussabwärts, also geht das Boot auch flussabwärts.'::text,'fließt'::text,'floss'::text,'fließen wird'::text,'Wenn ein Fluss flussabwärts fließt, geht er flussabwärts, also geht das Boot auch flussabwärts.'::text),
(355102,39456,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо річка ... вниз за течією, вона йде вниз за течією, тож і човник іде вниз за течією.'::text,'тече'::text,'текла'::text,'потече'::text,'Якщо річка тече вниз за течією, вона йде вниз за течією, тож і човник іде вниз за течією.'::text),
(355101,39456,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un río ... río abajo, va río abajo, así que el barco también va río abajo.'::text,'fluye'::text,'fluyó'::text,'fluirá'::text,'Si un río fluye río abajo, va río abajo, así que el barco también va río abajo.'::text),
(355100,39456,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une rivière ... vers l''aval, elle va vers l''aval, donc le bateau va aussi vers l''aval.'::text,'coule'::text,'coulait'::text,'coulera'::text,'Si une rivière coule vers l''aval, elle va vers l''aval, donc le bateau va aussi vers l''aval.'::text),
(355103,39456,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir nehir akıntı yönünde ..., akıntı yönünde gider, yani kayık da akıntı yönünde gider.'::text,'akarsa'::text,'aktıysa'::text,'akacaksa'::text,'Bir nehir akıntı yönünde akarsa, akıntı yönünde gider, yani kayık da akıntı yönünde gider.'::text),
(355104,39456,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy folyó lefelé ..., akkor lefelé megy, szóval a hajó is lefelé megy.'::text,'folyik'::text,'folyt'::text,'fog folyni'::text,'Ha egy folyó lefelé folyik, akkor lefelé megy, szóval a hajó is lefelé megy.'::text),
(355116,39458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Fluss etwas langsamer fließen würde, ... der Junge sein Boot zurück. Super Stapellauf, klar.'::text,'bekäme'::text,'bekommt'::text,'bekommt'::text,'Wenn der Fluss etwas langsamer fließen würde, bekäme der Junge sein Boot zurück. Super Stapellauf, klar.'::text),
(355120,39458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби річка текла трохи повільніше, хлопчик ... свій човник назад. Чудовий спуск на воду, звісно.'::text,'отримав би'::text,'отримає'::text,'отримує'::text,'Якби річка текла трохи повільніше, хлопчик отримав би свій човник назад. Чудовий спуск на воду, звісно.'::text),
(355119,39458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el río fluyera un poco más despacio, el niño ... su barco. Gran botadura, obviamente.'::text,'recuperaría'::text,'recuperará'::text,'recupera'::text,'Si el río fluyera un poco más despacio, el niño recuperaría su barco. Gran botadura, obviamente.'::text),
(355118,39458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la rivière coulait un peu moins vite, le garçon ... son bateau. Super mise à l''eau, évidemment.'::text,'récupérerait'::text,'récupérera'::text,'récupère'::text,'Si la rivière coulait un peu moins vite, le garçon récupérerait son bateau. Super mise à l''eau, évidemment.'::text),
(355121,39458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nehir biraz daha yavaş aksaydı, çocuk kayığını ...; harika bir suya indirme, tabii ki.'::text,'geri alırdı'::text,'geri alacak'::text,'geri alıyor'::text,'Nehir biraz daha yavaş aksaydı, çocuk kayığını geri alırdı; harika bir suya indirme, tabii ki.'::text),
(355122,39458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a folyó kicsit lassabban folyna, a fiú ... a hajóját. Remek vízre bocsátás, persze.'::text,'visszakapná'::text,'vissza fogja kapni'::text,'visszakapja'::text,'Ha a folyó kicsit lassabban folyna, a fiú visszakapná a hajóját. Remek vízre bocsátás, persze.'::text),
(355125,39459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Papierboot ... vom fließenden Fluss davongetragen.'::text,'wurde'::text,'hat'::text,'wird'::text,'Das Papierboot wurde vom fließenden Fluss davongetragen.'::text),
(355129,39459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Паперовий човник ... геть течією річки.'::text,'був віднесений'::text,'відніс'::text,'відносить'::text,'Паперовий човник був віднесений геть течією річки.'::text),
(355128,39459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco de papel ... por el río que fluía.'::text,'fue arrastrado'::text,'arrastró'::text,'está arrastrando'::text,'El barco de papel fue arrastrado por el río que fluía.'::text),
(355127,39459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bateau en papier ... par la rivière qui coulait.'::text,'a été emporté'::text,'a emporté'::text,'emporte'::text,'Le bateau en papier a été emporté par la rivière qui coulait.'::text),
(355130,39459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâğıt kayık akan nehir tarafından ...'::text,'sürüklenip götürüldü'::text,'sürükleyip götürdü'::text,'sürüklüyor'::text,'Kâğıt kayık akan nehir tarafından sürüklenip götürüldü.'::text),
(355131,39459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A papírhajót ... a sodró folyó.'::text,'elvitte'::text,'elvitte'::text,'viszi'::text,'A papírhajót elvitte a sodró folyó.'::text),
(355134,39460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Flusswasser ... schnell unter der alten Steinbrücke hindurch.'::text,'floss'::text,'floss'::text,'fließend'::text,'Das Flusswasser floss schnell unter der alten Steinbrücke hindurch.'::text),
(355138,39460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода в річці швидко ... під старим кам''яним мостом.'::text,'текла'::text,'текла'::text,'течучи'::text,'Вода в річці швидко текла під старим кам''яним мостом.'::text),
(355137,39460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agua del río ... rápido bajo el viejo puente de piedra.'::text,'fluyó'::text,'fluyó'::text,'fluyendo'::text,'El agua del río fluyó rápido bajo el viejo puente de piedra.'::text),
(355136,39460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''eau de la rivière ... vite sous le vieux pont de pierre.'::text,'coulait'::text,'coulait'::text,'coulant'::text,'L''eau de la rivière coulait vite sous le vieux pont de pierre.'::text),
(355139,39460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nehir suyu eski taş köprünün altından hızla ...'::text,'aktı'::text,'aktı'::text,'akarak'::text,'Nehir suyu eski taş köprünün altından hızla aktı.'::text),
(355140,39460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A folyó vize gyorsan ... a régi kőhíd alatt.'::text,'folyt'::text,'folyt'::text,'folyva'::text,'A folyó vize gyorsan folyt a régi kőhíd alatt.'::text),
(355143,39461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fluss ... hier sehr schnell fließen, weil das Papierboot sofort wegtreibt.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Der Fluss muss hier sehr schnell fließen, weil das Papierboot sofort wegtreibt.'::text),
(355147,39461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Річка тут ... текти дуже швидко, бо паперовий човник одразу відпливає.'::text,'мусить'::text,'не може'::text,'має'::text,'Річка тут мусить текти дуже швидко, бо паперовий човник одразу відпливає.'::text),
(355146,39461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El río ... fluir muy rápido aquí, porque el barco de papel se aleja enseguida.'::text,'debe de'::text,'no puede'::text,'debería'::text,'El río debe de fluir muy rápido aquí, porque el barco de papel se aleja enseguida.'::text),
(355145,39461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rivière ... couler très vite ici, parce que le bateau en papier s''éloigne tout de suite.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'La rivière doit couler très vite ici, parce que le bateau en papier s''éloigne tout de suite.'::text),
(355148,39461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nehir burada çok hızlı ..., çünkü kâğıt kayık hemen uzaklaşıyor.'::text,'akıyor olmalı'::text,'akıyor olamaz'::text,'akmalı'::text,'Nehir burada çok hızlı akıyor olmalı, çünkü kâğıt kayık hemen uzaklaşıyor.'::text),
(355149,39461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A folyónak itt nagyon gyorsan ..., mert a papírhajó azonnal elúszik.'::text,'kell folynia'::text,'nem folyhat'::text,'kellene folynia'::text,'A folyónak itt nagyon gyorsan kell folynia, mert a papírhajó azonnal elúszik.'::text),
(355152,39462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, anscheinend kommt der Fluss, ... unter der Brücke fließt, aus den Bergen.'::text,'der'::text,'der'::text,'wo'::text,'Rate mal, anscheinend kommt der Fluss, der unter der Brücke fließt, aus den Bergen.'::text),
(355156,39462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, річка, ... тече під тим мостом, бере початок у горах.'::text,'яка'::text,'хто'::text,'де'::text,'Уяви, кажуть, річка, яка тече під тим мостом, бере початок у горах.'::text),
(355155,39462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Al parecer el río ... pasa bajo ese puente viene de las montañas.'::text,'que'::text,'quien'::text,'donde'::text,'¿Sabes qué? Al parecer el río que pasa bajo ese puente viene de las montañas.'::text),
(355154,39462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment la rivière ... coule sous ce pont vient des montagnes.'::text,'qui'::text,'qui'::text,'où'::text,'Devine quoi, apparemment la rivière qui coule sous ce pont vient des montagnes.'::text),
(355157,39462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, anlaşılan o köprünün altından ... nehir dağlardan geliyormuş.'::text,'akan'::text,'akan'::text,'aktığı yerdeki'::text,'Bil bakalım, anlaşılan o köprünün altından akan nehir dağlardan geliyormuş.'::text),
(355158,39462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag a folyó, ... az alatt a híd alatt folyik, a hegyekből jön.'::text,'amely'::text,'aki'::text,'ahol'::text,'Képzeld, állítólag a folyó, amely az alatt a híd alatt folyik, a hegyekből jön.'::text),
(356025,39559,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Ausbilder berichtete, dass die Fallschirmspringer eine Ringformation aus etwa zwanzig Personen ...'::text,'gebildet hatten'::text,'gebildet haben'::text,'bilden'::text,'Der Ausbilder berichtete, dass die Fallschirmspringer eine Ringformation aus etwa zwanzig Personen gebildet hatten.'::text),
(356029,39559,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інструктор повідомив, що парашутисти ... кільцеву формацію приблизно з двадцяти осіб.'::text,'утворили'::text,'утворили'::text,'утворюють'::text,'Інструктор повідомив, що парашутисти утворили кільцеву формацію приблизно з двадцяти осіб.'::text),
(356028,39559,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El instructor informó de que los paracaidistas ... una formación en anillo de aproximadamente veinte personas.'::text,'habían formado'::text,'han formado'::text,'forman'::text,'El instructor informó de que los paracaidistas habían formado una formación en anillo de aproximadamente veinte personas.'::text),
(356027,39559,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''instructeur a indiqué que les parachutistes ... une formation en anneau d''environ vingt personnes.'::text,'avaient formé'::text,'ont formé'::text,'forment'::text,'L''instructeur a indiqué que les parachutistes avaient formé une formation en anneau d''environ vingt personnes.'::text),
(356030,39559,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmen, paraşütçülerin yaklaşık yirmi kişilik bir halka formasyonu ... bildirdi.'::text,'oluşturduğunu'::text,'oluşturduğunu'::text,'oluşturduğunu'::text,'Eğitmen, paraşütçülerin yaklaşık yirmi kişilik bir halka formasyonu oluşturduğunu bildirdi.'::text),
(356031,39559,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az oktató jelentette, hogy az ejtőernyősök egy körülbelül húszfős gyűrűalakzatot ...'::text,'alkottak'::text,'alkottak'::text,'alkotnak'::text,'Az oktató jelentette, hogy az ejtőernyősök egy körülbelül húszfős gyűrűalakzatot alkottak.'::text),
(356034,39560,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Fallschirmspringer ... panische Höhenangst, und jetzt fallen sie in Formation!'::text,'hatten früher'::text,'hatten früher'::text,'hatten gewöhnlich'::text,'Diese Fallschirmspringer hatten früher panische Höhenangst, und jetzt fallen sie in Formation!'::text),
(356038,39560,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці парашутисти ... страшенно боялися висоти, а тепер падають у формації!'::text,'колись'::text,'бувало'::text,'звикли'::text,'Ці парашутисти колись страшенно боялися висоти, а тепер падають у формації!'::text),
(356037,39560,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Estos paracaidistas ... tener pánico a las alturas, y ahora caen en formación!'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'¡Estos paracaidistas solían tener pánico a las alturas, y ahora caen en formación!'::text),
(356036,39560,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, ces parachutistes ... une peur bleue du vide, et maintenant ils tombent en formation !'::text,'avaient'::text,'avaient'::text,'étaient habitués à avoir'::text,'Avant, ces parachutistes avaient une peur bleue du vide, et maintenant ils tombent en formation !'::text),
(356039,39560,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu paraşütçüler eskiden yükseklikten ölesiye ..., şimdi ise formasyonda düşüyorlar!'::text,'korkarlardı'::text,'korkarlardı'::text,'korkmaya alışkındı'::text,'Bu paraşütçüler eskiden yükseklikten ölesiye korkarlardı, şimdi ise formasyonda düşüyorlar!'::text),
(356040,39560,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezek az ejtőernyősök régen halálosan ... a magasságtól, most meg alakzatban zuhannak!'::text,'féltek'::text,'féltek'::text,'hozzá voltak szokva, hogy féljenek'::text,'Ezek az ejtőernyősök régen halálosan féltek a magasságtól, most meg alakzatban zuhannak!'::text),
(356043,39561,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigern sich total, die Formation ..., selbst bei voller Geschwindigkeit durch die Wolken!'::text,'aufzulösen'::text,'aufzulösen'::text,'auflösen'::text,'Sie weigern sich total, die Formation aufzulösen, selbst bei voller Geschwindigkeit durch die Wolken!'::text),
(356047,39561,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони категорично відмовляються ... формацію, навіть на повній швидкості крізь хмари!'::text,'порушувати'::text,'порушувати'::text,'порушувати'::text,'Вони категорично відмовляються порушувати формацію, навіть на повній швидкості крізь хмари!'::text),
(356046,39561,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se niegan rotundamente a ... la formación, incluso a toda velocidad entre las nubes!'::text,'romper'::text,'romper'::text,'romper'::text,'¡Se niegan rotundamente a romper la formación, incluso a toda velocidad entre las nubes!'::text),
(356045,39561,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils refusent catégoriquement de ... la formation, même à pleine vitesse à travers les nuages !'::text,'rompre'::text,'rompre'::text,'rompre'::text,'Ils refusent catégoriquement de rompre la formation, même à pleine vitesse à travers les nuages !'::text),
(356048,39561,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bulutların arasından tam hızla geçerken bile formasyonu ... kesinlikle reddediyorlar!'::text,'bozmayı'::text,'bozmayı'::text,'bozmak'::text,'Bulutların arasından tam hızla geçerken bile formasyonu bozmayı kesinlikle reddediyorlar!'::text),
(356049,39561,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyszerűen nem hajlandók ... az alakzatot, még teljes sebességgel a felhőkön át sem!'::text,'felbontani'::text,'felbontani'::text,'felbontani'::text,'Egyszerűen nem hajlandók felbontani az alakzatot, még teljes sebességgel a felhőkön át sem!'::text),
(356052,39562,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fallschirmspringer haben eine perfekte Ringformation gebildet, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die Fallschirmspringer haben eine perfekte Ringformation gebildet, oder?'::text),
(356056,39562,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Парашутисти утворили ідеальну кільцеву формацію, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Парашутисти утворили ідеальну кільцеву формацію, правда?'::text),
(356055,39562,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los paracaidistas hicieron una formación en anillo perfecta, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Los paracaidistas hicieron una formación en anillo perfecta, ¿verdad?'::text),
(356054,39562,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les parachutistes ont fait une formation en anneau parfaite, ... ?'::text,'non'::text,'non'::text,'non'::text,'Les parachutistes ont fait une formation en anneau parfaite, non ?'::text),
(356057,39562,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paraşütçüler kusursuz bir halka formasyonu yaptılar, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Paraşütçüler kusursuz bir halka formasyonu yaptılar, değil mi?'::text),
(356058,39562,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ejtőernyősök tökéletes gyűrűalakzatot alkottak, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Az ejtőernyősök tökéletes gyűrűalakzatot alkottak, ugye?'::text),
(356070,39564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... monatelang, bevor die Ringformation am Himmel endlich klappte.'::text,'trainierten'::text,'trainieren'::text,'trainierten'::text,'Sie trainierten monatelang, bevor die Ringformation am Himmel endlich klappte.'::text),
(356074,39564,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... місяцями, перш ніж кільцева формація нарешті вийшла в небі.'::text,'тренувалися'::text,'тренуються'::text,'тренувалися'::text,'Вони тренувалися місяцями, перш ніж кільцева формація нарешті вийшла в небі.'::text),
(356073,39564,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... durante meses antes de que la formación en anillo por fin saliera bien en el cielo.'::text,'Habían estado entrenando'::text,'Han estado entrenando'::text,'Estaban entrenando'::text,'Habían estado entrenando durante meses antes de que la formación en anillo por fin saliera bien en el cielo.'::text),
(356072,39564,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... pendant des mois avant que la formation en anneau réussisse enfin dans le ciel.'::text,'s''étaient entraînés'::text,'s''entraînent'::text,'s''entraînaient'::text,'Ils s''étaient entraînés pendant des mois avant que la formation en anneau réussisse enfin dans le ciel.'::text),
(356075,39564,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Halka formasyonu gökyüzünde sonunda başarılana kadar aylarca ...'::text,'antrenman yapmışlardı'::text,'antrenman yapıyorlar'::text,'antrenman yapıyorlardı'::text,'Halka formasyonu gökyüzünde sonunda başarılana kadar aylarca antrenman yapmışlardı.'::text),
(356076,39564,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hónapokig ..., mire a gyűrűalakzat végre összejött az égen.'::text,'edzettek'::text,'edzenek'::text,'edzettek'::text,'Hónapokig edzettek, mire a gyűrűalakzat végre összejött az égen.'::text),
(356079,39565,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende dieses Sprungs ... sie eine perfekte Formation, natürlich ganz ohne Training.'::text,'bilden'::text,'bilden'::text,'bilden'::text,'Bis zum Ende dieses Sprungs bilden sie eine perfekte Formation, natürlich ganz ohne Training.'::text),
(356083,39565,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця цього стрибка вони ... ідеальну формацію, звісно ж, без жодних тренувань.'::text,'утворять'::text,'утворять'::text,'утворюють'::text,'До кінця цього стрибка вони утворять ідеальну формацію, звісно ж, без жодних тренувань.'::text),
(356082,39565,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de este salto, ... una formación perfecta, obviamente sin nada de práctica.'::text,'habrán hecho'::text,'harán'::text,'hacen'::text,'Para el final de este salto, habrán hecho una formación perfecta, obviamente sin nada de práctica.'::text),
(356081,39565,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de ce saut, ils ... une formation parfaite, évidemment sans aucun entraînement.'::text,'auront fait'::text,'feront'::text,'font'::text,'D''ici la fin de ce saut, ils auront fait une formation parfaite, évidemment sans aucun entraînement.'::text),
(356084,39565,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu atlayışın sonunda kusursuz bir formasyon ..., tabii ki hiç antrenman yapmadan.'::text,'oluşturmuş olacaklar'::text,'oluşturacaklar'::text,'oluşturuyorlar'::text,'Bu atlayışın sonunda kusursuz bir formasyon oluşturmuş olacaklar, tabii ki hiç antrenman yapmadan.'::text),
(356085,39565,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ugrás végére ... egy tökéletes alakzatot, persze mindenféle gyakorlás nélkül.'::text,'kialakítanak'::text,'ki fognak alakítani'::text,'alakítanak'::text,'Az ugrás végére kialakítanak egy tökéletes alakzatot, persze mindenféle gyakorlás nélkül.'::text),
(356088,39566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn einer losgelassen hätte, ... die Formation komplett im Eimer.'::text,'wäre'::text,'ist'::text,'war'::text,'Bro, wenn einer losgelassen hätte, wäre die Formation komplett im Eimer.'::text),
(356092,39566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби один чувак відпустив руки, формації ... повний капець.'::text,'був би'::text,'буде'::text,'був'::text,'Бро, якби один чувак відпустив руки, формації був би повний капець.'::text),
(356091,39566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si un tío se hubiera soltado, la formación ... un desastre total.'::text,'habría sido'::text,'será'::text,'era'::text,'Bro, si un tío se hubiera soltado, la formación habría sido un desastre total.'::text),
(356090,39566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si un gars avait lâché, la formation ... complètement foutue.'::text,'aurait été'::text,'sera'::text,'était'::text,'Frérot, si un gars avait lâché, la formation aurait été complètement foutue.'::text),
(356093,39566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, biri bıraksaydı formasyon tamamen ...'::text,'mahvolmuş olurdu'::text,'mahvolacak'::text,'mahvoldu'::text,'Kanka, biri bıraksaydı formasyon tamamen mahvolmuş olurdu.'::text),
(356094,39566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha egy srác elengedte volna a kezét, az alakzat ... teljesen oda.'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Tesó, ha egy srác elengedte volna a kezét, az alakzat lett volna teljesen oda.'::text),
(356106,39568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Formation wurde laut Berichten von 20 Fallschirmspringern ..., ein neuer Rekord für das Teamziel.'::text,'gebildet'::text,'bilden'::text,'bildend'::text,'Die Formation wurde laut Berichten von 20 Fallschirmspringern gebildet, ein neuer Rekord für das Teamziel.'::text),
(356110,39568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повідомляють, що формацію ... 20 парашутистів — новий рекорд для командної цілі.'::text,'утворили'::text,'утворюють'::text,'утворення'::text,'Повідомляють, що формацію утворили 20 парашутистів — новий рекорд для командної цілі.'::text),
(356109,39568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según se informa, la formación ... por 20 paracaidistas, un nuevo récord para el objetivo del equipo.'::text,'fue formada'::text,'formar'::text,'formando'::text,'Según se informa, la formación fue formada por 20 paracaidistas, un nuevo récord para el objetivo del equipo.'::text),
(356108,39568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La formation aurait été ... par 20 parachutistes, un nouveau record pour l''objectif de l''équipe.'::text,'réalisée'::text,'réaliser'::text,'réalisant'::text,'La formation aurait été réalisée par 20 parachutistes, un nouveau record pour l''objectif de l''équipe.'::text),
(356111,39568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Formasyonun 20 paraşütçü tarafından ... bildiriliyor; takım hedefi için yeni bir rekor.'::text,'oluşturulduğu'::text,'oluşturmak'::text,'oluşturarak'::text,'Formasyonun 20 paraşütçü tarafından oluşturulduğu bildiriliyor; takım hedefi için yeni bir rekor.'::text),
(356112,39568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelentések szerint az alakzatot 20 ejtőernyős ..., ami új rekord a csapatcélhoz képest.'::text,'alkotta'::text,'alkotni'::text,'alkotva'::text,'A jelentések szerint az alakzatot 20 ejtőernyős alkotta, ami új rekord a csapatcélhoz képest.'::text),
(356115,39569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Fallschirmspringer gab zu, sich der Formation ein paar Sekunden zu spät ...'::text,'angeschlossen zu haben'::text,'anzuschließen'::text,'angeschlossen'::text,'Ein Fallschirmspringer gab zu, sich der Formation ein paar Sekunden zu spät angeschlossen zu haben.'::text),
(356119,39569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один парашутист визнав, що ... до формації на кілька секунд пізно.'::text,'приєднався'::text,'приєднатися'::text,'приєднався'::text,'Один парашутист визнав, що приєднався до формації на кілька секунд пізно.'::text),
(356118,39569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un paracaidista admitió ... a la formación unos segundos tarde.'::text,'haberse unido'::text,'unirse'::text,'se unió'::text,'Un paracaidista admitió haberse unido a la formación unos segundos tarde.'::text),
(356117,39569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un parachutiste a avoué ... la formation quelques secondes trop tard.'::text,'avoir rejoint'::text,'rejoindre'::text,'a rejoint'::text,'Un parachutiste a avoué avoir rejoint la formation quelques secondes trop tard.'::text),
(356120,39569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir paraşütçü formasyona birkaç saniye geç ... itiraf etti.'::text,'katıldığını'::text,'katılmayı'::text,'katıldı'::text,'Bir paraşütçü formasyona birkaç saniye geç katıldığını itiraf etti.'::text),
(356121,39569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik ejtőernyős beismerte, hogy néhány másodperccel túl későn ... az alakzathoz.'::text,'csatlakozott'::text,'csatlakozni'::text,'csatlakozott'::text,'Az egyik ejtőernyős beismerte, hogy néhány másodperccel túl későn csatlakozott az alakzathoz.'::text),
(351768,39086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonntag ... er schon drei Tage lang neue Kekse, um diesen Reinfall wiedergutzumachen.'::text,'backt'::text,'backt'::text,'backt'::text,'Bis Sonntag backt er schon drei Tage lang neue Kekse, um diesen Reinfall wiedergutzumachen.'::text),
(351772,39086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До неділі він ... нове печиво вже три дні, щоб надолужити цей провал.'::text,'пектиме'::text,'пектиме'::text,'спече'::text,'До неділі він пектиме нове печиво вже три дні, щоб надолужити цей провал.'::text),
(351771,39086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el domingo, ... galletas nuevas durante tres días para compensar este fracaso.'::text,'habrá estado horneando'::text,'estará horneando'::text,'horneará'::text,'Para el domingo, habrá estado horneando galletas nuevas durante tres días para compensar este fracaso.'::text),
(351770,39086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici dimanche, il ... de nouveaux biscuits depuis trois jours pour rattraper cet échec.'::text,'aura fait cuire'::text,'fera cuire'::text,'fera cuire'::text,'D''ici dimanche, il aura fait cuire de nouveaux biscuits depuis trois jours pour rattraper cet échec.'::text),
(351773,39086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pazara kadar bu başarısızlığı telafi etmek için üç gündür yeni kurabiye ...'::text,'pişiriyor olacak'::text,'pişiriyor olacak'::text,'pişirecek'::text,'Pazara kadar bu başarısızlığı telafi etmek için üç gündür yeni kurabiye pişiriyor olacak.'::text),
(351774,39086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vasárnapra már három napja ... új kekszeket, hogy jóvátegye ezt a kudarcot.'::text,'fog sütni'::text,'fog sütni'::text,'süt'::text,'Vasárnapra már három napja fog sütni új kekszeket, hogy jóvátegye ezt a kudarcot.'::text),
(351777,39087,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er einen Timer gestellt hätte, ... dieser Reinfall gar nicht erst passiert.'::text,'wäre'::text,'ist'::text,'war'::text,'Wenn er einen Timer gestellt hätte, wäre dieser Reinfall gar nicht erst passiert.'::text),
(351781,39087,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він поставив таймер, цього провалу взагалі ...'::text,'не сталося б'::text,'не станеться'::text,'не сталося'::text,'Якби він поставив таймер, цього провалу взагалі не сталося б.'::text),
(351780,39087,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera puesto un temporizador, este fracaso ... en primer lugar.'::text,'no habría ocurrido'::text,'no ocurrirá'::text,'no ocurrió'::text,'Si hubiera puesto un temporizador, este fracaso no habría ocurrido en primer lugar.'::text),
(351779,39087,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait mis un minuteur, cet échec ... dès le départ.'::text,'ne serait pas arrivé'::text,'n''arrivera pas'::text,'n''est pas arrivé'::text,'S''il avait mis un minuteur, cet échec ne serait pas arrivé dès le départ.'::text),
(351782,39087,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zamanlayıcı kursaydı, bu başarısızlık hiç ...'::text,'yaşanmazdı'::text,'yaşanmayacak'::text,'yaşanmadı'::text,'Zamanlayıcı kursaydı, bu başarısızlık hiç yaşanmazdı.'::text),
(351783,39087,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha beállított volna egy időzítőt, ez a kudarc eleve ...'::text,'nem történt volna meg'::text,'nem fog megtörténni'::text,'nem történt meg'::text,'Ha beállított volna egy időzítőt, ez a kudarc eleve nem történt volna meg.'::text),
(351786,39088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er den Ofen früher kontrolliert hätte, ... er jetzt nicht so fertig wegen dieses Reinfalls.'::text,'wäre'::text,'wäre gewesen'::text,'ist'::text,'Wenn er den Ofen früher kontrolliert hätte, wäre er jetzt nicht so fertig wegen dieses Reinfalls.'::text),
(351790,39088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він перевірив духовку раніше, він ... зараз так засмучений через цей провал.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби він перевірив духовку раніше, він не був би зараз так засмучений через цей провал.'::text),
(351789,39088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera revisado el horno antes, ahora ... tan disgustado por este fracaso.'::text,'no estaría'::text,'no habría estado'::text,'no estará'::text,'Si hubiera revisado el horno antes, ahora no estaría tan disgustado por este fracaso.'::text),
(351788,39088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait vérifié le four plus tôt, il ... si contrarié par cet échec maintenant.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'S''il avait vérifié le four plus tôt, il ne serait pas si contrarié par cet échec maintenant.'::text),
(351791,39088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırını daha önce kontrol etseydi, şimdi bu başarısızlık yüzünden bu kadar üzgün ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Fırını daha önce kontrol etseydi, şimdi bu başarısızlık yüzünden bu kadar üzgün olmazdı.'::text),
(351792,39088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha korábban megnézte volna a sütőt, most ... ennyire kiborulva a kudarc miatt.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha korábban megnézte volna a sütőt, most nem lenne ennyire kiborulva a kudarc miatt.'::text),
(351795,39089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man geht davon aus, dass dieser Misserfolg durch eine 20-minütige Lücke im Backablauf ...'::text,'verursacht wurde'::text,'verursacht wird'::text,'verursachend'::text,'Man geht davon aus, dass dieser Misserfolg durch eine 20-minütige Lücke im Backablauf verursacht wurde.'::text),
(351799,39089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважають, що цей провал ... 20-хвилинна перерва в процесі випікання.'::text,'спричинила'::text,'спричиняє'::text,'спричиняючи'::text,'Вважають, що цей провал спричинила 20-хвилинна перерва в процесі випікання.'::text),
(351798,39089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que este fracaso ... por un hueco de 20 minutos en el flujo de horneado.'::text,'fue causado'::text,'es causado'::text,'causando'::text,'Se cree que este fracaso fue causado por un hueco de 20 minutos en el flujo de horneado.'::text),
(351797,39089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que cet échec ... par un trou de 20 minutes dans le process de cuisson.'::text,'a été causé'::text,'est causé'::text,'causant'::text,'On pense que cet échec a été causé par un trou de 20 minutes dans le process de cuisson.'::text),
(351800,39089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu başarısızlığın, pişirme sürecindeki 20 dakikalık bir boşluktan ... düşünülüyor.'::text,'kaynaklandığı'::text,'kaynaklandığı'::text,'kaynaklanarak'::text,'Bu başarısızlığın, pişirme sürecindeki 20 dakikalık bir boşluktan kaynaklandığı düşünülüyor.'::text),
(351801,39089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vélik, ezt a kudarcot a sütési folyamat egy 20 perces kiesése ...'::text,'okozta'::text,'okozza'::text,'okozva'::text,'Úgy vélik, ezt a kudarcot a sütési folyamat egy 20 perces kiesése okozta.'::text),
(351804,39090,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, die Kekse ..., also war der Reinfall ganz allein seiner.'::text,'verbrannt zu haben'::text,'zu verbrennen'::text,'verbrannt'::text,'Er gab zu, die Kekse verbrannt zu haben, also war der Reinfall ganz allein seiner.'::text),
(351808,39090,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він визнав, що ... печиво, тож провал був його власний.'::text,'спалив'::text,'спалити'::text,'спалив'::text,'Він визнав, що спалив печиво, тож провал був його власний.'::text),
(351807,39090,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... las galletas, así que el fracaso fue solo suyo.'::text,'haber quemado'::text,'quemar'::text,'quemó'::text,'Admitió haber quemado las galletas, así que el fracaso fue solo suyo.'::text),
(351806,39090,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a admis ... les biscuits, donc l''échec était le sien.'::text,'avoir brûlé'::text,'brûler'::text,'a brûlé'::text,'Il a admis avoir brûlé les biscuits, donc l''échec était le sien.'::text),
(351809,39090,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurabiyeleri ... itiraf etti, yani başarısızlık tamamen onundu.'::text,'yaktığını'::text,'yakmayı'::text,'yaktı'::text,'Kurabiyeleri yaktığını itiraf etti, yani başarısızlık tamamen onundu.'::text),
(351810,39090,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy ... a kekszeket, szóval a kudarc az ő hibája volt.'::text,'odaégette'::text,'odaégetni'::text,'odaégette'::text,'Beismerte, hogy odaégette a kekszeket, szóval a kudarc az ő hibája volt.'::text),
(351813,39091,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Misserfolg deutet darauf hin, dass die Kekse erheblich zu lange im Ofen ...'::text,'geblieben sein müssen'::text,'nicht geblieben sein können'::text,'hätten bleiben sollen'::text,'Der Misserfolg deutet darauf hin, dass die Kekse erheblich zu lange im Ofen geblieben sein müssen.'::text),
(351817,39091,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Невдача свідчить, що печиво ... в духовці значно задовго.'::text,'мабуть, пробуло'::text,'не могло пробути'::text,'мало пробути'::text,'Невдача свідчить, що печиво мабуть, пробуло в духовці значно задовго.'::text),
(351816,39091,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El fracaso indica que las galletas ... en el horno considerablemente demasiado tiempo.'::text,'debieron de quedarse'::text,'no pudieron quedarse'::text,'deberían haberse quedado'::text,'El fracaso indica que las galletas debieron de quedarse en el horno considerablemente demasiado tiempo.'::text),
(351815,39091,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''échec indique que les biscuits ... dans le four beaucoup trop longtemps.'::text,'ont dû rester'::text,'n''ont pas pu rester'::text,'auraient dû rester'::text,'L''échec indique que les biscuits ont dû rester dans le four beaucoup trop longtemps.'::text),
(351818,39091,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başarısızlık, kurabiyelerin fırında fazlasıyla uzun süre ... gösteriyor.'::text,'kalmış olması gerektiğini'::text,'kalmış olamayacağını'::text,'kalması gerektiğini'::text,'Başarısızlık, kurabiyelerin fırında fazlasıyla uzun süre kalmış olması gerektiğini gösteriyor.'::text),
(351819,39091,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kudarc arra utal, hogy a kekszek jóval túl sokáig ... a sütőben.'::text,'biztosan maradtak'::text,'nem maradhattak'::text,'kellett volna maradniuk'::text,'A kudarc arra utal, hogy a kekszek jóval túl sokáig biztosan maradtak a sütőben.'::text),
(351822,39092,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... er so einen totalen Reinfall in seiner Küche gesehen.'::text,'hatte'::text,'hatte'::text,'hat'::text,'Noch nie hatte er so einen totalen Reinfall in seiner Küche gesehen.'::text),
(351826,39092,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ще ... такого повного провалу на своїй кухні.'::text,'він не бачив'::text,'він не бачив'::text,'він не бачив'::text,'Ніколи ще він не бачив такого повного провалу на своїй кухні.'::text),
(351825,39092,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... un fracaso tan total en su cocina.'::text,'había visto'::text,'había visto'::text,'vio'::text,'Nunca había visto un fracaso tan total en su cocina.'::text),
(351824,39092,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... un échec aussi total dans sa cuisine.'::text,'il n''avait vu'::text,'il n''avait vu'::text,'il n''a vu'::text,'Jamais il n''avait vu un échec aussi total dans sa cuisine.'::text),
(351827,39092,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfağında hiç böyle tam bir başarısızlık ...'::text,'görmemişti'::text,'görmemişti'::text,'görmedi'::text,'Mutfağında hiç böyle tam bir başarısızlık görmemişti.'::text),
(351828,39092,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még ilyen teljes kudarcot a konyhájában.'::text,'nem látott'::text,'nem látott'::text,'nem látott'::text,'Soha nem látott még ilyen teljes kudarcot a konyhájában.'::text),
(351831,39093,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ein Reinfall ist nichts; lass nächstes Mal deinen Mitbewohner den Ofentimer für dich ...'::text,'stellen'::text,'stellen'::text,'stellen'::text,'Ehrlich, ein Reinfall ist nichts; lass nächstes Mal deinen Mitbewohner den Ofentimer für dich stellen.'::text),
(351835,39093,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, один провал — це дрібниці; наступного разу попроси сусіда ... тобі таймер духовки.'::text,'поставити'::text,'поставити'::text,'поставити'::text,'Чесно, один провал — це дрібниці; наступного разу попроси сусіда поставити тобі таймер духовки.'::text),
(351834,39093,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, un fracaso no es nada; la próxima vez pídele a tu compi de piso que te ... el temporizador del horno.'::text,'ponga'::text,'ponga'::text,'ponga'::text,'Sinceramente, un fracaso no es nada; la próxima vez pídele a tu compi de piso que te ponga el temporizador del horno.'::text),
(351833,39093,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, un échec, c''est rien ; la prochaine fois, demande à ton coloc de te ... le minuteur du four.'::text,'régler'::text,'régler'::text,'régler'::text,'Franchement, un échec, c''est rien ; la prochaine fois, demande à ton coloc de te régler le minuteur du four.'::text),
(351836,39093,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir başarısızlık hiçbir şey değil; bir dahaki sefere ev arkadaşına fırın zamanlayıcısını ...'::text,'kurdur'::text,'kurdur'::text,'kurdur'::text,'Açıkçası, bir başarısızlık hiçbir şey değil; bir dahaki sefere ev arkadaşına fırın zamanlayıcısını kurdur.'::text),
(351837,39093,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egy kudarc semmi; legközelebb kérd meg a lakótársadat, hogy ... be neked a sütő időzítőjét.'::text,'állítsa'::text,'állítsa'::text,'állítsa'::text,'Őszintén, egy kudarc semmi; legközelebb kérd meg a lakótársadat, hogy állítsa be neked a sütő időzítőjét.'::text),
(351849,39095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Blech, ... Kekse schwarz und rissig sind, zeigt einen Reinfall von wirklich makelloser Qualität.'::text,'dessen'::text,'das'::text,'das'::text,'Das Blech, dessen Kekse schwarz und rissig sind, zeigt einen Reinfall von wirklich makelloser Qualität.'::text),
(351853,39095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Деко, ... печиво чорне й потріскане, демонструє провал справді бездоганної якості.'::text,'чиє'::text,'яке'::text,'яке'::text,'Деко, чиє печиво чорне й потріскане, демонструє провал справді бездоганної якості.'::text),
(351852,39095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bandeja, ... galletas están negras y agrietadas, muestra un fracaso de una calidad verdaderamente impecable.'::text,'cuyas'::text,'que'::text,'que'::text,'La bandeja, cuyas galletas están negras y agrietadas, muestra un fracaso de una calidad verdaderamente impecable.'::text),
(351851,39095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La plaque, ... biscuits sont noirs et craquelés, montre un échec d''une qualité vraiment irréprochable.'::text,'dont les'::text,'qui'::text,'que'::text,'La plaque, dont les biscuits sont noirs et craquelés, montre un échec d''une qualité vraiment irréprochable.'::text),
(351854,39095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurabiyeleri kapkara ve çatlak ... tepsi, gerçekten kusursuz kalitede bir başarısızlık sergiliyor.'::text,'olan'::text,'olan'::text,'olan'::text,'Kurabiyeleri kapkara ve çatlak olan tepsi, gerçekten kusursuz kalitede bir başarısızlık sergiliyor.'::text),
(351855,39095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tepsi, ... kekszei feketék és repedezettek, egy igazán hibátlan minőségű kudarcot mutat.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A tepsi, amelynek a kekszei feketék és repedezettek, egy igazán hibátlan minőségű kudarcot mutat.'::text),
(351858,39096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, ... gehört zum Backen dazu. Dieses schwarze Blech ist ein echtes Meisterwerk.'::text,'Scheitern'::text,'ein Scheitern'::text,'das Scheitern'::text,'Klar, Scheitern gehört zum Backen dazu. Dieses schwarze Blech ist ein echtes Meisterwerk.'::text),
(351862,39096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, ... — частина випікання. Це чорне деко — справжній шедевр.'::text,'провал'::text,'провал'::text,'провал'::text,'Звісно, провал — частина випікання. Це чорне деко — справжній шедевр.'::text),
(351861,39096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, ... forma parte de hornear. Esta bandeja negra es una auténtica obra maestra.'::text,'el fracaso'::text,'un fracaso'::text,'el fracaso'::text,'Obviamente, el fracaso forma parte de hornear. Esta bandeja negra es una auténtica obra maestra.'::text),
(351860,39096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, ... fait partie de la pâtisserie. Cette plaque noire est un vrai chef-d''œuvre.'::text,'l''échec'::text,'un échec'::text,'l''échec'::text,'Évidemment, l''échec fait partie de la pâtisserie. Cette plaque noire est un vrai chef-d''œuvre.'::text),
(351863,39096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki ... pişirmenin bir parçası. Bu kapkara tepsi gerçek bir başyapıt.'::text,'başarısızlık'::text,'bir başarısızlık'::text,'başarısızlık'::text,'Tabii ki başarısızlık pişirmenin bir parçası. Bu kapkara tepsi gerçek bir başyapıt.'::text),
(351864,39096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze ... a sütés része. Ez a fekete tepsi igazi mestermű.'::text,'a kudarc'::text,'egy kudarc'::text,'a kudarc'::text,'Persze a kudarc a sütés része. Ez a fekete tepsi igazi mestermű.'::text),
(355890,39544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seinem Freund früher verzeihen sollen, denn sie wollten beide eindeutig diese Umarmung.'::text,'hätte'::text,'muss'::text,'konnte'::text,'Er hätte seinem Freund früher verzeihen sollen, denn sie wollten beide eindeutig diese Umarmung.'::text),
(355894,39544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... другові раніше, бо вони обидва явно хотіли цих обіймів.'::text,'мав пробачити'::text,'мабуть, пробачив'::text,'міг пробачити'::text,'Він мав пробачити другові раніше, бо вони обидва явно хотіли цих обіймів.'::text),
(355893,39544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... a su amigo antes, porque los dos claramente querían ese abrazo.'::text,'debería haber perdonado'::text,'debió de perdonar'::text,'podía perdonar'::text,'Él debería haber perdonado a su amigo antes, porque los dos claramente querían ese abrazo.'::text),
(355892,39544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à son ami plus tôt, parce qu''ils voulaient clairement tous les deux ce câlin.'::text,'aurait dû pardonner'::text,'a dû pardonner'::text,'pouvait pardonner'::text,'Il aurait dû pardonner à son ami plus tôt, parce qu''ils voulaient clairement tous les deux ce câlin.'::text),
(355895,39544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşını daha önce ..., çünkü ikisi de o sarılmayı açıkça istiyordu.'::text,'affetmeliydi'::text,'affetmiş olmalı'::text,'affedebilirdi'::text,'Arkadaşını daha önce affetmeliydi, çünkü ikisi de o sarılmayı açıkça istiyordu.'::text),
(355896,39544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előbb ... a barátjának, mert egyértelműen mindketten akarták azt az ölelést.'::text,'meg kellett volna bocsátania'::text,'biztosan megbocsátott'::text,'megbocsáthatott'::text,'Előbb meg kellett volna bocsátania a barátjának, mert egyértelműen mindketten akarták azt az ölelést.'::text),
(355899,39545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst als sein Freund alles erklärt hatte, ... er zu, ihm zu verzeihen.'::text,'stimmte'::text,'stimmte'::text,'stimmte'::text,'Erst als sein Freund alles erklärt hatte, stimmte er zu, ihm zu verzeihen.'::text),
(355903,39545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише коли друг усе пояснив, ... пробачити йому.'::text,'він погодився'::text,'він погодився'::text,'він погодився'::text,'Лише коли друг усе пояснив, він погодився пробачити йому.'::text),
(355902,39545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo cuando su amigo se lo explicó todo, ... perdonarlo.'::text,'aceptó'::text,'aceptó'::text,'aceptó'::text,'Solo cuando su amigo se lo explicó todo, aceptó perdonarlo.'::text),
(355901,39545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est qu''une fois que son ami a tout expliqué ... de lui pardonner.'::text,'qu''il a accepté'::text,'qu''il a accepté'::text,'qu''il a accepté'::text,'Ce n''est qu''une fois que son ami a tout expliqué qu''il a accepté de lui pardonner.'::text),
(355904,39545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı her şeyi açıkladıktan sonra ancak onu affetmeyi ...'::text,'kabul etti'::text,'kabul etti'::text,'kabul etti'::text,'Arkadaşı her şeyi açıkladıktan sonra ancak onu affetmeyi kabul etti.'::text),
(355905,39545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak miután a barátja mindent elmagyarázott, ... bele, hogy megbocsát neki.'::text,'egyezett'::text,'egyezett'::text,'egyezett'::text,'Csak miután a barátja mindent elmagyarázott, egyezett bele, hogy megbocsát neki.'::text),
(355908,39546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann brachte seinen Freund schließlich dazu, ihm zu ..., ein Prozess, der typischerweise Zeit braucht.'::text,'verzeihen'::text,'verzeihen'::text,'verzeihen'::text,'Der junge Mann brachte seinen Freund schließlich dazu, ihm zu verzeihen, ein Prozess, der typischerweise Zeit braucht.'::text),
(355912,39546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець зрештою домігся, щоб друг ... йому, — процес, який зазвичай потребує часу.'::text,'пробачив'::text,'пробачив'::text,'пробачив'::text,'Хлопець зрештою домігся, щоб друг пробачив йому, — процес, який зазвичай потребує часу.'::text),
(355911,39546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven consiguió finalmente que su amigo lo ..., un proceso que normalmente requiere tiempo.'::text,'perdonara'::text,'perdonara'::text,'perdonara'::text,'El joven consiguió finalmente que su amigo lo perdonara, un proceso que normalmente requiere tiempo.'::text),
(355910,39546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme a fini par amener son ami à lui ..., un processus qui demande généralement du temps.'::text,'pardonner'::text,'pardonner'::text,'pardonner'::text,'Le jeune homme a fini par amener son ami à lui pardonner, un processus qui demande généralement du temps.'::text),
(355913,39546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam sonunda arkadaşının kendisini ... sağladı; bu, genellikle zaman gerektiren bir süreçtir.'::text,'affetmesini'::text,'affetmesini'::text,'affetmesini'::text,'Genç adam sonunda arkadaşının kendisini affetmesini sağladı; bu, genellikle zaman gerektiren bir süreçtir.'::text),
(355914,39546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember végül elérte, hogy a barátja ... neki, ami egy jellemzően időigényes folyamat.'::text,'megbocsásson'::text,'megbocsásson'::text,'megbocsásson'::text,'A fiatalember végül elérte, hogy a barátja megbocsásson neki, ami egy jellemzően időigényes folyamat.'::text),
(355926,39548,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein bester Freund, ... Entschuldigung seinen Stolz fast zerstört hat, hat endlich Vergebung bekommen!'::text,'dessen'::text,'die'::text,'der'::text,'Sein bester Freund, dessen Entschuldigung seinen Stolz fast zerstört hat, hat endlich Vergebung bekommen!'::text),
(355930,39548,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його найкращому другові, ... вибачення мало не знищило його гордість, нарешті пробачили!'::text,'чиє'::text,'яке'::text,'хто'::text,'Його найкращому другові, чиє вибачення мало не знищило його гордість, нарешті пробачили!'::text),
(355929,39548,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su mejor amigo, ... disculpa casi destruyó su orgullo, por fin fue perdonado!'::text,'cuya'::text,'que'::text,'quien'::text,'¡Su mejor amigo, cuya disculpa casi destruyó su orgullo, por fin fue perdonado!'::text),
(355928,39548,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son meilleur ami, ... les excuses ont failli détruire sa fierté, a enfin été pardonné !'::text,'dont'::text,'que'::text,'qui'::text,'Son meilleur ami, dont les excuses ont failli détruire sa fierté, a enfin été pardonné !'::text),
(355931,39548,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Özrü neredeyse gururunu yerle bir ... en yakın arkadaşı sonunda affedildi!'::text,'eden'::text,'eden'::text,'eden'::text,'Özrü neredeyse gururunu yerle bir eden en yakın arkadaşı sonunda affedildi!'::text),
(355932,39548,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legjobb barátja, ... bocsánatkérése majdnem tönkretette a büszkeségét, végre bocsánatot kapott!'::text,'akinek a'::text,'amely'::text,'aki'::text,'A legjobb barátja, akinek a bocsánatkérése majdnem tönkretette a büszkeségét, végre bocsánatot kapott!'::text),
(355935,39549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seines komplett zerstörten Stolzes verzieh er seinem besten Freund!'::text,'Trotz'::text,'Obwohl'::text,'Im Falle'::text,'Trotz seines komplett zerstörten Stolzes verzieh er seinem besten Freund!'::text),
(355939,39549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... свою геть зруйновану гордість, він пробачив найкращому другові!'::text,'Попри'::text,'Хоча'::text,'У разі'::text,'Попри свою геть зруйновану гордість, він пробачив найкращому другові!'::text),
(355938,39549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... su orgullo completamente destrozado, perdonó a su mejor amigo!'::text,'A pesar de'::text,'Aunque'::text,'En caso de'::text,'¡A pesar de su orgullo completamente destrozado, perdonó a su mejor amigo!'::text),
(355937,39549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sa fierté complètement brisée, il a pardonné à son meilleur ami !'::text,'Malgré'::text,'Bien que'::text,'En cas de'::text,'Malgré sa fierté complètement brisée, il a pardonné à son meilleur ami !'::text),
(355940,39549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamamen yerle bir olmuş gururuna ..., en yakın arkadaşını affetti!'::text,'rağmen'::text,'olsa da'::text,'durumunda'::text,'Tamamen yerle bir olmuş gururuna rağmen, en yakın arkadaşını affetti!'::text),
(355941,39549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen összetört büszkesége ... megbocsátott a legjobb barátjának!'::text,'ellenére'::text,'bár'::text,'esetén'::text,'Teljesen összetört büszkesége ellenére megbocsátott a legjobb barátjának!'::text),
(355944,39550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass er seinem Freund bis zum Ende des Tages ..., und das hat er!'::text,'verzeihen würde'::text,'verzeihen wird'::text,'verzeiht'::text,'Hör mal, ich hab gehört, dass er seinem Freund bis zum Ende des Tages verzeihen würde, und das hat er!'::text),
(355948,39550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що він ... другові до кінця дня, і він пробачив!'::text,'пробачить'::text,'пробачить'::text,'пробачає'::text,'Слухай, я чула, що він пробачить другові до кінця дня, і він пробачив!'::text),
(355947,39550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijeron que ... a su amigo antes de que acabara el día, ¡y lo hizo!'::text,'perdonaría'::text,'perdonará'::text,'perdona'::text,'Oye, me dijeron que perdonaría a su amigo antes de que acabara el día, ¡y lo hizo!'::text),
(355946,39550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''il ... à son ami avant la fin de la journée, et c''est ce qu''il a fait !'::text,'pardonnerait'::text,'pardonnera'::text,'pardonne'::text,'Écoute, j''ai entendu dire qu''il pardonnerait à son ami avant la fin de la journée, et c''est ce qu''il a fait !'::text),
(355949,39550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki gün bitmeden arkadaşını ... ve affetti de!'::text,'affedecekmiş'::text,'affedecek'::text,'affediyor'::text,'Dinle, duydum ki gün bitmeden arkadaşını affedecekmiş ve affetti de!'::text),
(355950,39550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a nap végéig ... a barátjának, és így is lett!'::text,'megbocsát'::text,'meg fog bocsátani'::text,'megbocsát'::text,'Figyelj, azt hallottam, hogy a nap végéig megbocsát a barátjának, és így is lett!'::text),
(355953,39551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... er seinem Freund inzwischen, also umarmen sie sich wieder.'::text,'verzeiht'::text,'verzeiht'::text,'verzeiht'::text,'Bestie, angeblich verzeiht er seinem Freund inzwischen, also umarmen sie sich wieder.'::text),
(355957,39551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він уже ... другові, тож вони знову обіймаються.'::text,'пробачив'::text,'пробачає'::text,'пробачає'::text,'Подруго, кажуть, він уже пробачив другові, тож вони знову обіймаються.'::text),
(355956,39551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, al parecer ya ... a su amigo, así que vuelven a abrazarse.'::text,'ha perdonado'::text,'está perdonando'::text,'perdona'::text,'Bestie, al parecer ya ha perdonado a su amigo, así que vuelven a abrazarse.'::text),
(355955,39551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma best, apparemment il ... à son ami maintenant, du coup ils se refont des câlins.'::text,'a pardonné'::text,'pardonne'::text,'pardonne'::text,'Ma best, apparemment il a pardonné à son ami maintenant, du coup ils se refont des câlins.'::text),
(355958,39551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan artık arkadaşını ..., o yüzden yine sarılıyorlar.'::text,'affetmiş'::text,'affediyor'::text,'affeder'::text,'Kanka, anlaşılan artık arkadaşını affetmiş, o yüzden yine sarılıyorlar.'::text),
(355959,39551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, állítólag már ... a barátjának, úgyhogy megint ölelkeznek.'::text,'megbocsátott'::text,'megbocsát'::text,'megbocsát'::text,'Bestie, állítólag már megbocsátott a barátjának, úgyhogy megint ölelkeznek.'::text),
(355962,39552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, dass er seinen Freund eine Woche lang ..., bevor er ihm endlich verziehen hat.'::text,'ignoriert hatte'::text,'ignoriert'::text,'ignorierte'::text,'Okay, also ich hab gehört, dass er seinen Freund eine Woche lang ignoriert hatte, bevor er ihm endlich verziehen hat.'::text),
(355966,39552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, я чула, що він ... друга цілий тиждень, поки нарешті не пробачив йому.'::text,'ігнорував'::text,'ігнорує'::text,'ігнорував'::text,'Короче, я чула, що він ігнорував друга цілий тиждень, поки нарешті не пробачив йому.'::text),
(355965,39552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me han dicho que ... a su amigo durante una semana antes de perdonarlo por fin.'::text,'había estado ignorando'::text,'ha estado ignorando'::text,'ignoró'::text,'Vale, pues me han dicho que había estado ignorando a su amigo durante una semana antes de perdonarlo por fin.'::text),
(355964,39552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, alors j''ai entendu dire qu''il ... son ami pendant une semaine avant de finalement lui pardonner.'::text,'avait ignoré'::text,'ignore'::text,'a ignoré'::text,'Ok, alors j''ai entendu dire qu''il avait ignoré son ami pendant une semaine avant de finalement lui pardonner.'::text),
(355967,39552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duydum ki sonunda affetmeden önce arkadaşını bir hafta boyunca ...'::text,'görmezden gelmiş'::text,'görmezden geliyor'::text,'görmezden geldi'::text,'Tamam, duydum ki sonunda affetmeden önce arkadaşını bir hafta boyunca görmezden gelmiş.'::text),
(355968,39552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval azt hallottam, hogy egy hétig ... a barátját, mielőtt végre megbocsátott neki.'::text,'ignorálta'::text,'ignorálja'::text,'ignorálta'::text,'Oké, szóval azt hallottam, hogy egy hétig ignorálta a barátját, mielőtt végre megbocsátott neki.'::text),
(355971,39553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... er seinem Freund den Streit komplett.'::text,'verzeiht'::text,'verzeiht'::text,'verzeiht'::text,'Bis heute Abend verzeiht er seinem Freund den Streit komplett.'::text),
(355975,39553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... другові сварку повністю.'::text,'пробачить'::text,'пробачить'::text,'пробачає'::text,'До вечора він пробачить другові сварку повністю.'::text),
(355974,39553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ya ... por completo a su amigo por la discusión.'::text,'habrá perdonado'::text,'perdonará'::text,'perdona'::text,'Para esta noche, ya habrá perdonado por completo a su amigo por la discusión.'::text),
(355973,39553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... complètement à son ami pour la dispute.'::text,'aura pardonné'::text,'pardonnera'::text,'pardonne'::text,'D''ici ce soir, il aura pardonné complètement à son ami pour la dispute.'::text),
(355976,39553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar arkadaşını kavga için tamamen ...'::text,'affetmiş olacak'::text,'affedecek'::text,'affediyor'::text,'Bu akşama kadar arkadaşını kavga için tamamen affetmiş olacak.'::text),
(355977,39553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére teljesen ... a barátjának a vitát.'::text,'megbocsátja'::text,'meg fogja bocsátani'::text,'megbocsátja'::text,'Estére teljesen megbocsátja a barátjának a vitát.'::text),
(377157,41907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler ... schon seit fünf Minuten gegen die Gelbe Karte.'::text,'protestiert'::text,'protestiert'::text,'protestiert'::text,'Der Spieler protestiert schon seit fünf Minuten gegen die Gelbe Karte.'::text),
(377161,41907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець ... проти жовтої картки вже п''ять хвилин.'::text,'протестує'::text,'протестує'::text,'протестує'::text,'Гравець протестує проти жовтої картки вже п''ять хвилин.'::text),
(377160,41907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador ... por la tarjeta amarilla desde hace cinco minutos.'::text,'está protestando'::text,'está protestando'::text,'protesta'::text,'El jugador está protestando por la tarjeta amarilla desde hace cinco minutos.'::text),
(377159,41907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur ... contre le carton jaune depuis cinq minutes.'::text,'proteste'::text,'proteste'::text,'proteste'::text,'Le joueur proteste contre le carton jaune depuis cinq minutes.'::text),
(377162,41907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncu beş dakikadır sarı karta ...'::text,'itiraz ediyor'::text,'itiraz ediyor'::text,'itiraz eder'::text,'Oyuncu beş dakikadır sarı karta itiraz ediyor.'::text),
(377163,41907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos már öt perce ... a sárga lap miatt.'::text,'tiltakozik'::text,'tiltakozik'::text,'tiltakozik'::text,'A játékos már öt perce tiltakozik a sárga lap miatt.'::text),
(377166,41908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler ..., sobald das Foul geschah, und hob dabei beide Handflächen.'::text,'protestierte'::text,'protestierte gerade'::text,'protestierte'::text,'Der Spieler protestierte, sobald das Foul geschah, und hob dabei beide Handflächen.'::text),
(377170,41908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець ..., щойно стався фол, піднявши обидві долоні.'::text,'запротестував'::text,'протестував'::text,'запротестував'::text,'Гравець запротестував, щойно стався фол, піднявши обидві долоні.'::text),
(377169,41908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador ... en cuanto se produjo la falta, levantando ambas palmas.'::text,'protestó'::text,'estaba protestando'::text,'ha protestado'::text,'El jugador protestó en cuanto se produjo la falta, levantando ambas palmas.'::text),
(377168,41908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur ... dès que la faute a eu lieu, en levant les deux paumes.'::text,'a protesté'::text,'protestait'::text,'a protesté'::text,'Le joueur a protesté dès que la faute a eu lieu, en levant les deux paumes.'::text),
(377171,41908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncu, faul olur olmaz iki avucunu kaldırarak ...'::text,'itiraz etti'::text,'itiraz ediyordu'::text,'itiraz etmiş'::text,'Oyuncu, faul olur olmaz iki avucunu kaldırarak itiraz etti.'::text),
(377172,41908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos ..., amint a szabálytalanság megtörtént, mindkét tenyerét felemelve.'::text,'tiltakozott'::text,'tiltakozott'::text,'tiltakozott'::text,'A játékos tiltakozott, amint a szabálytalanság megtörtént, mindkét tenyerét felemelve.'::text),
(377175,41909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat schon dreimal ..., und die Schiedsrichterin ignoriert ihn komplett!'::text,'protestiert'::text,'protestiert'::text,'protestiert'::text,'Er hat schon dreimal protestiert, und die Schiedsrichterin ignoriert ihn komplett!'::text),
(377179,41909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже ... тричі, а суддя його повністю ігнорує!'::text,'протестував'::text,'протестував'::text,'протестував'::text,'Він уже протестував тричі, а суддя його повністю ігнорує!'::text),
(377178,41909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ya ... tres veces y la árbitra lo está ignorando por completo!'::text,'ha protestado'::text,'ha estado protestando'::text,'protestó'::text,'¡Ya ha protestado tres veces y la árbitra lo está ignorando por completo!'::text),
(377177,41909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... déjà trois fois, et l''arbitre l''ignore complètement !'::text,'a protesté'::text,'proteste'::text,'a protesté'::text,'Il a protesté déjà trois fois, et l''arbitre l''ignore complètement !'::text),
(377180,41909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiden üç kez ... ve hakem onu tamamen görmezden geliyor!'::text,'itiraz etti'::text,'itiraz ediyor'::text,'itiraz etti'::text,'Şimdiden üç kez itiraz etti ve hakem onu tamamen görmezden geliyor!'::text),
(377181,41909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már háromszor ..., és a játékvezető teljesen levegőnek nézi!'::text,'tiltakozott'::text,'tiltakozik'::text,'tiltakozott'::text,'Már háromszor tiltakozott, és a játékvezető teljesen levegőnek nézi!'::text),
(377193,41911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch einmal protestiert, ... die Schiedsrichterin ihn vom Platz! Game over!'::text,'schickt'::text,'schickte'::text,'schickte'::text,'Wenn er noch einmal protestiert, schickt die Schiedsrichterin ihn vom Platz! Game over!'::text),
(377197,41911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він ще раз запротестує, суддя його ...! Гру закінчено!'::text,'вилучить'::text,'вилучила б'::text,'вилучила'::text,'Якщо він ще раз запротестує, суддя його вилучить! Гру закінчено!'::text),
(377196,41911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si protesta una vez más, la árbitra lo ...! ¡Se acabó el partido!'::text,'expulsará'::text,'expulsaría'::text,'expulsó'::text,'¡Si protesta una vez más, la árbitra lo expulsará! ¡Se acabó el partido!'::text),
(377195,41911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il proteste encore une fois, l''arbitre ... du terrain ! Game over !'::text,'l''expulsera'::text,'l''expulserait'::text,'l''a expulsé'::text,'S''il proteste encore une fois, l''arbitre l''expulsera du terrain ! Game over !'::text),
(377198,41911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kez daha itiraz ederse hakem onu oyundan ...! Oyun bitti!'::text,'atacak'::text,'atardı'::text,'attı'::text,'Bir kez daha itiraz ederse hakem onu oyundan atacak! Oyun bitti!'::text),
(377199,41911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egyszer tiltakozik, a játékvezető ... a pályáról! Vége a meccsnek!'::text,'leküldi'::text,'leküldené'::text,'leküldte'::text,'Ha még egyszer tiltakozik, a játékvezető leküldi a pályáról! Vége a meccsnek!'::text),
(377202,41912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er aufhören würde zu protestieren, ... die Schiedsrichterin ihn weiterspielen.'::text,'ließe'::text,'lässt'::text,'lässt'::text,'Wenn er aufhören würde zu protestieren, ließe die Schiedsrichterin ihn weiterspielen.'::text),
(377206,41912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він перестав протестувати, суддя ... йому грати далі.'::text,'дозволила б'::text,'дозволить'::text,'дозволяє'::text,'Якби він перестав протестувати, суддя дозволила б йому грати далі.'::text),
(377205,41912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si dejara de protestar, la árbitra lo ... seguir jugando.'::text,'dejaría'::text,'dejará'::text,'deja'::text,'Si dejara de protestar, la árbitra lo dejaría seguir jugando.'::text),
(377204,41912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il arrêtait de protester, l''arbitre le ... continuer à jouer.'::text,'laisserait'::text,'laissera'::text,'laisse'::text,'S''il arrêtait de protester, l''arbitre le laisserait continuer à jouer.'::text),
(377207,41912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İtiraz etmeyi bıraksa, hakem onun oynamaya devam etmesine ...'::text,'izin verirdi'::text,'izin verecek'::text,'izin veriyor'::text,'İtiraz etmeyi bıraksa, hakem onun oynamaya devam etmesine izin verirdi.'::text),
(377208,41912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha abbahagyná a tiltakozást, a játékvezető ... tovább játszani.'::text,'hagyná'::text,'hagyni fogja'::text,'hagyja'::text,'Ha abbahagyná a tiltakozást, a játékvezető hagyná tovább játszani.'::text),
(377211,41913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend ... ihm eine Gelbe Karte gezeigt, weil er zu viel protestiert hat.'::text,'wurde'::text,'hat'::text,'wird'::text,'Girl, anscheinend wurde ihm eine Gelbe Karte gezeigt, weil er zu viel protestiert hat.'::text),
(377215,41913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, йому ... жовту картку, бо він забагато протестував.'::text,'показали'::text,'показала'::text,'показує'::text,'Подруго, кажуть, йому показали жовту картку, бо він забагато протестував.'::text),
(377214,41913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer le ... una tarjeta amarilla porque protestó demasiado.'::text,'mostraron'::text,'mostró'::text,'está mostrando'::text,'Tía, al parecer le mostraron una tarjeta amarilla porque protestó demasiado.'::text),
(377213,41913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment un carton jaune lui ... parce qu''il a trop protesté.'::text,'a été montré'::text,'a montré'::text,'montre'::text,'Meuf, apparemment un carton jaune lui a été montré parce qu''il a trop protesté.'::text),
(377216,41913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan çok itiraz ettiği için ona sarı kart ...'::text,'gösterilmiş'::text,'göstermiş'::text,'gösteriyor'::text,'Kızım, anlaşılan çok itiraz ettiği için ona sarı kart gösterilmiş.'::text),
(377217,41913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag sárga lapot ... neki, mert túl sokat tiltakozott.'::text,'mutattak fel'::text,'mutatott fel'::text,'mutat fel'::text,'Csajszi, állítólag sárga lapot mutattak fel neki, mert túl sokat tiltakozott.'::text),
(377220,41914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass der Spieler ewig ..., nachdem die Schiedsrichterin die Karte gezeigt hatte.'::text,'protestiert hat'::text,'protestiert hat'::text,'protestierend'::text,'Hör mal, ich hab gehört, dass der Spieler ewig protestiert hat, nachdem die Schiedsrichterin die Karte gezeigt hatte.'::text),
(377224,41914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що гравець ... цілу вічність після того, як суддя показала картку.'::text,'протестував'::text,'протестував'::text,'протестуючи'::text,'Слухай, я чула, що гравець протестував цілу вічність після того, як суддя показала картку.'::text),
(377223,41914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que el jugador ... un montón después de que la árbitra sacara la tarjeta.'::text,'protestó'::text,'protestó'::text,'protestando'::text,'Oye, me han dicho que el jugador protestó un montón después de que la árbitra sacara la tarjeta.'::text),
(377222,41914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que le joueur ... pendant des lustres après que l''arbitre a montré le carton.'::text,'a protesté'::text,'a protesté'::text,'protestant'::text,'Écoute, j''ai entendu dire que le joueur a protesté pendant des lustres après que l''arbitre a montré le carton.'::text),
(377225,41914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki hakem kartı gösterdikten sonra oyuncu uzun süre ...'::text,'itiraz etmiş'::text,'itiraz etmiş'::text,'itiraz ederek'::text,'Dinle, duydum ki hakem kartı gösterdikten sonra oyuncu uzun süre itiraz etmiş.'::text),
(377226,41914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a játékos még sokáig ..., miután a játékvezető felmutatta a lapot.'::text,'tiltakozott'::text,'tiltakozott'::text,'tiltakozva'::text,'Figyelj, azt hallottam, hogy a játékos még sokáig tiltakozott, miután a játékvezető felmutatta a lapot.'::text),
(377229,41915,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... die entspannteste Schiedsrichterin aller Zeiten sein, so wie du sein ganzes Protestieren ignorierst.'::text,'musst'::text,'kannst nicht'::text,'musst nicht'::text,'Ehrlich, du musst die entspannteste Schiedsrichterin aller Zeiten sein, so wie du sein ganzes Protestieren ignorierst.'::text),
(377233,41915,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... бути найспокійнішою суддею в історії, як ти ігноруєш усі його протести.'::text,'маєш'::text,'не можеш'::text,'можеш і не'::text,'Чесно, ти маєш бути найспокійнішою суддею в історії, як ти ігноруєш усі його протести.'::text),
(377232,41915,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... ser la árbitra más tranquila del mundo, por cómo ignoras todas sus protestas.'::text,'debes de'::text,'no puedes'::text,'podrías no'::text,'Sinceramente, tú debes de ser la árbitra más tranquila del mundo, por cómo ignoras todas sus protestas.'::text),
(377231,41915,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... être l''arbitre la plus calme du monde, vu comment tu ignores toutes ses protestations.'::text,'dois'::text,'ne peux pas'::text,'pourrais ne pas'::text,'Franchement, tu dois être l''arbitre la plus calme du monde, vu comment tu ignores toutes ses protestations.'::text),
(377234,41915,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, gelmiş geçmiş en sakin hakem ..., bütün itirazlarını görmezden gelişine bakılırsa.'::text,'olmalısın'::text,'olamazsın'::text,'olmayabilirsin'::text,'Açıkçası, gelmiş geçmiş en sakin hakem olmalısın, bütün itirazlarını görmezden gelişine bakılırsa.'::text),
(377235,41915,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... te vagy a valaha volt legnyugodtabb játékvezető, ahogy levegőnek nézed az összes tiltakozását.'::text,'biztosan'::text,'biztosan nem'::text,'talán nem'::text,'Őszintén, biztosan te vagy a valaha volt legnyugodtabb játékvezető, ahogy levegőnek nézed az összes tiltakozását.'::text),
(377238,41916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler, ... so laut protestiert hat, bekam eine Gelbe Karte.'::text,'der'::text,'der'::text,'dessen'::text,'Der Spieler, der so laut protestiert hat, bekam eine Gelbe Karte.'::text),
(377242,41916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець, ... так голосно протестував, отримав жовту картку.'::text,'який'::text,'що'::text,'чий'::text,'Гравець, який так голосно протестував, отримав жовту картку.'::text),
(377241,41916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador ... protestó tan fuerte recibió una tarjeta amarilla.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El jugador que protestó tan fuerte recibió una tarjeta amarilla.'::text),
(377240,41916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur ... a protesté si fort a pris un carton jaune.'::text,'qui'::text,'lequel'::text,'dont'::text,'Le joueur qui a protesté si fort a pris un carton jaune.'::text),
(377243,41916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar yüksek sesle ... oyuncu sarı kart gördü.'::text,'itiraz eden'::text,'itiraz eden'::text,'itiraz ettiği'::text,'O kadar yüksek sesle itiraz eden oyuncu sarı kart gördü.'::text),
(377244,41916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos, ... olyan hangosan tiltakozott, sárga lapot kapott.'::text,'aki'::text,'amely'::text,'akinek a'::text,'A játékos, aki olyan hangosan tiltakozott, sárga lapot kapott.'::text),
(377247,41917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler sagte, dass er nichts falsch ..., also protestierte er.'::text,'gemacht hatte'::text,'gemacht hat'::text,'macht'::text,'Der Spieler sagte, dass er nichts falsch gemacht hatte, also protestierte er.'::text),
(377251,41917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець сказав, що ... нічого поганого, тож він протестував.'::text,'не зробив'::text,'не зробив'::text,'не робить'::text,'Гравець сказав, що не зробив нічого поганого, тож він протестував.'::text),
(377250,41917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador dijo que no ... nada malo, así que protestó.'::text,'había hecho'::text,'ha hecho'::text,'hace'::text,'El jugador dijo que no había hecho nada malo, así que protestó.'::text),
(377249,41917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur a dit qu''il ... de mal, alors il a protesté.'::text,'n''avait rien fait'::text,'n''a rien fait'::text,'ne fait rien'::text,'Le joueur a dit qu''il n''avait rien fait de mal, alors il a protesté.'::text),
(377252,41917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncu hiçbir yanlış ... söyledi, bu yüzden itiraz etti.'::text,'yapmadığını'::text,'yapmadığını'::text,'yapmadığını'::text,'Oyuncu hiçbir yanlış yapmadığını söyledi, bu yüzden itiraz etti.'::text),
(377253,41917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos azt mondta, hogy ... semmi rosszat, ezért tiltakozott.'::text,'nem tett'::text,'nem tett'::text,'nem tesz'::text,'A játékos azt mondta, hogy nem tett semmi rosszat, ezért tiltakozott.'::text),
(356259,39585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächste Woche um diese Zeit ... er wegen eines winzigen Bruchs diesen schweren Gips! Ein Albtraum!'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Nächste Woche um diese Zeit trägt er wegen eines winzigen Bruchs diesen schweren Gips! Ein Albtraum!'::text),
(356263,39585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного тижня в цей час він ... цей важкий гіпс через один крихітний перелом! Жах!'::text,'носитиме'::text,'носитиме'::text,'носить'::text,'Наступного тижня в цей час він носитиме цей важкий гіпс через один крихітний перелом! Жах!'::text),
(356262,39585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La semana que viene a esta hora ... esta escayola pesada por una fractura diminuta! ¡Una pesadilla!'::text,'estará llevando'::text,'llevará'::text,'lleva'::text,'¡La semana que viene a esta hora estará llevando esta escayola pesada por una fractura diminuta! ¡Una pesadilla!'::text),
(356261,39585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semaine prochaine à la même heure, il ... ce plâtre lourd à cause d''une toute petite fracture ! Un cauchemar !'::text,'portera'::text,'portera'::text,'porte'::text,'La semaine prochaine à la même heure, il portera ce plâtre lourd à cause d''une toute petite fracture ! Un cauchemar !'::text),
(356264,39585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haftaya bu saatlerde minicik bir kırık yüzünden bu ağır alçıyı ...! Tam bir kâbus!'::text,'takıyor olacak'::text,'takacak'::text,'takıyor'::text,'Haftaya bu saatlerde minicik bir kırık yüzünden bu ağır alçıyı takıyor olacak! Tam bir kâbus!'::text),
(356265,39585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő héten ilyenkor ezt a nehéz gipszet ... egyetlen apró törés miatt! Rémálom!'::text,'fogja hordani'::text,'fogja hordani'::text,'hordja'::text,'Jövő héten ilyenkor ezt a nehéz gipszet fogja hordani egyetlen apró törés miatt! Rémálom!'::text),
(356268,39586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schwört, dass er nach diesem schrecklichen Bruch vorsichtiger ...!'::text,'sein wird'::text,'sein wird'::text,'ist'::text,'Er schwört, dass er nach diesem schrecklichen Bruch vorsichtiger sein wird!'::text),
(356272,39586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він клянеться, що після цього жахливого перелому ... обережнішим!'::text,'буде'::text,'буде'::text,'є'::text,'Він клянеться, що після цього жахливого перелому буде обережнішим!'::text),
(356271,39586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Jura que ... más cuidadoso después de esta fractura horrible!'::text,'será'::text,'estará siendo'::text,'está siendo'::text,'¡Jura que será más cuidadoso después de esta fractura horrible!'::text),
(356270,39586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il jure qu''il ... plus prudent après cette terrible fracture !'::text,'sera'::text,'sera'::text,'est'::text,'Il jure qu''il sera plus prudent après cette terrible fracture !'::text),
(356273,39586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu korkunç kırıktan sonra daha dikkatli ... yemin ediyor!'::text,'olacağına'::text,'olacağına'::text,'olduğuna'::text,'Bu korkunç kırıktan sonra daha dikkatli olacağına yemin ediyor!'::text),
(356274,39586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megesküszik, hogy ettől a szörnyű töréstől kezdve óvatosabb ...!'::text,'lesz'::text,'lesz'::text,NULL::text,'Megesküszik, hogy ettől a szörnyű töréstől kezdve óvatosabb lesz!'::text),
(356286,39588,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir erzählt, dass er vor diesem Bruch Skateboarden ...'::text,'früher geliebt hat'::text,'immer geliebt hat'::text,'gewohnt war zu lieben'::text,'Girl, er hat mir erzählt, dass er vor diesem Bruch Skateboarden früher geliebt hat.'::text),
(356290,39588,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що до цього перелому ... скейтбординг.'::text,'колись обожнював'::text,'бувало, обожнював'::text,'звик обожнювати'::text,'Подруго, він сказав мені, що до цього перелому колись обожнював скейтбординг.'::text),
(356289,39588,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que antes de esta fractura ... el skate.'::text,'le encantaba'::text,'le encantaba'::text,'estaba acostumbrado a amar'::text,'Tía, me dijo que antes de esta fractura le encantaba el skate.'::text),
(356288,39588,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''avant cette fracture, il ... le skate.'::text,'adorait'::text,'adorait'::text,'avait l''habitude d''adorer'::text,'Meuf, il m''a dit qu''avant cette fracture, il adorait le skate.'::text),
(356291,39588,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana bu kırıktan önce kaykaya ... söyledi.'::text,'bayıldığını'::text,'bayıldığını'::text,'bayılmaya alışkın olduğunu'::text,'Kızım, bana bu kırıktan önce kaykaya bayıldığını söyledi.'::text),
(356292,39588,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a törés előtt ... a gördeszkázást.'::text,'imádta'::text,'imádta'::text,'hozzá volt szokva, hogy imádja'::text,'Csajszi, azt mondta, hogy a törés előtt imádta a gördeszkázást.'::text),
(356295,39589,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend ... er seinen Gips ständig allen, samt Bruch.'::text,'zeigt'::text,'zeigt'::text,'zeigt'::text,'Hör mal, anscheinend zeigt er seinen Gips ständig allen, samt Bruch.'::text),
(356299,39589,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він постійно ... всім свій гіпс, разом із переломом.'::text,'показує'::text,'показувати'::text,'показувати'::text,'Слухай, кажуть, він постійно показує всім свій гіпс, разом із переломом.'::text),
(356298,39589,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer no para de ... su escayola a todo el mundo, fractura incluida.'::text,'enseñar'::text,'enseñar'::text,'enseñar'::text,'Oye, al parecer no para de enseñar su escayola a todo el mundo, fractura incluida.'::text),
(356297,39589,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il n''arrête pas de ... son plâtre à tout le monde, fracture comprise.'::text,'montrer'::text,'montrer'::text,'montrer'::text,'Écoute, apparemment il n''arrête pas de montrer son plâtre à tout le monde, fracture comprise.'::text),
(356300,39589,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan alçısını kırığıyla birlikte herkese ... duruyor.'::text,'gösterip'::text,'gösterip'::text,'göstermek'::text,'Dinle, anlaşılan alçısını kırığıyla birlikte herkese gösterip duruyor.'::text),
(356301,39589,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag folyton ... mindenkinek a gipszét, töréssel együtt.'::text,'mutogatja'::text,'mutogatja'::text,'mutogatja'::text,'Figyelj, állítólag folyton mutogatja mindenkinek a gipszét, töréssel együtt.'::text),
(356304,39590,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend ist diese dunkle Linie ein Bruch, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Girl, anscheinend ist diese dunkle Linie ein Bruch, oder?'::text),
(356308,39590,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ця темна лінія — перелом, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Подруго, кажуть, ця темна лінія — перелом, правда?'::text),
(356307,39590,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer esa línea oscura es una fractura, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Tía, al parecer esa línea oscura es una fractura, ¿verdad?'::text),
(356306,39590,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment cette ligne sombre, c''est une fracture, ... ?'::text,'non'::text,'non'::text,'non'::text,'Meuf, apparemment cette ligne sombre, c''est une fracture, non ?'::text),
(356309,39590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan o koyu çizgi bir kırık, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kızım, anlaşılan o koyu çizgi bir kırık, değil mi?'::text),
(356310,39590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az a sötét vonal egy törés, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Csajszi, állítólag az a sötét vonal egy törés, ugye?'::text),
(356313,39591,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist bei dem Bruch ruhig geblieben, und ehrlich, ...'::text,'die Ärztin auch'::text,'die Ärztin auch'::text,'die Ärztin auch nicht'::text,'Du bist bei dem Bruch ruhig geblieben, und ehrlich, die Ärztin auch.'::text),
(356317,39591,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зберіг спокій через той перелом, і, чесно, ...'::text,'лікарка теж'::text,'лікарка теж'::text,'лікарка теж ні'::text,'Ти зберіг спокій через той перелом, і, чесно, лікарка теж.'::text),
(356316,39591,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mantuviste la calma con esa fractura y, sinceramente, ...'::text,'la doctora también'::text,'la doctora también'::text,'la doctora tampoco'::text,'Mantuviste la calma con esa fractura y, sinceramente, la doctora también.'::text),
(356315,39591,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu es resté calme face à cette fracture et, franchement, ...'::text,'la médecin aussi'::text,'la médecin aussi'::text,'la médecin non plus'::text,'Tu es resté calme face à cette fracture et, franchement, la médecin aussi.'::text),
(356318,39591,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kırık konusunda sakin kaldın ve açıkçası ...'::text,'doktor da öyle'::text,'doktor da öyle'::text,'doktor da kalmadı'::text,'O kırık konusunda sakin kaldın ve açıkçası doktor da öyle.'::text),
(356319,39591,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyugodt maradtál a törés miatt, és őszintén, ...'::text,'az orvos is'::text,'az orvos is'::text,'az orvos sem'::text,'Nyugodt maradtál a törés miatt, és őszintén, az orvos is.'::text),
(356331,39593,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... in seinem Handgelenk ist klein, aber er braucht trotzdem einen Gips.'::text,'Der Bruch'::text,'Ein Bruch'::text,'Bruch'::text,'Der Bruch in seinem Handgelenk ist klein, aber er braucht trotzdem einen Gips.'::text),
(356335,39593,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... у його зап''ясті невеликий, але все одно потрібен гіпс.'::text,'Перелом'::text,'Перелом'::text,'Перелом'::text,'Перелом у його зап''ясті невеликий, але все одно потрібен гіпс.'::text),
(356334,39593,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de su muñeca es pequeña, pero aun así necesita escayola.'::text,'La fractura'::text,'Una fractura'::text,'Fractura'::text,'La fractura de su muñeca es pequeña, pero aun así necesita escayola.'::text),
(356333,39593,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... au poignet est petite, mais il faut quand même un plâtre.'::text,'La fracture'::text,'Une fracture'::text,'Fracture'::text,'La fracture au poignet est petite, mais il faut quand même un plâtre.'::text),
(356336,39593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bileğindeki ... küçük, ama yine de alçı gerekiyor.'::text,'kırık'::text,'bir kırık'::text,'kırık'::text,'Bileğindeki kırık küçük, ama yine de alçı gerekiyor.'::text),
(356337,39593,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a csuklójában kicsi, de azért gipsz kell rá.'::text,'A törés'::text,'Egy törés'::text,'Törés'::text,'A törés a csuklójában kicsi, de azért gipsz kell rá.'::text),
(356340,39594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seinen Arm wegen des Bruchs jetzt in einer Schlinge.'::text,'hält'::text,'hält'::text,'hielt'::text,'Er hält seinen Arm wegen des Bruchs jetzt in einer Schlinge.'::text),
(356344,39594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зараз ... руку на перев''язі через перелом.'::text,'тримає'::text,'тримає'::text,'тримав'::text,'Він зараз тримає руку на перев''язі через перелом.'::text),
(356343,39594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ... el brazo en cabestrillo por la fractura.'::text,'está llevando'::text,'lleva'::text,'ha llevado'::text,'Ahora está llevando el brazo en cabestrillo por la fractura.'::text),
(356342,39594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... son bras en écharpe maintenant à cause de la fracture.'::text,'tient'::text,'tient'::text,'a tenu'::text,'Il tient son bras en écharpe maintenant à cause de la fracture.'::text),
(356345,39594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırık yüzünden şimdi kolunu askıda ...'::text,'tutuyor'::text,'tutar'::text,'tuttu'::text,'Kırık yüzünden şimdi kolunu askıda tutuyor.'::text),
(356346,39594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A törés miatt most felkötve ... a karját.'::text,'tartja'::text,'tartja'::text,'tartotta'::text,'A törés miatt most felkötve tartja a karját.'::text),
(356349,39595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich das Handgelenk eine Woche, bevor die Ärztin den Bruch fand, verletzt.'::text,'hatte'::text,'hat'::text,'war'::text,'Er hatte sich das Handgelenk eine Woche, bevor die Ärztin den Bruch fand, verletzt.'::text),
(356353,39595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... зап''ясток за тиждень до того, як лікарка знайшла перелом.'::text,'пошкодив'::text,'пошкодив'::text,'пошкоджував'::text,'Він пошкодив зап''ясток за тиждень до того, як лікарка знайшла перелом.'::text),
(356352,39595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la muñeca una semana antes de que la doctora encontrara la fractura.'::text,'Se había hecho daño en'::text,'Se ha hecho daño en'::text,'Se estaba haciendo daño en'::text,'Se había hecho daño en la muñeca una semana antes de que la doctora encontrara la fractura.'::text),
(356351,39595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... au poignet une semaine avant que la médecin trouve la fracture.'::text,'s''était fait mal'::text,'s''est fait mal'::text,'se faisait mal'::text,'Il s''était fait mal au poignet une semaine avant que la médecin trouve la fracture.'::text),
(356354,39595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doktor kırığı bulmadan bir hafta önce bileğini ...'::text,'incitmişti'::text,'incitti'::text,'incitiyordu'::text,'Doktor kırığı bulmadan bir hafta önce bileğini incitmişti.'::text),
(356355,39595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy héttel azelőtt ... meg a csuklóját, hogy az orvos megtalálta a törést.'::text,'sértette'::text,'sértette'::text,'sértette'::text,'Egy héttel azelőtt sértette meg a csuklóját, hogy az orvos megtalálta a törést.'::text),
(333030,37004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also anscheinend blieb draußen eine ganze Menschenmenge stehen, während der Bäcker das Schaufenster ...'::text,'füllte'::text,'füllte'::text,'gefüllt hat'::text,'Okay, also anscheinend blieb draußen eine ganze Menschenmenge stehen, während der Bäcker das Schaufenster füllte.'::text),
(333034,37004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, поки пекар ... вітрину, надворі зупинився цілий натовп.'::text,'заповнював'::text,'заповнив'::text,'заповнив'::text,'Короче, кажуть, поки пекар заповнював вітрину, надворі зупинився цілий натовп.'::text),
(333033,37004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer mientras el panadero ... el escaparate, se paró fuera toda una multitud.'::text,'estaba llenando'::text,'llenó'::text,'ha llenado'::text,'Vale, pues al parecer mientras el panadero estaba llenando el escaparate, se paró fuera toda una multitud.'::text),
(333032,37004,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, alors apparemment pendant que le boulanger ... la vitrine, toute une foule s''est arrêtée dehors.'::text,'remplissait'::text,'a rempli'::text,'a rempli'::text,'Ok, alors apparemment pendant que le boulanger remplissait la vitrine, toute une foule s''est arrêtée dehors.'::text),
(333035,37004,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan fırıncı vitrini ... dışarıda koca bir kalabalık durmuş.'::text,'doldururken'::text,'doldurunca'::text,'doldurmuşken'::text,'Tamam, anlaşılan fırıncı vitrini doldururken dışarıda koca bir kalabalık durmuş.'::text),
(333036,37004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag miközben a pék ... a kirakatot, egy egész tömeg megállt kint.'::text,'töltötte'::text,'feltöltötte'::text,'feltöltötte'::text,'Oké, szóval állítólag miközben a pék töltötte a kirakatot, egy egész tömeg megállt kint.'::text),
(333039,37005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, dieser Bäcker ... seit fünf Uhr morgens Baguettes.'::text,'backt'::text,'backt'::text,'backt'::text,'Bestie, ich hab gehört, dieser Bäcker backt seit fünf Uhr morgens Baguettes.'::text),
(333043,37005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, цей пекар ... багети з п''ятої ранку.'::text,'пече'::text,'пече'::text,'пече'::text,'Подруго, я чула, цей пекар пече багети з п''ятої ранку.'::text),
(333042,37005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, me han dicho que este panadero ... baguettes desde las cinco de la mañana.'::text,'lleva horneando'::text,'está horneando'::text,'hornea'::text,'Bestie, me han dicho que este panadero lleva horneando baguettes desde las cinco de la mañana.'::text),
(333041,37005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma best, j''ai entendu dire que ce boulanger ... des baguettes depuis cinq heures du matin.'::text,'fait'::text,'fait'::text,'fait'::text,'Ma best, j''ai entendu dire que ce boulanger fait des baguettes depuis cinq heures du matin.'::text),
(333044,37005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki bu fırıncı sabah beşten beri baget ...'::text,'pişiriyor'::text,'pişiriyor'::text,'pişirir'::text,'Kanka, duydum ki bu fırıncı sabah beşten beri baget pişiriyor.'::text),
(333045,37005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, azt hallottam, hogy ez a pék hajnali öt óta ... a bagetteket.'::text,'süti'::text,'süti'::text,'süti'::text,'Bestie, azt hallottam, hogy ez a pék hajnali öt óta süti a bagetteket.'::text),
(333048,37006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Bäcker ... in ein Baguette wie in ein Handy, als er die Kamera bemerkte, lowkey ikonisch.'::text,'redete gerade'::text,'redete'::text,'redete'::text,'Yo, der Bäcker redete gerade in ein Baguette wie in ein Handy, als er die Kamera bemerkte, lowkey ikonisch.'::text),
(333052,37006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, пекар ... в багет, як у телефон, коли помітив камеру, реально культово.'::text,'говорив'::text,'говорив'::text,'говорив'::text,'Йо, пекар говорив в багет, як у телефон, коли помітив камеру, реально культово.'::text),
(333051,37006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, el panadero ... por una baguette como si fuera un móvil cuando vio la cámara, bastante icónico.'::text,'estaba hablando'::text,'habló'::text,'ha hablado'::text,'Ey, el panadero estaba hablando por una baguette como si fuera un móvil cuando vio la cámara, bastante icónico.'::text),
(333050,37006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le boulanger ... dans une baguette comme dans un téléphone quand il a repéré la caméra, trop iconique.'::text,'parlait'::text,'a parlé'::text,'a parlé'::text,'Yo, le boulanger parlait dans une baguette comme dans un téléphone quand il a repéré la caméra, trop iconique.'::text),
(333053,37006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, fırıncı kamerayı fark ettiğinde bagete telefonmuş gibi ..., bayağı ikonik.'::text,'konuşuyordu'::text,'konuştu'::text,'konuşmuş'::text,'Yo, fırıncı kamerayı fark ettiğinde bagete telefonmuş gibi konuşuyordu, bayağı ikonik.'::text),
(333054,37006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó, a pék úgy ... a bagettbe, mint egy telefonba, amikor észrevette a kamerát, elég ikonikus.'::text,'beszélt'::text,'beszélt'::text,'beszélt'::text,'Jó, a pék úgy beszélt a bagettbe, mint egy telefonba, amikor észrevette a kamerát, elég ikonikus.'::text),
(333066,37008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Laden aufmachte, ... der Bäcker das Schaufenster schon mit Croissants gefüllt.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Als der Laden aufmachte, hatte der Bäcker das Schaufenster schon mit Croissants gefüllt.'::text),
(333070,37008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки крамниця відчинилася, пекар уже ... вітрину круасанами.'::text,'заповнив'::text,'заповнив'::text,'заповнив'::text,'Поки крамниця відчинилася, пекар уже заповнив вітрину круасанами.'::text),
(333069,37008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando abrió la tienda, el panadero ya ... el escaparate de cruasanes.'::text,'había llenado'::text,'ha llenado'::text,'llenó'::text,'Para cuando abrió la tienda, el panadero ya había llenado el escaparate de cruasanes.'::text),
(333068,37008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que la boutique ouvre, le boulanger ... la vitrine de croissants.'::text,'avait rempli'::text,'a rempli'::text,'a rempli'::text,'Le temps que la boutique ouvre, le boulanger avait rempli la vitrine de croissants.'::text),
(333071,37008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dükkân açıldığında fırıncı vitrini çoktan kruvasanla ...'::text,'doldurmuştu'::text,'doldurdu'::text,'doldurdu'::text,'Dükkân açıldığında fırıncı vitrini çoktan kruvasanla doldurmuştu.'::text),
(333072,37008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a bolt kinyitott, a pék már ... a kirakatot croissant-okkal.'::text,'megtöltötte'::text,'megtöltötte'::text,'megtöltötte'::text,'Mire a bolt kinyitott, a pék már megtöltötte a kirakatot croissant-okkal.'::text),
(333075,37009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Menge weiter wächst, ... der Bäcker mehr Baguettes.'::text,'braucht'::text,'bräuchte'::text,'brauchte'::text,'Wenn die Menge weiter wächst, braucht der Bäcker mehr Baguettes.'::text),
(333079,37009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо натовп і далі зростатиме, пекареві ... більше багетів.'::text,'знадобиться'::text,'знадобилося б'::text,'знадобилося'::text,'Якщо натовп і далі зростатиме, пекареві знадобиться більше багетів.'::text),
(333078,37009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la multitud sigue creciendo, el panadero ... más baguettes.'::text,'necesitará'::text,'necesitaría'::text,'necesitó'::text,'Si la multitud sigue creciendo, el panadero necesitará más baguettes.'::text),
(333077,37009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la foule continue de grossir, le boulanger ... plus de baguettes.'::text,'aura besoin de'::text,'aurait besoin de'::text,'avait besoin de'::text,'Si la foule continue de grossir, le boulanger aura besoin de plus de baguettes.'::text),
(333080,37009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık büyümeye devam ederse fırıncının daha fazla bagete ...'::text,'ihtiyacı olacak'::text,'ihtiyacı olurdu'::text,'ihtiyacı oldu'::text,'Kalabalık büyümeye devam ederse fırıncının daha fazla bagete ihtiyacı olacak.'::text),
(333081,37009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tömeg tovább nő, a péknek több bagettre ... szüksége.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha a tömeg tovább nő, a péknek több bagettre lesz szüksége.'::text),
(333084,37010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bäcker füllte das Schaufenster früh, ... die Menge die Croissants sehen konnte.'::text,'damit'::text,'falls'::text,'trotz'::text,'Der Bäcker füllte das Schaufenster früh, damit die Menge die Croissants sehen konnte.'::text),
(333088,37010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пекар рано заповнив вітрину, ... натовп бачив круасани.'::text,'щоб'::text,'на випадок, якщо'::text,'попри'::text,'Пекар рано заповнив вітрину, щоб натовп бачив круасани.'::text),
(333087,37010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El panadero llenó el escaparate temprano ... la multitud pudiera ver los cruasanes.'::text,'para que'::text,'por si'::text,'a pesar de'::text,'El panadero llenó el escaparate temprano para que la multitud pudiera ver los cruasanes.'::text),
(333086,37010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le boulanger a rempli la vitrine tôt ... la foule puisse voir les croissants.'::text,'pour que'::text,'au cas où'::text,'malgré'::text,'Le boulanger a rempli la vitrine tôt pour que la foule puisse voir les croissants.'::text),
(333089,37010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırıncı, kalabalık kruvasanları ... diye vitrini erkenden doldurdu.'::text,'görebilsin'::text,'görürse'::text,'rağmen'::text,'Fırıncı, kalabalık kruvasanları görebilsin diye vitrini erkenden doldurdu.'::text),
(333090,37010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pék korán megtöltötte a kirakatot, ... a tömeg lássa a croissant-okat.'::text,'hogy'::text,'arra az esetre, ha'::text,'annak ellenére, hogy'::text,'A pék korán megtöltötte a kirakatot, hogy a tömeg lássa a croissant-okat.'::text),
(333093,37011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bäcker wusste, sein Baguette ... überhaupt keinen Empfang. Ein echter Profi.'::text,'hätte'::text,'hat'::text,'hat'::text,'Der Bäcker wusste, sein Baguette hätte überhaupt keinen Empfang. Ein echter Profi.'::text),
(333097,37011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пекар знав, що його багет ... жодного сигналу. Справжній професіонал.'::text,'не матиме'::text,'не матиме'::text,'не має'::text,'Пекар знав, що його багет не матиме жодного сигналу. Справжній професіонал.'::text),
(333096,37011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El panadero sabía que su baguette no ... nada de cobertura. Un auténtico profesional.'::text,'tendría'::text,'tendrá'::text,'tiene'::text,'El panadero sabía que su baguette no tendría nada de cobertura. Un auténtico profesional.'::text),
(333095,37011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le boulanger savait que sa baguette ... aucun réseau. Un vrai pro.'::text,'n''aurait'::text,'n''aura'::text,'n''a'::text,'Le boulanger savait que sa baguette n''aurait aucun réseau. Un vrai pro.'::text),
(333098,37011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırıncı, bagetinin hiç sinyal ... biliyordu. Tam bir profesyonel.'::text,'almayacağını'::text,'almayacağını'::text,'almadığını'::text,'Fırıncı, bagetinin hiç sinyal almayacağını biliyordu. Tam bir profesyonel.'::text),
(333099,37011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pék tudta, hogy a bagettjének egyáltalán nem ... térereje. Igazi profi.'::text,'lesz'::text,'lesz'::text,'van'::text,'A pék tudta, hogy a bagettjének egyáltalán nem lesz térereje. Igazi profi.'::text),
(333111,37013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Türen aufgingen, ... der Bäcker die ganze Nacht, komplett voller Mehl!'::text,'arbeitete'::text,'arbeitete'::text,'arbeitet'::text,'Bis die Türen aufgingen, arbeitete der Bäcker die ganze Nacht, komplett voller Mehl!'::text),
(333115,37013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки відчинилися двері, пекар ... всю ніч, геть увесь у борошні!'::text,'працював'::text,'працював'::text,'працює'::text,'Поки відчинилися двері, пекар працював всю ніч, геть увесь у борошні!'::text),
(333114,37013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando se abrieron las puertas, el panadero ... toda la noche, completamente cubierto de harina!'::text,'había estado trabajando'::text,'estaba trabajando'::text,'ha estado trabajando'::text,'¡Para cuando se abrieron las puertas, el panadero había estado trabajando toda la noche, completamente cubierto de harina!'::text),
(333113,37013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les portes ont ouvert, le boulanger ... toute la nuit, complètement couvert de farine !'::text,'avait travaillé'::text,'travaillait'::text,'a travaillé'::text,'Quand les portes ont ouvert, le boulanger avait travaillé toute la nuit, complètement couvert de farine !'::text),
(333116,37013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapılar açıldığında fırıncı bütün gece ..., tepeden tırnağa una bulanmıştı!'::text,'çalışmıştı'::text,'çalışıyordu'::text,'çalışıyor'::text,'Kapılar açıldığında fırıncı bütün gece çalışmıştı, tepeden tırnağa una bulanmıştı!'::text),
(333117,37013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire kinyíltak az ajtók, a pék egész éjjel ..., tiszta liszt volt!'::text,'dolgozott'::text,'dolgozott'::text,'dolgozik'::text,'Mire kinyíltak az ajtók, a pék egész éjjel dolgozott, tiszta liszt volt!'::text),
(333120,37014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... der Bäcker jedes einzelne Croissant, und die Menge wird ausrasten!'::text,'verkauft'::text,'verkauft'::text,'verkauft'::text,'Bis Mittag verkauft der Bäcker jedes einzelne Croissant, und die Menge wird ausrasten!'::text),
(333124,37014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду пекар ... кожен круасан, і натовп кричатиме!'::text,'продасть'::text,'продасть'::text,'продає'::text,'До обіду пекар продасть кожен круасан, і натовп кричатиме!'::text)
