(332805,36979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er den Bacon vergessen würde, ... die Pfanne keinen Bacon drin, also hat er ihn mitgebracht.'::text,'hätte'::text,'hat'::text,'hat'::text,'Wenn er den Bacon vergessen würde, hätte die Pfanne keinen Bacon drin, also hat er ihn mitgebracht.'::text),
(332809,36979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він забув бекон, у сковороді ... бекону, тож він його взяв.'::text,'не було б'::text,'не буде'::text,'немає'::text,'Якби він забув бекон, у сковороді не було б бекону, тож він його взяв.'::text),
(332808,36979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se olvidara el bacon, la sartén no ... bacon, así que lo trajo.'::text,'tendría'::text,'tendrá'::text,'tiene'::text,'Si se olvidara el bacon, la sartén no tendría bacon, así que lo trajo.'::text),
(332807,36979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il oubliait le bacon, la poêle ... pas de bacon, donc il l''a apporté.'::text,'n''aurait'::text,'n''aura'::text,'n''a'::text,'S''il oubliait le bacon, la poêle n''aurait pas de bacon, donc il l''a apporté.'::text),
(332810,36979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pastırmayı unutsaydı tavada hiç domuz pastırması ..., o yüzden getirdi.'::text,'olmazdı'::text,'olmayacak'::text,'yok'::text,'Pastırmayı unutsaydı tavada hiç domuz pastırması olmazdı, o yüzden getirdi.'::text),
(332811,36979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elfelejtené a bacont, a serpenyőben ... bacon, ezért elhozta.'::text,'nem lenne'::text,'nem lesz'::text,'nincs'::text,'Ha elfelejtené a bacont, a serpenyőben nem lenne bacon, ezért elhozta.'::text),
(332814,36980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bacon ... Streifen für Streifen neben das Ei in die Pfanne gelegt.'::text,'wird'::text,'legt'::text,'legte'::text,'Der Bacon wird Streifen für Streifen neben das Ei in die Pfanne gelegt.'::text),
(332818,36980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бекон ... на сковороду біля яйця по одній смужці.'::text,'кладуть'::text,'кладе'::text,'клав'::text,'Бекон кладуть на сковороду біля яйця по одній смужці.'::text),
(332817,36980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El bacon ... en la sartén junto al huevo, tira a tira.'::text,'se coloca'::text,'coloca'::text,'colocó'::text,'El bacon se coloca en la sartén junto al huevo, tira a tira.'::text),
(332816,36980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bacon ... dans la poêle à côté de l''œuf, une tranche à la fois.'::text,'est posé'::text,'pose'::text,'a posé'::text,'Le bacon est posé dans la poêle à côté de l''œuf, une tranche à la fois.'::text),
(332819,36980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Domuz pastırması tavaya yumurtanın yanına şerit şerit ...'::text,'konuyor'::text,'koyuyor'::text,'koydu'::text,'Domuz pastırması tavaya yumurtanın yanına şerit şerit konuyor.'::text),
(332820,36980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bacont csíkonként ... a serpenyőbe a tojás mellé.'::text,'teszik'::text,'teszi'::text,'tette'::text,'A bacont csíkonként teszik a serpenyőbe a tojás mellé.'::text),
(332832,36982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bacon ... in der kalten Luft super riechen, weil er brutzelt.'::text,'muss'::text,'kann nicht'::text,'muss nicht'::text,'Der Bacon muss in der kalten Luft super riechen, weil er brutzelt.'::text),
(332836,36982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бекон ... чудово пахнути в тому холодному повітрі, бо він шкварчить.'::text,'мусить'::text,'не може'::text,'не мусить'::text,'Бекон мусить чудово пахнути в тому холодному повітрі, бо він шкварчить.'::text),
(332835,36982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El bacon ... oler genial con ese aire frío, porque está chisporroteando.'::text,'debe de'::text,'no puede'::text,'no tiene que'::text,'El bacon debe de oler genial con ese aire frío, porque está chisporroteando.'::text),
(332834,36982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bacon ... sentir super bon dans cet air froid, parce qu''il grésille.'::text,'doit'::text,'ne peut pas'::text,'n''a pas besoin de'::text,'Le bacon doit sentir super bon dans cet air froid, parce qu''il grésille.'::text),
(332837,36982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Domuz pastırması o soğuk havada harika ..., çünkü cızırdıyor.'::text,'kokuyor olmalı'::text,'kokuyor olamaz'::text,'kokmak zorunda değil'::text,'Domuz pastırması o soğuk havada harika kokuyor olmalı, çünkü cızırdıyor.'::text),
(332838,36982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bacon ... isteni illatú abban a hideg levegőben, mert sistereg.'::text,'biztosan'::text,'biztosan nem'::text,'nem feltétlenül'::text,'A bacon biztosan isteni illatú abban a hideg levegőben, mert sistereg.'::text),
(332841,36983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pfanne, ... Bacon auf diesem zugefrorenen See brutzelt, ist absolut unglaublich!'::text,'deren'::text,'die'::text,'die'::text,'Die Pfanne, deren Bacon auf diesem zugefrorenen See brutzelt, ist absolut unglaublich!'::text),
(332845,36983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сковорода, ... шкварчить бекон на тому замерзлому озері, просто неймовірна!'::text,'на якій'::text,'яка'::text,'що'::text,'Сковорода, на якій шкварчить бекон на тому замерзлому озері, просто неймовірна!'::text),
(332844,36983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La sartén ... bacon chisporrotea en ese lago helado es absolutamente increíble!'::text,'cuyo'::text,'que'::text,'que'::text,'¡La sartén cuyo bacon chisporrotea en ese lago helado es absolutamente increíble!'::text),
(332843,36983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poêle ... le bacon grésille sur ce lac gelé est absolument incroyable !'::text,'dont'::text,'qui'::text,'que'::text,'La poêle dont le bacon grésille sur ce lac gelé est absolument incroyable !'::text),
(332846,36983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O donmuş gölde pastırması ... tava kesinlikle inanılmaz!'::text,'cızırdayan'::text,'cızırdayan'::text,'cızırdayan'::text,'O donmuş gölde pastırması cızırdayan tava kesinlikle inanılmaz!'::text),
(332847,36983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A serpenyő, ... bacon sistereg azon a befagyott tavon, egyszerűen hihetetlen!'::text,'amelyben a'::text,'amely'::text,'ami'::text,'A serpenyő, amelyben a bacon sistereg azon a befagyott tavon, egyszerűen hihetetlen!'::text),
(332850,36984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schrie, dass der Bacon schwarz ..., aber er war nur braun!'::text,'geworden war'::text,'geworden ist'::text,'wird'::text,'Er schrie, dass der Bacon schwarz geworden war, aber er war nur braun!'::text),
(332854,36984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кричав, що бекон ..., а він був лише коричневий!'::text,'почорнів'::text,'почорнів'::text,'чорніє'::text,'Він кричав, що бекон почорнів, а він був лише коричневий!'::text),
(332853,36984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó que el bacon se ... negro, pero solo estaba dorado!'::text,'había puesto'::text,'ha puesto'::text,'pone'::text,'¡Gritó que el bacon se había puesto negro, pero solo estaba dorado!'::text),
(332852,36984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a crié que le bacon ... noir, mais il était seulement doré !'::text,'était devenu'::text,'est devenu'::text,'devient'::text,'Il a crié que le bacon était devenu noir, mais il était seulement doré !'::text),
(332855,36984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pastırmanın ... bağırdı, ama sadece kahverengiydi!'::text,'kararmış olduğunu'::text,'karardığını'::text,'kararıyor olduğunu'::text,'Pastırmanın kararmış olduğunu bağırdı, ama sadece kahverengiydi!'::text),
(332856,36984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kiabálta, hogy a bacon ..., pedig csak barna volt!'::text,'megfeketedett'::text,'megfeketedett'::text,'feketedik'::text,'Azt kiabálta, hogy a bacon megfeketedett, pedig csak barna volt!'::text),
(332859,36985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... er vor diesem Trip Bacon.'::text,'hasste früher'::text,'hasste'::text,'war gewohnt zu hassen'::text,'Bestie, anscheinend hasste früher er vor diesem Trip Bacon.'::text),
(332863,36985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... бекон до цієї поїздки.'::text,'колись ненавидів'::text,'бувало, ненавидів'::text,'звик ненавидіти'::text,'Подруго, кажуть, він колись ненавидів бекон до цієї поїздки.'::text),
(332862,36985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, al parecer ... el bacon antes de este viaje.'::text,'odiaba'::text,'odiaba'::text,'estaba acostumbrado a odiar'::text,'Bestie, al parecer odiaba el bacon antes de este viaje.'::text),
(332861,36985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma best, apparemment il ... le bacon avant ce voyage.'::text,'détestait'::text,'détestait'::text,'avait l''habitude de détester'::text,'Ma best, apparemment il détestait le bacon avant ce voyage.'::text),
(332864,36985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan bu geziden önce domuz pastırmasından ...'::text,'nefret edermiş'::text,'nefret edermiş'::text,'nefret etmeye alışkınmış'::text,'Kanka, anlaşılan bu geziden önce domuz pastırmasından nefret edermiş.'::text),
(332865,36985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, állítólag ez előtt az út előtt ... a bacont.'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva, hogy utálja'::text,'Bestie, állítólag ez előtt az út előtt utálta a bacont.'::text),
(332868,36986,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, er hat mir gesagt, dass er gern Bacon auf zugefrorenen Seen ...'::text,'zubereitet'::text,'zubereitet'::text,'zubereitet'::text,'Rate mal, er hat mir gesagt, dass er gern Bacon auf zugefrorenen Seen zubereitet.'::text),
(332872,36986,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він сказав мені, що обожнює ... бекон на замерзлих озерах.'::text,'готувати'::text,'готувати'::text,'готувати'::text,'Уяви, він сказав мені, що обожнює готувати бекон на замерзлих озерах.'::text),
(332871,36986,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Me dijo que disfruta ... bacon en lagos helados.'::text,'cocinando'::text,'cocinar'::text,'cocinar'::text,'¿Sabes qué? Me dijo que disfruta cocinando bacon en lagos helados.'::text),
(332870,36986,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il m''a dit qu''il adore ... du bacon sur des lacs gelés.'::text,'cuisiner'::text,'cuisiner'::text,'cuisiner'::text,'Devine quoi, il m''a dit qu''il adore cuisiner du bacon sur des lacs gelés.'::text),
(332873,36986,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, bana donmuş göllerde domuz pastırması ... bayıldığını söyledi.'::text,'pişirmeye'::text,'pişirmeye'::text,'pişirmek'::text,'Bil bakalım, bana donmuş göllerde domuz pastırması pişirmeye bayıldığını söyledi.'::text),
(332874,36986,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy imád bacont ... befagyott tavakon.'::text,'sütni'::text,'sütni'::text,'sütni'::text,'Képzeld, azt mondta, hogy imád bacont sütni befagyott tavakon.'::text),
(332886,36988,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, als er die Kartoffeln dazutat, ... der Bacon schon braun, echt jetzt.'::text,'war'::text,'ist'::text,'wird'::text,'Bro, als er die Kartoffeln dazutat, war der Bacon schon braun, echt jetzt.'::text),
(332890,36988,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки він додав картоплю, бекон уже ..., реально.'::text,'підрум''янився'::text,'підрум''янився'::text,'рум''яниться'::text,'Бро, поки він додав картоплю, бекон уже підрум''янився, реально.'::text),
(332889,36988,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para cuando añadió las patatas, el bacon ya se ..., en serio.'::text,'había dorado'::text,'ha dorado'::text,'dora'::text,'Bro, para cuando añadió las patatas, el bacon ya se había dorado, en serio.'::text),
(332888,36988,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le temps qu''il ajoute les patates, le bacon ..., sérieux.'::text,'avait doré'::text,'a doré'::text,'dore'::text,'Frérot, le temps qu''il ajoute les patates, le bacon avait doré, sérieux.'::text),
(332891,36988,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o patatesleri ekleyene kadar pastırma ..., cidden.'::text,'kızarmıştı'::text,'kızardı'::text,'kızarıyor'::text,'Kanka, o patatesleri ekleyene kadar pastırma kızarmıştı, cidden.'::text),
(332892,36988,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire hozzáadta a krumplit, a bacon már ..., komolyan.'::text,'megpirult'::text,'megpirult'::text,'pirul'::text,'Tesó, mire hozzáadta a krumplit, a bacon már megpirult, komolyan.'::text),
(357105,39679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besucher ... durch die Galerie, als er die große abstrakte Leinwand bemerkte.'::text,'ging gerade'::text,'ging'::text,'ging'::text,'Der Besucher ging gerade durch die Galerie, als er die große abstrakte Leinwand bemerkte.'::text),
(357109,39679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відвідувач ... галереєю, коли помітив велике абстрактне полотно.'::text,'проходив'::text,'пройшов'::text,'пройшов'::text,'Відвідувач проходив галереєю, коли помітив велике абстрактне полотно.'::text),
(357108,39679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El visitante ... por la galería cuando observó el gran lienzo abstracto.'::text,'estaba caminando'::text,'caminó'::text,'ha caminado'::text,'El visitante estaba caminando por la galería cuando observó el gran lienzo abstracto.'::text),
(357107,39679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le visiteur ... dans la galerie quand il a remarqué la grande toile abstraite.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Le visiteur marchait dans la galerie quand il a remarqué la grande toile abstraite.'::text),
(357110,39679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaretçi galeride ... büyük soyut tuvali fark etti.'::text,'yürürken'::text,'yürüdü'::text,'yürümüş'::text,'Ziyaretçi galeride yürürken büyük soyut tuvali fark etti.'::text),
(357111,39679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogató éppen ... a galérián, amikor észrevette a nagy absztrakt vásznat.'::text,'sétált át'::text,'átsétált'::text,'átsétált'::text,'A látogató éppen sétált át a galérián, amikor észrevette a nagy absztrakt vásznat.'::text),
(357123,39681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er diese Tür nicht geöffnet hätte, ... er den riesigen Galeriesaal nicht gefunden.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er diese Tür nicht geöffnet hätte, hätte er den riesigen Galeriesaal nicht gefunden.'::text),
(357127,39681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не відчинив ті двері, він ... величезну залу галереї.'::text,'не знайшов би'::text,'не знайде'::text,'не знайшов'::text,'Якби він не відчинив ті двері, він не знайшов би величезну залу галереї.'::text),
(357126,39681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera abierto esa puerta, no ... la enorme sala de la galería.'::text,'habría encontrado'::text,'encontrará'::text,'encontró'::text,'Si no hubiera abierto esa puerta, no habría encontrado la enorme sala de la galería.'::text),
(357125,39681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas ouvert cette porte, il ... l''immense salle de la galerie.'::text,'n''aurait pas trouvé'::text,'ne trouvera pas'::text,'n''a pas trouvé'::text,'S''il n''avait pas ouvert cette porte, il n''aurait pas trouvé l''immense salle de la galerie.'::text),
(357128,39681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kapıyı açmasaydı, galerinin devasa salonunu ...'::text,'bulamazdı'::text,'bulamayacak'::text,'bulamadı'::text,'O kapıyı açmasaydı, galerinin devasa salonunu bulamazdı.'::text),
(357129,39681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem nyitotta volna ki azt az ajtót, ... a galéria hatalmas termét.'::text,'nem találta volna meg'::text,'nem fogja megtalálni'::text,'nem találta meg'::text,'Ha nem nyitotta volna ki azt az ajtót, nem találta volna meg a galéria hatalmas termét.'::text),
(357132,39682,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schlug vor, die Galerie nächste Woche noch mal zu ...'::text,'besuchen'::text,'besuchen'::text,'besuchen'::text,'Er schlug vor, die Galerie nächste Woche noch mal zu besuchen.'::text),
(357136,39682,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він запропонував ... галерею знову наступного тижня.'::text,'відвідати'::text,'відвідати'::text,'відвідав'::text,'Він запропонував відвідати галерею знову наступного тижня.'::text),
(357135,39682,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Propuso ... la galería otra vez la semana que viene.'::text,'visitar'::text,'visitar'::text,'visitó'::text,'Propuso visitar la galería otra vez la semana que viene.'::text),
(357134,39682,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a proposé de ... la galerie à nouveau la semaine prochaine.'::text,'visiter'::text,'visiter'::text,'visiter'::text,'Il a proposé de visiter la galerie à nouveau la semaine prochaine.'::text),
(357137,39682,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Galeriyi haftaya tekrar ... önerdi.'::text,'ziyaret etmeyi'::text,'ziyaret etmeyi'::text,'ziyaret etti'::text,'Galeriyi haftaya tekrar ziyaret etmeyi önerdi.'::text),
(357138,39682,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt javasolta, hogy jövő héten ... meg újra a galériát.'::text,'nézzék'::text,'nézzék'::text,'nézték'::text,'Azt javasolta, hogy jövő héten nézzék meg újra a galériát.'::text),
(357141,39683,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... Kunst studiert haben; du schaust dir jedes Bild in der Galerie an wie ein Profi.'::text,'musst'::text,'hättest'::text,'kannst nicht'::text,'Ehrlich, du musst Kunst studiert haben; du schaust dir jedes Bild in der Galerie an wie ein Profi.'::text),
(357145,39683,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... вивчав мистецтво; ти дивишся на кожну картину в галереї як профі.'::text,'мабуть'::text,'мав би'::text,'точно не'::text,'Чесно, ти мабуть вивчав мистецтво; ти дивишся на кожну картину в галереї як профі.'::text),
(357144,39683,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... estudiado arte; miras cada cuadro de la galería como un pro.'::text,'debes de haber'::text,'deberías haber'::text,'no puedes haber'::text,'Sinceramente, tú debes de haber estudiado arte; miras cada cuadro de la galería como un pro.'::text),
(357143,39683,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... étudié l''art ; tu regardes chaque tableau de la galerie comme un pro.'::text,'as dû'::text,'aurais dû'::text,'ne peux pas avoir'::text,'Franchement, tu as dû étudié l''art ; tu regardes chaque tableau de la galerie comme un pro.'::text),
(357146,39683,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sanat ...; galerideki her tabloya bir profesyonel gibi bakıyorsun.'::text,'okumuş olmalısın'::text,'okumalıydın'::text,'okumuş olamazsın'::text,'Açıkçası, sanat okumuş olmalısın; galerideki her tabloya bir profesyonel gibi bakıyorsun.'::text),
(357147,39683,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... művészetet tanultál; úgy nézed a galéria minden festményét, mint egy profi.'::text,'biztosan'::text,'kellett volna'::text,'biztosan nem'::text,'Őszintén, biztosan művészetet tanultál; úgy nézed a galéria minden festményét, mint egy profi.'::text),
(357159,39685,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, diese Galerie ... mehr Platz. Offensichtlich ist sie viel zu klein.'::text,'hätte'::text,'hat'::text,'hätte'::text,'Er wünscht sich, diese Galerie hätte mehr Platz. Offensichtlich ist sie viel zu klein.'::text),
(357163,39685,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб ця галерея ... більше простору. Очевидно, вона занадто мала.'::text,'мала'::text,'має'::text,'мала б'::text,'Він хотів би, щоб ця галерея мала більше простору. Очевидно, вона занадто мала.'::text),
(357162,39685,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía que esta galería ... más espacio. Está claro que es demasiado pequeña.'::text,'tuviera'::text,'tiene'::text,'tendría'::text,'Desearía que esta galería tuviera más espacio. Está claro que es demasiado pequeña.'::text),
(357161,39685,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait que cette galerie ... plus d''espace. Visiblement, elle est beaucoup trop petite.'::text,'ait'::text,'a'::text,'aurait'::text,'Il aimerait que cette galerie ait plus d''espace. Visiblement, elle est beaucoup trop petite.'::text),
(357164,39685,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bu galerinin daha fazla alanı ..., diye düşünüyor. Belli ki fazlasıyla küçük.'::text,'olsa'::text,'var'::text,'olsaydı'::text,'Keşke bu galerinin daha fazla alanı olsa, diye düşünüyor. Belli ki fazlasıyla küçük.'::text),
(357165,39685,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha ennek a galériának ... több helye. Láthatóan túl kicsi.'::text,'lenne'::text,'van'::text,'lenne'::text,'Azt szeretné, ha ennek a galériának lenne több helye. Láthatóan túl kicsi.'::text),
(357168,39686,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die letzte Halle, ... Glasdach echt krass ist, ist der beste Teil der Galerie, Bro.'::text,'deren'::text,'die'::text,'die'::text,'Die letzte Halle, deren Glasdach echt krass ist, ist der beste Teil der Galerie, Bro.'::text),
(357172,39686,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Остання зала, ... скляний дах просто божевільний, — найкраща частина галереї, бро.'::text,'у якої'::text,'яка'::text,'що'::text,'Остання зала, у якої скляний дах просто божевільний, — найкраща частина галереї, бро.'::text),
(357171,39686,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La última sala, ... techo de cristal es una locura, es lo mejor de la galería, bro.'::text,'cuyo'::text,'que'::text,'que'::text,'La última sala, cuyo techo de cristal es una locura, es lo mejor de la galería, bro.'::text),
(357170,39686,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La dernière salle, ... le toit en verre est un peu dingue, c''est le meilleur coin de la galerie, frérot.'::text,'dont'::text,'qui'::text,'que'::text,'La dernière salle, dont le toit en verre est un peu dingue, c''est le meilleur coin de la galerie, frérot.'::text),
(357173,39686,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam çatısı bayağı çılgın ... son salon, galerinin en efsane kısmı kanka.'::text,'olan'::text,'olan'::text,'olan'::text,'Cam çatısı bayağı çılgın olan son salon, galerinin en efsane kısmı kanka.'::text),
(357174,39686,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utolsó terem, ... üvegteteje elég őrült, a galéria legjobb része, tesó.'::text,'amelynek az'::text,'amely'::text,'ami'::text,'Az utolsó terem, amelynek az üvegteteje elég őrült, a galéria legjobb része, tesó.'::text),
(357177,39687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er geht auf ... Bild in der Galerie zu.'::text,'das größte'::text,'ein größtes'::text,'größte'::text,'Er geht auf das größte Bild in der Galerie zu.'::text),
(357181,39687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він іде до ... картини в галереї.'::text,'найбільшої'::text,'найбільшої'::text,'найбільшої'::text,'Він іде до найбільшої картини в галереї.'::text),
(357180,39687,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Camina hacia ... cuadro de la galería.'::text,'el mayor'::text,'un mayor'::text,'mayor'::text,'Camina hacia el mayor cuadro de la galería.'::text),
(357179,39687,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il marche vers ... tableau de la galerie.'::text,'le plus grand'::text,'un plus grand'::text,'plus grand'::text,'Il marche vers le plus grand tableau de la galerie.'::text),
(357182,39687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Galerideki ... tabloya doğru yürüyor.'::text,'en büyük'::text,'en büyük'::text,'en büyük'::text,'Galerideki en büyük tabloya doğru yürüyor.'::text),
(357183,39687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... festmény felé sétál a galériában.'::text,'A legnagyobb'::text,'Egy legnagyobb'::text,'Legnagyobb'::text,'A legnagyobb festmény felé sétál a galériában.'::text),
(357186,39688,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seines Meetings um 15 Uhr blieb er in der Galerie.'::text,'Trotz'::text,'Obwohl'::text,'Außer wenn'::text,'Trotz seines Meetings um 15 Uhr blieb er in der Galerie.'::text),
(357190,39688,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... зустріч о 15:00, він залишився в галереї.'::text,'Попри'::text,'Хоча'::text,'Якщо не'::text,'Попри зустріч о 15:00, він залишився в галереї.'::text),
(357189,39688,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su reunión de las 15:00, se quedó en la galería.'::text,'A pesar de'::text,'Aunque'::text,'A menos que'::text,'A pesar de su reunión de las 15:00, se quedó en la galería.'::text),
(357188,39688,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sa réunion de 15 h, il est resté à la galerie.'::text,'Malgré'::text,'Bien que'::text,'À moins que'::text,'Malgré sa réunion de 15 h, il est resté à la galerie.'::text),
(357191,39688,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 15.00''teki toplantısına ... galeride kaldı.'::text,'rağmen'::text,'olsa da'::text,'olmadıkça'::text,'Saat 15.00''teki toplantısına rağmen galeride kaldı.'::text),
(357192,39688,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 15 órás megbeszélése ... a galériában maradt.'::text,'ellenére'::text,'bár'::text,'hacsak nem'::text,'A 15 órás megbeszélése ellenére a galériában maradt.'::text),
(357195,39689,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Tages ... er jeden Raum der Galerie.'::text,'sieht'::text,'sieht'::text,'sieht'::text,'Bis zum Ende des Tages sieht er jeden Raum der Galerie.'::text),
(357199,39689,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця дня він ... кожну залу в галереї.'::text,'побачить'::text,'побачить'::text,'бачить'::text,'До кінця дня він побачить кожну залу в галереї.'::text),
(357198,39689,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del día, ... todas las salas de la galería.'::text,'habrá visto'::text,'verá'::text,'ve'::text,'Para el final del día, habrá visto todas las salas de la galería.'::text),
(357197,39689,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la journée, il ... chaque salle de la galerie.'::text,'aura vu'::text,'verra'::text,'voit'::text,'D''ici la fin de la journée, il aura vu chaque salle de la galerie.'::text),
(357200,39689,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün sonuna kadar galerideki her salonu ...'::text,'görmüş olacak'::text,'görecek'::text,'görüyor'::text,'Gün sonuna kadar galerideki her salonu görmüş olacak.'::text),
(357201,39689,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap végére ... a galéria minden termét.'::text,'megnézi'::text,'meg fogja nézni'::text,'nézi'::text,'A nap végére megnézi a galéria minden termét.'::text),
(357222,39692,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gamer ... auf dem Sofa, als das Rennen auf dem großen Fernseher begann.'::text,'saß'::text,'setzte sich'::text,'setzte sich'::text,'Der Gamer saß auf dem Sofa, als das Rennen auf dem großen Fernseher begann.'::text),
(357226,39692,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Геймер ... на дивані, коли на великому телевізорі почалися перегони.'::text,'сидів'::text,'сів'::text,'сів'::text,'Геймер сидів на дивані, коли на великому телевізорі почалися перегони.'::text),
(357225,39692,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gamer ... en el sofá cuando empezó la carrera en la tele grande.'::text,'estaba sentado'::text,'se sentó'::text,'se ha sentado'::text,'El gamer estaba sentado en el sofá cuando empezó la carrera en la tele grande.'::text),
(357224,39692,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gamer ... sur le canapé quand la course a commencé sur la grande télé.'::text,'était assis'::text,'s''est assis'::text,'s''est assis'::text,'Le gamer était assis sur le canapé quand la course a commencé sur la grande télé.'::text),
(357227,39692,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük televizyondaki yarış başladığında oyuncu kanepede ...'::text,'oturuyordu'::text,'oturdu'::text,'oturmuş'::text,'Büyük televizyondaki yarış başladığında oyuncu kanepede oturuyordu.'::text),
(357228,39692,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gamer ... a kanapén, amikor elindult a verseny a nagy tévén.'::text,'ült'::text,'leült'::text,'leült'::text,'A gamer ült a kanapén, amikor elindult a verseny a nagy tévén.'::text),
(357231,39693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Gamer ... seit dem Frühstück dasselbe Rennspiel.'::text,'spielt'::text,'spielt'::text,'spielte'::text,'Der junge Gamer spielt seit dem Frühstück dasselbe Rennspiel.'::text),
(357235,39693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий геймер ... в ту саму гру-перегони ще зі сніданку.'::text,'грає'::text,'грав'::text,'грав'::text,'Молодий геймер грає в ту саму гру-перегони ще зі сніданку.'::text),
(357234,39693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven gamer ... al mismo juego de carreras desde el desayuno.'::text,'lleva jugando'::text,'ha jugado'::text,'jugó'::text,'El joven gamer lleva jugando al mismo juego de carreras desde el desayuno.'::text),
(357233,39693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune gamer ... au même jeu de course depuis le petit-déjeuner.'::text,'joue'::text,'a joué'::text,'a joué'::text,'Le jeune gamer joue au même jeu de course depuis le petit-déjeuner.'::text),
(357236,39693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç oyuncu kahvaltıdan beri aynı yarış oyununu ...'::text,'oynuyor'::text,'oynadı'::text,'oynadı'::text,'Genç oyuncu kahvaltıdan beri aynı yarış oyununu oynuyor.'::text),
(357237,39693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal gamer reggeli óta ugyanazzal a versenyjátékkal ...'::text,'játszik'::text,'játszott'::text,'játszott'::text,'A fiatal gamer reggeli óta ugyanazzal a versenyjátékkal játszik.'::text),
(357240,39694,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Finale begann, ... jeder Gamer in der Arena schon seinen Platz eingenommen.'::text,'hatte'::text,'hat'::text,'nimmt'::text,'Als das Finale begann, hatte jeder Gamer in der Arena schon seinen Platz eingenommen.'::text),
(357244,39694,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки почався фінал, кожен геймер на арені вже ... своє місце.'::text,'зайняв'::text,'зайняв'::text,'займає'::text,'Поки почався фінал, кожен геймер на арені вже зайняв своє місце.'::text),
(357243,39694,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando empezó la final, cada gamer del estadio ya ... su asiento.'::text,'había ocupado'::text,'ha ocupado'::text,'ocupa'::text,'Para cuando empezó la final, cada gamer del estadio ya había ocupado su asiento.'::text),
(357242,39694,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que la finale commence, chaque gamer de l''arène ... sa place.'::text,'avait pris'::text,'a pris'::text,'prend'::text,'Le temps que la finale commence, chaque gamer de l''arène avait pris sa place.'::text),
(357245,39694,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Final başladığında arenadaki her oyuncu yerini çoktan ...'::text,'almıştı'::text,'aldı'::text,'alıyor'::text,'Final başladığında arenadaki her oyuncu yerini çoktan almıştı.'::text),
(357246,39694,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a döntő elkezdődött, az arénában minden gamer már ... a helyét.'::text,'elfoglalta'::text,'elfoglalta'::text,'elfoglalja'::text,'Mire a döntő elkezdődött, az arénában minden gamer már elfoglalta a helyét.'::text),
(357249,39695,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn dieser Gamer weiter den Bildschirm anschreit, ... die Nachbarn das, klar.'::text,'lieben'::text,'würden lieben'::text,'liebten'::text,'Wenn dieser Gamer weiter den Bildschirm anschreit, lieben die Nachbarn das, klar.'::text),
(357253,39695,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо цей геймер і далі кричатиме на екран, сусіди це ..., звісно.'::text,'обожнюватимуть'::text,'обожнювали б'::text,'обожнювали'::text,'Якщо цей геймер і далі кричатиме на екран, сусіди це обожнюватимуть, звісно.'::text),
(357252,39695,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ese gamer sigue gritándole a la pantalla, a los vecinos les ..., obviamente.'::text,'encantará'::text,'encantaría'::text,'encantó'::text,'Si ese gamer sigue gritándole a la pantalla, a los vecinos les encantará, obviamente.'::text),
(357251,39695,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ce gamer continue de crier sur l''écran, les voisins ... ça, évidemment.'::text,'adoreront'::text,'adoreraient'::text,'ont adoré'::text,'Si ce gamer continue de crier sur l''écran, les voisins adoreront ça, évidemment.'::text),
(357254,39695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O oyuncu ekrana bağırmaya devam ederse komşular buna ..., tabii ki.'::text,'bayılacak'::text,'bayılırdı'::text,'bayıldı'::text,'O oyuncu ekrana bağırmaya devam ederse komşular buna bayılacak, tabii ki.'::text),
(357255,39695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az a gamer tovább kiabál a képernyővel, a szomszédok ..., persze.'::text,'imádni fogják'::text,'imádnák'::text,'imádták'::text,'Ha az a gamer tovább kiabál a képernyővel, a szomszédok imádni fogják, persze.'::text),
(357258,39696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Gamerin mehr schlafen würde, ... sie bei Games weniger genial, klar.'::text,'wäre'::text,'ist'::text,'ist'::text,'Wenn diese Gamerin mehr schlafen würde, wäre sie bei Games weniger genial, klar.'::text),
(357262,39696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ця геймерка більше спала, вона ... менш неймовірною в іграх, звісно.'::text,'була б'::text,'буде'::text,'є'::text,'Якби ця геймерка більше спала, вона була б менш неймовірною в іграх, звісно.'::text),
(357261,39696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si esta gamer durmiera más, ... menos increíble en los juegos, obviamente.'::text,'sería'::text,'será'::text,'es'::text,'Si esta gamer durmiera más, sería menos increíble en los juegos, obviamente.'::text),
(357260,39696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette gamer dormait plus, elle ... moins incroyable aux jeux, évidemment.'::text,'serait'::text,'sera'::text,'est'::text,'Si cette gamer dormait plus, elle serait moins incroyable aux jeux, évidemment.'::text),
(357263,39696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu oyuncu daha çok uyusaydı, oyunlarda daha az harika ..., tabii ki.'::text,'olurdu'::text,'olacak'::text,NULL::text,'Bu oyuncu daha çok uyusaydı, oyunlarda daha az harika olurdu, tabii ki.'::text),
(357264,39696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a gamer többet aludna, kevésbé ... elképesztő a játékokban, persze.'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha ez a gamer többet aludna, kevésbé lenne elképesztő a játékokban, persze.'::text),
(357267,39697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der siegreiche Gamer ... auf dem riesigen Bildschirm über der Bühne gezeigt.'::text,'wurde'::text,'hat'::text,'war'::text,'Der siegreiche Gamer wurde auf dem riesigen Bildschirm über der Bühne gezeigt.'::text),
(357271,39697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Геймера-переможця ... на величезному екрані над сценою.'::text,'показали'::text,'показав'::text,'показував'::text,'Геймера-переможця показали на величезному екрані над сценою.'::text),
(357270,39697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al gamer ganador lo ... en la pantalla gigante sobre el escenario.'::text,'mostraron'::text,'mostró'::text,'estaba mostrando'::text,'Al gamer ganador lo mostraron en la pantalla gigante sobre el escenario.'::text),
(357269,39697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gamer gagnant ... sur l''écran géant au-dessus de la scène.'::text,'a été montré'::text,'a montré'::text,'montrait'::text,'Le gamer gagnant a été montré sur l''écran géant au-dessus de la scène.'::text),
(357272,39697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kazanan oyuncu sahnenin üstündeki dev ekranda ...'::text,'gösterildi'::text,'gösterdi'::text,'gösteriyordu'::text,'Kazanan oyuncu sahnenin üstündeki dev ekranda gösterildi.'::text),
(357273,39697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A győztes gamert ... az óriáskivetítőn a színpad felett.'::text,'mutatták'::text,'mutatta'::text,'mutatta'::text,'A győztes gamert mutatták az óriáskivetítőn a színpad felett.'::text),
(357276,39698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge ... den Gamer auf dem riesigen Bildschirm mit lautem Jubel.'::text,'begrüßte'::text,'wurde begrüßt'::text,'begrüßend'::text,'Die Menge begrüßte den Gamer auf dem riesigen Bildschirm mit lautem Jubel.'::text),
(357280,39698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп ... геймера на величезному екрані гучними вигуками.'::text,'привітав'::text,'був привітаний'::text,'вітаючи'::text,'Натовп привітав геймера на величезному екрані гучними вигуками.'::text),
(357279,39698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El público ... al gamer de la pantalla gigante con fuertes vítores.'::text,'recibió'::text,'fue recibido'::text,'recibiendo'::text,'El público recibió al gamer de la pantalla gigante con fuertes vítores.'::text),
(357278,39698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule ... le gamer sur l''écran géant avec de grandes acclamations.'::text,'a acclamé'::text,'a été acclamée'::text,'acclamant'::text,'La foule a acclamé le gamer sur l''écran géant avec de grandes acclamations.'::text),
(357281,39698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık dev ekrandaki oyuncuyu yüksek sesli tezahüratlarla ...'::text,'karşıladı'::text,'karşılandı'::text,'karşılayarak'::text,'Kalabalık dev ekrandaki oyuncuyu yüksek sesli tezahüratlarla karşıladı.'::text),
(357282,39698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg hangos ujjongással ... a gamert az óriáskivetítőn.'::text,'fogadta'::text,'fogadták'::text,'fogadva'::text,'A tömeg hangos ujjongással fogadta a gamert az óriáskivetítőn.'::text),
(357285,39699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit 20.000 Fans in der Arena ... dieser Gamer der Top-Name auf der Roadmap des Teams sein.'::text,'muss'::text,'kann nicht'::text,'muss nicht'::text,'Mit 20.000 Fans in der Arena muss dieser Gamer der Top-Name auf der Roadmap des Teams sein.'::text),
(357289,39699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З 20 000 фанатів на арені цей геймер ... бути головним іменем у роадмапі команди.'::text,'мусить'::text,'не може'::text,'може й не'::text,'З 20 000 фанатів на арені цей геймер мусить бути головним іменем у роадмапі команди.'::text),
(357288,39699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con 20.000 fans en el estadio, ese gamer ... ser el nombre estrella del roadmap del equipo.'::text,'debe de'::text,'no puede'::text,'podría no'::text,'Con 20.000 fans en el estadio, ese gamer debe de ser el nombre estrella del roadmap del equipo.'::text),
(357287,39699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec 20 000 fans dans l''arène, ce gamer ... être le nom phare de la roadmap de l''équipe.'::text,'doit'::text,'ne peut pas'::text,'pourrait ne pas'::text,'Avec 20 000 fans dans l''arène, ce gamer doit être le nom phare de la roadmap de l''équipe.'::text),
(357290,39699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arenada 20.000 hayranla o oyuncu, takımın yol haritasındaki en önemli isim ...'::text,'olmalı'::text,'olamaz'::text,'olmayabilir'::text,'Arenada 20.000 hayranla o oyuncu, takımın yol haritasındaki en önemli isim olmalı.'::text),
(357291,39699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'20 000 rajongóval az arénában ... az a gamer a csapat roadmapjének első számú neve.'::text,'biztosan'::text,'biztosan nem'::text,'talán nem'::text,'20 000 rajongóval az arénában biztosan az a gamer a csapat roadmapjének első számú neve.'::text),
(357294,39700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Gamer ist eine Person, ... Games spielt, also spielt er deshalb Games.'::text,'die'::text,'welche'::text,'wo'::text,'Ein Gamer ist eine Person, die Games spielt, also spielt er deshalb Games.'::text),
(357298,39700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Геймер — це людина, ... грає в ігри, тому він і грає в ігри.'::text,'яка'::text,'що'::text,'де'::text,'Геймер — це людина, яка грає в ігри, тому він і грає в ігри.'::text),
(357297,39700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un gamer es una persona ... juega a videojuegos, así que por eso juega a videojuegos.'::text,'que'::text,'la cual'::text,'donde'::text,'Un gamer es una persona que juega a videojuegos, así que por eso juega a videojuegos.'::text),
(357296,39700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un gamer, c''est une personne ... joue aux jeux, donc c''est pour ça qu''il joue aux jeux.'::text,'qui'::text,'laquelle'::text,'où'::text,'Un gamer, c''est une personne qui joue aux jeux, donc c''est pour ça qu''il joue aux jeux.'::text),
(357299,39700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncu, oyun ... kişidir, yani bu yüzden oyun oynar.'::text,'oynayan'::text,'oynayan'::text,'oynadığı yerdeki'::text,'Oyuncu, oyun oynayan kişidir, yani bu yüzden oyun oynar.'::text),
(357300,39700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gamer olyan ember, ... játszik, szóval ezért játszik.'::text,'aki'::text,'amely'::text,'ahol'::text,'A gamer olyan ember, aki játszik, szóval ezért játszik.'::text),
(357303,39701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kommentator erklärte, dass der Gamer das Turnier mit einer bemerkenswert schnellen Runde ...'::text,'gewonnen hatte'::text,'gewonnen hat'::text,'gewinnt'::text,'Der Kommentator erklärte, dass der Gamer das Turnier mit einer bemerkenswert schnellen Runde gewonnen hatte.'::text),
(357307,39701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коментатор заявив, що геймер ... турнір завдяки надзвичайно швидкому колу.'::text,'виграв'::text,'виграв'::text,'виграє'::text,'Коментатор заявив, що геймер виграв турнір завдяки надзвичайно швидкому колу.'::text),
(357306,39701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El comentarista afirmó que el gamer ... el torneo con una vuelta notablemente rápida.'::text,'había ganado'::text,'ha ganado'::text,'gana'::text,'El comentarista afirmó que el gamer había ganado el torneo con una vuelta notablemente rápida.'::text),
(357305,39701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le commentateur a déclaré que le gamer ... le tournoi grâce à un tour remarquablement rapide.'::text,'avait gagné'::text,'a gagné'::text,'gagne'::text,'Le commentateur a déclaré que le gamer avait gagné le tournoi grâce à un tour remarquablement rapide.'::text),
(357308,39701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yorumcu, oyuncunun turnuvayı dikkat çekici derecede hızlı bir turla ... belirtti.'::text,'kazandığını'::text,'kazandığını'::text,'kazandığını'::text,'Yorumcu, oyuncunun turnuvayı dikkat çekici derecede hızlı bir turla kazandığını belirtti.'::text),
(357309,39701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kommentátor kijelentette, hogy a gamer figyelemre méltóan gyors körrel ... a tornát.'::text,'megnyerte'::text,'megnyerte'::text,'megnyeri'::text,'A kommentátor kijelentette, hogy a gamer figyelemre méltóan gyors körrel megnyerte a tornát.'::text),
(358824,39870,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie kein Gewächshaus gebaut hätte, ... sie im Frühling keine Setzlinge gezogen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sie kein Gewächshaus gebaut hätte, hätte sie im Frühling keine Setzlinge gezogen.'::text),
(358828,39870,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не збудувала теплицю, вона ... жодної розсади навесні.'::text,'не виростила б'::text,'не виростить'::text,'не виростила'::text,'Якби вона не збудувала теплицю, вона не виростила б жодної розсади навесні.'::text),
(358827,39870,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera construido un invernadero, no ... ninguna plántula en primavera.'::text,'habría cultivado'::text,'cultivará'::text,'cultivó'::text,'Si no hubiera construido un invernadero, no habría cultivado ninguna plántula en primavera.'::text),
(358826,39870,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas construit de serre, elle ... aucun semis au printemps.'::text,'n''aurait fait pousser'::text,'ne fera pousser'::text,'n''a fait pousser'::text,'Si elle n''avait pas construit de serre, elle n''aurait fait pousser aucun semis au printemps.'::text),
(358829,39870,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sera yapmasaydı, baharda hiç fide ...'::text,'yetiştiremezdi'::text,'yetiştiremeyecek'::text,'yetiştiremedi'::text,'Sera yapmasaydı, baharda hiç fide yetiştiremezdi.'::text),
(358830,39870,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem épített volna üvegházat, tavasszal egyetlen palántát sem ...'::text,'nevelt volna'::text,'fog nevelni'::text,'nevelt'::text,'Ha nem épített volna üvegházat, tavasszal egyetlen palántát sem nevelt volna.'::text),
(354711,39413,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schwarm ... eine riesige Spirale, als die Frau nach oben zeigte, klar, nichts Besonderes.'::text,'bildete gerade'::text,'bildete'::text,'bildete'::text,'Der Schwarm bildete gerade eine riesige Spirale, als die Frau nach oben zeigte, klar, nichts Besonderes.'::text),
(354715,39413,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зграя ... величезну спіраль, коли жінка показала вгору, звісно, нічого особливого.'::text,'утворювала'::text,'утворила'::text,'утворила'::text,'Зграя утворювала величезну спіраль, коли жінка показала вгору, звісно, нічого особливого.'::text),
(354714,39413,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bandada ... una espiral gigante cuando la mujer señaló hacia arriba, nada especial, claro.'::text,'estaba formando'::text,'formó'::text,'ha formado'::text,'La bandada estaba formando una espiral gigante cuando la mujer señaló hacia arriba, nada especial, claro.'::text),
(354713,39413,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nuée ... une spirale géante quand la femme a pointé le ciel, clairement rien de spécial.'::text,'formait'::text,'a formé'::text,'a formé'::text,'La nuée formait une spirale géante quand la femme a pointé le ciel, clairement rien de spécial.'::text),
(354716,39413,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın yukarıyı gösterdiğinde sürü dev bir spiral ..., belli ki hiç de özel bir şey değil.'::text,'oluşturuyordu'::text,'oluşturdu'::text,'oluşturmuş'::text,'Kadın yukarıyı gösterdiğinde sürü dev bir spiral oluşturuyordu, belli ki hiç de özel bir şey değil.'::text),
(354717,39413,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A madárraj éppen óriási spirált ..., amikor a nő felmutatott, nyilván semmi különös.'::text,'formált'::text,'formált'::text,'formált'::text,'A madárraj éppen óriási spirált formált, amikor a nő felmutatott, nyilván semmi különös.'::text),
(354720,39414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Schwarm ... schon seit zwanzig Minuten im Kreis, offensichtlich ein sehr langweiliger Sonnenuntergang.'::text,'fliegt'::text,'fliegt'::text,'fliegt'::text,'Dieser Schwarm fliegt schon seit zwanzig Minuten im Kreis, offensichtlich ein sehr langweiliger Sonnenuntergang.'::text),
(354724,39414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця зграя ... колами вже двадцять хвилин, очевидно, дуже нудний захід сонця.'::text,'літає'::text,'літає'::text,'літає'::text,'Ця зграя літає колами вже двадцять хвилин, очевидно, дуже нудний захід сонця.'::text),
(354723,39414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esa bandada ... en círculos desde hace veinte minutos, obviamente un atardecer aburridísimo.'::text,'está volando'::text,'está volando'::text,'vuela'::text,'Esa bandada está volando en círculos desde hace veinte minutos, obviamente un atardecer aburridísimo.'::text),
(354722,39414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette nuée ... en cercles depuis vingt minutes, évidemment un coucher de soleil très ennuyeux.'::text,'vole'::text,'vole'::text,'vole'::text,'Cette nuée vole en cercles depuis vingt minutes, évidemment un coucher de soleil très ennuyeux.'::text),
(354725,39414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sürü yirmi dakikadır daireler çizerek ..., belli ki çok sıkıcı bir gün batımı.'::text,'uçuyor'::text,'uçuyor'::text,'uçar'::text,'O sürü yirmi dakikadır daireler çizerek uçuyor, belli ki çok sıkıcı bir gün batımı.'::text),
(354726,39414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a raj már húsz perce ... körbe-körbe, nyilván nagyon unalmas naplemente.'::text,'repül'::text,'repül'::text,'repül'::text,'Az a raj már húsz perce repül körbe-körbe, nyilván nagyon unalmas naplemente.'::text),
(354729,39415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... den Kopf in den Nacken, als der Schwarm über ihn hinwegflog.'::text,'legte'::text,'legte gerade'::text,'legte'::text,'Der Mann legte den Kopf in den Nacken, als der Schwarm über ihn hinwegflog.'::text),
(354733,39415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... голову, коли зграя пролетіла над ним.'::text,'закинув'::text,'закидав'::text,'закинув'::text,'Чоловік закинув голову, коли зграя пролетіла над ним.'::text),
(354732,39415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... la cabeza hacia atrás cuando la bandada pasó por encima.'::text,'echó'::text,'estaba echando'::text,'ha echado'::text,'El hombre echó la cabeza hacia atrás cuando la bandada pasó por encima.'::text),
(354731,39415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... la tête en arrière quand la nuée est passée au-dessus de lui.'::text,'a penché'::text,'penchait'::text,'a penché'::text,'L''homme a penché la tête en arrière quand la nuée est passée au-dessus de lui.'::text),
(354734,39415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürü tepesinden geçerken adam başını geriye ...'::text,'attı'::text,'atıyordu'::text,'atmış'::text,'Sürü tepesinden geçerken adam başını geriye attı.'::text),
(354735,39415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ... a fejét, amikor a raj elhúzott fölötte.'::text,'hátrahajtotta'::text,'hajtotta hátra'::text,'hátrahajtotta'::text,'A férfi hátrahajtotta a fejét, amikor a raj elhúzott fölötte.'::text),
(354738,39416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schwarm hat seine Form, seit die Leute da sind, dreimal ...'::text,'geändert'::text,'geändert'::text,'geändert'::text,'Der Schwarm hat seine Form, seit die Leute da sind, dreimal geändert.'::text),
(354742,39416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зграя ... свою форму тричі відтоді, як прийшли люди.'::text,'змінила'::text,'змінювала'::text,'змінила'::text,'Зграя змінила свою форму тричі відтоді, як прийшли люди.'::text),
(354741,39416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bandada ... de forma tres veces desde que llegó la gente.'::text,'ha cambiado'::text,'ha estado cambiando'::text,'cambió'::text,'La bandada ha cambiado de forma tres veces desde que llegó la gente.'::text),
(354740,39416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nuée ... de forme trois fois depuis l''arrivée des gens.'::text,'a changé'::text,'change'::text,'a changé'::text,'La nuée a changé de forme trois fois depuis l''arrivée des gens.'::text),
(354743,39416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar geldiğinden beri sürü şeklini üç kez ...'::text,'değiştirdi'::text,'değiştiriyor'::text,'değiştirdi'::text,'İnsanlar geldiğinden beri sürü şeklini üç kez değiştirdi.'::text),
(354744,39416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A raj háromszor ... az alakját, amióta megjöttek az emberek.'::text,'változtatta meg'::text,'változtatja'::text,'változtatta meg'::text,'A raj háromszor változtatta meg az alakját, amióta megjöttek az emberek.'::text),
(354747,39417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Sonne unterging, ... sich der Schwarm von einem Bogen in eine Spirale.'::text,'verwandelte'::text,'verwandelte'::text,'verwandelt'::text,'Als die Sonne unterging, verwandelte sich der Schwarm von einem Bogen in eine Spirale.'::text),
(354751,39417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки сонце сіло, зграя вже ... із завитка на спіраль.'::text,'перетворилася'::text,'перетворилася'::text,'перетворюється'::text,'Поки сонце сіло, зграя вже перетворилася із завитка на спіраль.'::text),
(354750,39417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se puso el sol, la bandada ya ... de una curva a una espiral.'::text,'había pasado'::text,'ha pasado'::text,'pasa'::text,'Para cuando se puso el sol, la bandada ya había pasado de una curva a una espiral.'::text),
(354749,39417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que le soleil se couche, la nuée ... d''une boucle en spirale.'::text,'s''était transformée'::text,'s''est transformée'::text,'se transforme'::text,'Le temps que le soleil se couche, la nuée s''était transformée d''une boucle en spirale.'::text),
(354752,39417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş batana kadar sürü bir kıvrımdan spirale ...'::text,'dönüşmüştü'::text,'dönüştü'::text,'dönüşüyor'::text,'Güneş batana kadar sürü bir kıvrımdan spirale dönüşmüştü.'::text),
(354753,39417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire lement a nap, a raj egy ívből spirállá ...'::text,'alakult'::text,'alakult'::text,'alakul'::text,'Mire lement a nap, a raj egy ívből spirállá alakult.'::text),
(354756,39418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... der Schwarm wieder über dem Moor, und ich werde komplett ausrasten!'::text,'fliegt'::text,'fliegt'::text,'fliegt'::text,'Morgen um diese Zeit fliegt der Schwarm wieder über dem Moor, und ich werde komplett ausrasten!'::text),
(354760,39418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час зграя знову ... над болотом, і я просто закричу!'::text,'літатиме'::text,'пролетить'::text,'літає'::text,'Завтра в цей час зграя знову літатиме над болотом, і я просто закричу!'::text),
(354759,39418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora la bandada ... otra vez sobre la marisma, y me voy a poner a gritar!'::text,'estará volando'::text,'volará'::text,'vuela'::text,'¡Mañana a esta hora la bandada estará volando otra vez sobre la marisma, y me voy a poner a gritar!'::text),
(354758,39418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, la nuée ... de nouveau au-dessus du marais, et je vais carrément hurler !'::text,'volera'::text,'volera'::text,'vole'::text,'Demain à la même heure, la nuée volera de nouveau au-dessus du marais, et je vais carrément hurler !'::text),
(354761,39418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte sürü yine bataklığın üzerinde ... ve ben kesinlikle çığlık atacağım!'::text,'uçuyor olacak'::text,'uçacak'::text,'uçuyor'::text,'Yarın bu saatte sürü yine bataklığın üzerinde uçuyor olacak ve ben kesinlikle çığlık atacağım!'::text),
(354762,39418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a raj megint ... a mocsár fölött, én meg sikítani fogok!'::text,'fog repülni'::text,'fog repülni'::text,'repül'::text,'Holnap ilyenkor a raj megint fog repülni a mocsár fölött, én meg sikítani fogok!'::text),
(354774,39420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Schwarm Stare zusammen ..., ändert er sehr schnell seine Form.'::text,'fliegt'::text,'flog'::text,'fliegen wird'::text,'Wenn ein Schwarm Stare zusammen fliegt, ändert er sehr schnell seine Form.'::text),
(354778,39420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли зграя шпаків ... разом, вона дуже швидко змінює форму.'::text,'летить'::text,'летіла'::text,'полетить'::text,'Коли зграя шпаків летить разом, вона дуже швидко змінює форму.'::text),
(354777,39420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando una bandada de estorninos ... junta, cambia de forma muy rápido.'::text,'vuela'::text,'voló'::text,'volará'::text,'Cuando una bandada de estorninos vuela junta, cambia de forma muy rápido.'::text),
(354776,39420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand une nuée d''étourneaux ... ensemble, elle change de forme très vite.'::text,'vole'::text,'volait'::text,'volera'::text,'Quand une nuée d''étourneaux vole ensemble, elle change de forme très vite.'::text),
(354779,39420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sığırcık sürüsü birlikte ..., şeklini çok hızlı değiştirir.'::text,'uçtuğunda'::text,'uçtuğunda'::text,'uçacağında'::text,'Bir sığırcık sürüsü birlikte uçtuğunda, şeklini çok hızlı değiştirir.'::text),
(354780,39420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor egy seregélyraj együtt ..., nagyon gyorsan változtatja az alakját.'::text,'repül'::text,'repült'::text,'fog repülni'::text,'Amikor egy seregélyraj együtt repül, nagyon gyorsan változtatja az alakját.'::text),
(354783,39421,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend kann sie nicht aufhören, auf den Schwarm zu ...'::text,'zeigen'::text,'zeigen'::text,'zeigen'::text,'Hör mal, anscheinend kann sie nicht aufhören, auf den Schwarm zu zeigen.'::text),
(354787,39421,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона не може перестати ... на зграю.'::text,'показувати'::text,'показувати'::text,'показувати'::text,'Слухай, кажуть, вона не може перестати показувати на зграю.'::text),
(354786,39421,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer no puede dejar de ... a la bandada.'::text,'señalar'::text,'señalar'::text,'señalar'::text,'Oye, al parecer no puede dejar de señalar a la bandada.'::text),
(354785,39421,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle n''arrive pas à arrêter de ... la nuée.'::text,'montrer du doigt'::text,'montrer du doigt'::text,'montrer du doigt'::text,'Écoute, apparemment elle n''arrive pas à arrêter de montrer du doigt la nuée.'::text),
(354788,39421,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan sürüyü ... duramıyor.'::text,'göstermeden'::text,'göstermeden'::text,'göstermek'::text,'Dinle, anlaşılan sürüyü göstermeden duramıyor.'::text),
(354789,39421,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag nem tudja abbahagyni, hogy a rajra ...'::text,'mutogasson'::text,'mutogasson'::text,'mutogat'::text,'Figyelj, állítólag nem tudja abbahagyni, hogy a rajra mutogasson.'::text),
(354792,39422,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... diesen Schwarm schon ewig, und ehrlich, ich liebe das.'::text,'beobachtest'::text,'beobachtest'::text,'beobachtest'::text,'Du beobachtest diesen Schwarm schon ewig, und ehrlich, ich liebe das.'::text),
(354796,39422,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... на цю зграю вже цілу вічність, і, чесно, я це обожнюю.'::text,'дивишся'::text,'дивишся'::text,'дивишся'::text,'Ти дивишся на цю зграю вже цілу вічність, і, чесно, я це обожнюю.'::text),
(354795,39422,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... esta bandada desde hace siglos y, sinceramente, me encanta.'::text,'estás mirando'::text,'estás mirando'::text,'miras'::text,'Tú estás mirando esta bandada desde hace siglos y, sinceramente, me encanta.'::text),
(354794,39422,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... cette nuée depuis une éternité, et franchement, j''adore ça.'::text,'regardes'::text,'regardes'::text,'regardes'::text,'Tu regardes cette nuée depuis une éternité, et franchement, j''adore ça.'::text),
(354797,39422,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sürüyü ne zamandır ... ve açıkçası buna bayılıyorum.'::text,'izliyorsun'::text,'izliyorsun'::text,'izlersin'::text,'Bu sürüyü ne zamandır izliyorsun ve açıkçası buna bayılıyorum.'::text),
(354798,39422,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már ezer éve ... ezt a rajt, és őszintén, imádom.'::text,'nézed'::text,'nézed'::text,'nézed'::text,'Már ezer éve nézed ezt a rajt, és őszintén, imádom.'::text),
(357573,39731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn er weiterspielt, ... dieser Auflauf noch viel größer, ohne Witz.'::text,'wird'::text,'würde'::text,'wurde'::text,'Yo, wenn er weiterspielt, wird dieser Auflauf noch viel größer, ohne Witz.'::text),
(357577,39731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якщо він гратиме далі, цей натовп ... ще набагато більшим, без жартів.'::text,'стане'::text,'став би'::text,'став'::text,'Йо, якщо він гратиме далі, цей натовп стане ще набагато більшим, без жартів.'::text),
(357576,39731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, si sigue tocando, esta multitud se ... mucho más grande, en serio.'::text,'hará'::text,'haría'::text,'hizo'::text,'Ey, si sigue tocando, esta multitud se hará mucho más grande, en serio.'::text),
(357575,39731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, s''il continue de jouer, cet attroupement ... encore bien plus grand, sans mentir.'::text,'deviendra'::text,'deviendrait'::text,'est devenu'::text,'Yo, s''il continue de jouer, cet attroupement deviendra encore bien plus grand, sans mentir.'::text),
(357578,39731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, çalmaya devam ederse bu kalabalık çok daha ..., cidden.'::text,'büyüyecek'::text,'büyürdü'::text,'büyüdü'::text,'Yo, çalmaya devam ederse bu kalabalık çok daha büyüyecek, cidden.'::text),
(357579,39731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, ha tovább játszik, ez a csődület még sokkal nagyobb ..., komolyan.'::text,'lesz'::text,'lenne'::text,'lett'::text,'Hé, ha tovább játszik, ez a csődület még sokkal nagyobb lesz, komolyan.'::text),
(357591,39733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Straßenmusiker ... auf dem Platz von einer großen Menschenansammlung umringt.'::text,'wurde'::text,'hat'::text,'wird'::text,'Der Straßenmusiker wurde auf dem Platz von einer großen Menschenansammlung umringt.'::text),
(357595,39733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вуличний музикант ... великим натовпом людей на площі.'::text,'був оточений'::text,'оточив'::text,'оточує'::text,'Вуличний музикант був оточений великим натовпом людей на площі.'::text),
(357594,39733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El músico callejero ... por una gran multitud de gente en la plaza.'::text,'fue rodeado'::text,'rodeó'::text,'está rodeando'::text,'El músico callejero fue rodeado por una gran multitud de gente en la plaza.'::text),
(357593,39733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le musicien de rue ... par un grand attroupement de gens sur la place.'::text,'a été entouré'::text,'a entouré'::text,'entoure'::text,'Le musicien de rue a été entouré par un grand attroupement de gens sur la place.'::text),
(357596,39733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokak müzisyeni meydanda büyük bir insan kalabalığı tarafından ...'::text,'çevrildi'::text,'çevirdi'::text,'çeviriyor'::text,'Sokak müzisyeni meydanda büyük bir insan kalabalığı tarafından çevrildi.'::text),
(357597,39733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utcazenészt ... egy nagy csődület a téren.'::text,'körülvette'::text,'körülvette'::text,'veszi körül'::text,'Az utcazenészt körülvette egy nagy csődület a téren.'::text),
(357600,39734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Innerhalb von Sekunden ... sich eine kleine Menschenansammlung um den Straßenmusiker.'::text,'bildete'::text,'bildete'::text,'bildend'::text,'Innerhalb von Sekunden bildete sich eine kleine Menschenansammlung um den Straßenmusiker.'::text),
(357604,39734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Навколо вуличного музиканта за лічені секунди ... невеликий натовп.'::text,'утворився'::text,'був утворений'::text,'утворюючись'::text,'Навколо вуличного музиканта за лічені секунди утворився невеликий натовп.'::text),
(357603,39734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una pequeña multitud ... alrededor del músico en cuestión de segundos.'::text,'se formó'::text,'fue formada'::text,'formándose'::text,'Una pequeña multitud se formó alrededor del músico en cuestión de segundos.'::text),
(357602,39734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un petit attroupement ... autour du musicien en quelques secondes.'::text,'s''est formé'::text,'a été formé'::text,'se formant'::text,'Un petit attroupement s''est formé autour du musicien en quelques secondes.'::text),
(357605,39734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saniyeler içinde müzisyenin etrafında küçük bir kalabalık ...'::text,'oluştu'::text,'oluşturuldu'::text,'oluşarak'::text,'Saniyeler içinde müzisyenin etrafında küçük bir kalabalık oluştu.'::text),
(357606,39734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Másodpercek alatt kis csődület ... az utcazenész körül.'::text,'alakult ki'::text,'lett kialakítva'::text,'kialakulva'::text,'Másodpercek alatt kis csődület alakult ki az utcazenész körül.'::text),
(357609,39735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, der Auflauf ist so groß, er ... schon berühmt sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Girl, ich hab gehört, der Auflauf ist so groß, er muss schon berühmt sein.'::text),
(357613,39735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, натовп такий великий, що він ... бути вже відомим.'::text,'мусить'::text,'не може'::text,'мав би'::text,'Подруго, я чула, натовп такий великий, що він мусить бути вже відомим.'::text),
(357612,39735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que la multitud es tan grande que él ... ser famoso ya.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Tía, me han dicho que la multitud es tan grande que él debe de ser famoso ya.'::text),
(357611,39735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu dire que l''attroupement est tellement grand qu''il ... déjà être célèbre.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Meuf, j''ai entendu dire que l''attroupement est tellement grand qu''il doit déjà être célèbre.'::text),
(357614,39735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki kalabalık o kadar büyük ki çoktan ünlü ...'::text,'olmalı'::text,'olamaz'::text,'olması gerekir'::text,'Kızım, duydum ki kalabalık o kadar büyük ki çoktan ünlü olmalı.'::text),
(357615,39735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy akkora a csődület, hogy ő már ... híres.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'Csajszi, azt hallottam, hogy akkora a csődület, hogy ő már biztosan híres.'::text),
(357618,39736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend hat die Frau, ... Zopf rot ist, den ganzen Auflauf beobachtet.'::text,'deren'::text,'die'::text,'die'::text,'Hör mal, anscheinend hat die Frau, deren Zopf rot ist, den ganzen Auflauf beobachtet.'::text),
(357622,39736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, жінка, ... коса руда, спостерігала за всім натовпом.'::text,'у якої'::text,'яка'::text,'що'::text,'Слухай, кажуть, жінка, у якої коса руда, спостерігала за всім натовпом.'::text),
(357621,39736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer la mujer ... trenza es roja estuvo mirando toda la multitud.'::text,'cuya'::text,'que'::text,'la cual'::text,'Oye, al parecer la mujer cuya trenza es roja estuvo mirando toda la multitud.'::text),
(357620,39736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la femme ... la tresse est rouge a regardé tout l''attroupement.'::text,'dont'::text,'qui'::text,'que'::text,'Écoute, apparemment la femme dont la tresse est rouge a regardé tout l''attroupement.'::text),
(357623,39736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan örgüsü kırmızı ... kadın bütün kalabalığı izlemiş.'::text,'olan'::text,'olan'::text,'olan'::text,'Dinle, anlaşılan örgüsü kırmızı olan kadın bütün kalabalığı izlemiş.'::text),
(357624,39736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a nő, ... copfja vörös, végignézte az egész csődületet.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Figyelj, állítólag a nő, akinek a copfja vörös, végignézte az egész csődületet.'::text),
(357627,39737,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, der Straßenmusiker hat mir gesagt, der Auflauf ... der größte, den er je gesehen hat.'::text,'war'::text,'ist'::text,'wird'::text,'Girl, der Straßenmusiker hat mir gesagt, der Auflauf war der größte, den er je gesehen hat.'::text),
(357631,39737,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, музикант сказав мені, що цей натовп ... найбільшим, який він коли-небудь бачив.'::text,'був'::text,'є'::text,'буде'::text,'Подруго, музикант сказав мені, що цей натовп був найбільшим, який він коли-небудь бачив.'::text),
(357630,39737,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el músico me dijo que la multitud ... la más grande que había visto nunca.'::text,'era'::text,'es'::text,'será'::text,'Tía, el músico me dijo que la multitud era la más grande que había visto nunca.'::text),
(357629,39737,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le musicien m''a dit que l''attroupement ... le plus grand qu''il ait jamais vu.'::text,'était'::text,'est'::text,'sera'::text,'Meuf, le musicien m''a dit que l''attroupement était le plus grand qu''il ait jamais vu.'::text),
(357632,39737,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, müzisyen bana kalabalığın gördüğü en büyük kalabalık ... söyledi.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Kızım, müzisyen bana kalabalığın gördüğü en büyük kalabalık olduğunu söyledi.'::text),
(357633,39737,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, az utcazenész azt mondta, hogy a csődület ... a legnagyobb, amit valaha látott.'::text,'volt'::text,NULL::text,'lesz'::text,'Csajszi, az utcazenész azt mondta, hogy a csődület volt a legnagyobb, amit valaha látott.'::text),
(357636,39738,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... früher der Typ, für den niemand stehen blieb, und jetzt schau dir diesen Auflauf an, ehrlich.'::text,'warst'::text,'warst'::text,'warst es gewohnt'::text,'Du warst früher der Typ, für den niemand stehen blieb, und jetzt schau dir diesen Auflauf an, ehrlich.'::text),
(357640,39738,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... хлопцем, біля якого ніхто не зупинявся, а тепер глянь на цей натовп, чесно.'::text,'колись був'::text,'бувало, був'::text,'звик бути'::text,'Ти колись був хлопцем, біля якого ніхто не зупинявся, а тепер глянь на цей натовп, чесно.'::text),
(357639,39738,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... el chico por el que nadie se paraba, y ahora mira esta multitud, en serio.'::text,'solías ser'::text,'solías ser'::text,'estabas acostumbrado a ser'::text,'Tú solías ser el chico por el que nadie se paraba, y ahora mira esta multitud, en serio.'::text),
(357638,39738,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, tu ... le mec pour qui personne ne s''arrêtait, et maintenant regarde cet attroupement, franchement.'::text,'étais'::text,'étais'::text,'avais l''habitude d''être'::text,'Avant, tu étais le mec pour qui personne ne s''arrêtait, et maintenant regarde cet attroupement, franchement.'::text),
(357641,39738,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden kimsenin durmadığı çocuk ..., şimdi şu kalabalığa bak, açıkçası.'::text,'sendin'::text,'sendin'::text,'olmaya alışkındın'::text,'Eskiden kimsenin durmadığı çocuk sendin, şimdi şu kalabalığa bak, açıkçası.'::text),
(357642,39738,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen te ... az a srác, akinél senki sem állt meg, most meg nézd ezt a csődületet, őszintén.'::text,'voltál'::text,'voltál'::text,'hozzá voltál szokva, hogy legyél'::text,'Régen te voltál az a srác, akinél senki sem állt meg, most meg nézd ezt a csődületet, őszintén.'::text),
(357645,39739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast es geschafft, mit einem einzigen Akkordeon einen ganzen Auflauf ...'::text,'anzulocken'::text,'anzulocken'::text,'anlocken'::text,'Ehrlich, du hast es geschafft, mit einem einzigen Akkordeon einen ganzen Auflauf anzulocken.'::text),
(357649,39739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, тобі вдалося ... цілий натовп одним акордеоном.'::text,'привабити'::text,'привабити'::text,'привабити'::text,'Чесно, тобі вдалося привабити цілий натовп одним акордеоном.'::text),
(357648,39739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, conseguiste ... a toda una multitud con un solo acordeón.'::text,'atraer'::text,'atraer'::text,'atraer'::text,'Sinceramente, conseguiste atraer a toda una multitud con un solo acordeón.'::text),
(357647,39739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as réussi à ... tout un attroupement avec un seul accordéon.'::text,'attirer'::text,'attirer'::text,'attirer'::text,'Franchement, tu as réussi à attirer tout un attroupement avec un seul accordéon.'::text),
(357650,39739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, tek bir akordeonla koca bir kalabalığı ... başardın.'::text,'toplamayı'::text,'toplamayı'::text,'toplamak'::text,'Açıkçası, tek bir akordeonla koca bir kalabalığı toplamayı başardın.'::text),
(357651,39739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, sikerült egyetlen harmonikával ... egy egész csődületet.'::text,'odavonzanod'::text,'odavonzanod'::text,'odavonz'::text,'Őszintén, sikerült egyetlen harmonikával odavonzanod egy egész csődületet.'::text),
(357654,39740,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist offensichtlich ein winziger Auflauf, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Das ist offensichtlich ein winziger Auflauf, oder?'::text),
(357658,39740,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ж очевидно крихітний натовп, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Це ж очевидно крихітний натовп, правда?'::text),
(357657,39740,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eso es obviamente una multitud diminuta, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Eso es obviamente una multitud diminuta, ¿verdad?'::text),
(357656,39740,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est évidemment un minuscule attroupement, ... ?'::text,'non'::text,'non'::text,'non'::text,'C''est évidemment un minuscule attroupement, non ?'::text),
(357659,39740,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu belli ki minicik bir kalabalık, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Bu belli ki minicik bir kalabalık, değil mi?'::text),
(357660,39740,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez nyilván egy apró csődület, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Ez nyilván egy apró csődület, ugye?'::text),
(357663,39741,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemandem im Auflauf gefiel das Lied, und ... dem Straßenmusiker, klar.'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Niemandem im Auflauf gefiel das Lied, und auch nicht dem Straßenmusiker, klar.'::text),
(357667,39741,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нікому в натовпі не сподобалася пісня, і музикантові ..., звісно.'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Нікому в натовпі не сподобалася пісня, і музикантові теж ні, звісно.'::text),
(357666,39741,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nadie de la multitud le gustó la canción, y ... al músico, obviamente.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'A nadie de la multitud le gustó la canción, y tampoco al músico, obviamente.'::text),
(357665,39741,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne dans l''attroupement n''a aimé la chanson, et le musicien ..., évidemment.'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Personne dans l''attroupement n''a aimé la chanson, et le musicien non plus, évidemment.'::text),
(357668,39741,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalıktaki kimse şarkıdan hoşlanmadı, müzisyen ..., tabii ki.'::text,'de hoşlanmadı'::text,'de hoşlandı'::text,'de değildi'::text,'Kalabalıktaki kimse şarkıdan hoşlanmadı, müzisyen de hoşlanmadı, tabii ki.'::text),
(357669,39741,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csődületből senkinek sem tetszett a dal, és az utcazenésznek ..., persze.'::text,'sem'::text,'is'::text,'sem'::text,'A csődületből senkinek sem tetszett a dal, és az utcazenésznek sem, persze.'::text),
(371181,41243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Familie ... wochenlang, bevor das neugeborene Baby endlich nach Hause kam.'::text,'wartete'::text,'wartet'::text,'wartete'::text,'Die Familie wartete wochenlang, bevor das neugeborene Baby endlich nach Hause kam.'::text),
(371185,41243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Родина ... тижнями, перш ніж новонароджене немовля нарешті прибуло додому.'::text,'чекала'::text,'чекає'::text,'чекала'::text,'Родина чекала тижнями, перш ніж новонароджене немовля нарешті прибуло додому.'::text),
(371184,41243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La familia ... durante semanas antes de que el bebé recién nacido llegara por fin a casa.'::text,'había estado esperando'::text,'ha estado esperando'::text,'estaba esperando'::text,'La familia había estado esperando durante semanas antes de que el bebé recién nacido llegara por fin a casa.'::text),
(371183,41243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La famille ... pendant des semaines avant que le bébé nouveau-né arrive enfin à la maison.'::text,'avait attendu'::text,'attend'::text,'attendait'::text,'La famille avait attendu pendant des semaines avant que le bébé nouveau-né arrive enfin à la maison.'::text),
(371186,41243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni doğan bebek sonunda eve gelene kadar aile haftalarca ...'::text,'beklemişti'::text,'bekliyor'::text,'bekliyordu'::text,'Yeni doğan bebek sonunda eve gelene kadar aile haftalarca beklemişti.'::text),
(371187,41243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A család hetekig ..., mire az újszülött baba végre hazaérkezett.'::text,'várt'::text,'vár'::text,'várt'::text,'A család hetekig várt, mire az újszülött baba végre hazaérkezett.'::text),
(371190,41244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonntag ... jeder Verwandte das Neugeborene mindestens einmal im Arm.'::text,'hält'::text,'hält'::text,'hält'::text,'Bis Sonntag hält jeder Verwandte das Neugeborene mindestens einmal im Arm.'::text),
(371194,41244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До неділі кожен родич ... новонароджене немовля хоча б раз.'::text,'потримає'::text,'потримає'::text,'тримає'::text,'До неділі кожен родич потримає новонароджене немовля хоча б раз.'::text),
(371193,41244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el domingo, cada familiar ... en brazos al bebé recién nacido al menos una vez.'::text,'habrá tenido'::text,'tendrá'::text,'tiene'::text,'Para el domingo, cada familiar habrá tenido en brazos al bebé recién nacido al menos una vez.'::text),
(371192,41244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici dimanche, chaque membre de la famille ... le nouveau-né dans ses bras au moins une fois.'::text,'aura tenu'::text,'tiendra'::text,'tient'::text,'D''ici dimanche, chaque membre de la famille aura tenu le nouveau-né dans ses bras au moins une fois.'::text),
(371195,41244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pazara kadar her akraba yeni doğan bebeği en az bir kez kucağına ...'::text,'almış olacak'::text,'alacak'::text,'alıyor'::text,'Pazara kadar her akraba yeni doğan bebeği en az bir kez kucağına almış olacak.'::text),
(371196,41244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vasárnapra minden rokon legalább egyszer ... az újszülött babát.'::text,'kézbe veszi'::text,'kézbe fogja venni'::text,'kézbe veszi'::text,'Vasárnapra minden rokon legalább egyszer kézbe veszi az újszülött babát.'::text),
(371199,41245,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend ... Oma bis heute Abend das Neugeborene sechs Stunden am Stück im Arm.'::text,'hält'::text,'hält'::text,'hält'::text,'Girl, anscheinend hält Oma bis heute Abend das Neugeborene sechs Stunden am Stück im Arm.'::text),
(371203,41245,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до вечора бабуся ... те новонароджене немовля шість годин поспіль.'::text,'триматиме'::text,'триматиме'::text,'потримає'::text,'Подруго, кажуть, до вечора бабуся триматиме те новонароджене немовля шість годин поспіль.'::text),
(371202,41245,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer esta noche la abuela ... seis horas seguidas con ese recién nacido en brazos.'::text,'llevará'::text,'estará'::text,'estará'::text,'Tía, al parecer esta noche la abuela llevará seis horas seguidas con ese recién nacido en brazos.'::text),
(371201,41245,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment d''ici ce soir, mamie ... ce nouveau-né dans ses bras six heures d''affilée.'::text,'aura tenu'::text,'tiendra'::text,'tiendra'::text,'Meuf, apparemment d''ici ce soir, mamie aura tenu ce nouveau-né dans ses bras six heures d''affilée.'::text),
(371204,41245,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan bu akşama kadar nine o yeni doğanı altı saat aralıksız ...'::text,'kucağında tutmuş olacak'::text,'kucağında tutuyor olacak'::text,'kucağında tutacak'::text,'Kızım, anlaşılan bu akşama kadar nine o yeni doğanı altı saat aralıksız kucağında tutmuş olacak.'::text),
(371205,41245,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag estére a mama már hat órája egyfolytában ... azt az újszülöttet.'::text,'tartja'::text,'tartja'::text,'tartani fogja'::text,'Csajszi, állítólag estére a mama már hat órája egyfolytában tartja azt az újszülöttet.'::text),
(371208,41246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Baby letztes Jahr geboren worden wäre, ... es kein Neugeborenes mehr.'::text,'wäre'::text,'wäre'::text,'ist'::text,'Wenn das Baby letztes Jahr geboren worden wäre, wäre es kein Neugeborenes mehr.'::text),
(371212,41246,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби дитина народилася минулого року, вона вже ... новонародженою.'::text,'не була б'::text,'не була б'::text,'не буде'::text,'Якби дитина народилася минулого року, вона вже не була б новонародженою.'::text),
(371211,41246,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el bebé hubiera nacido el año pasado, ya no ... un recién nacido.'::text,'sería'::text,'habría sido'::text,'será'::text,'Si el bebé hubiera nacido el año pasado, ya no sería un recién nacido.'::text),
(371210,41246,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le bébé était né l''année dernière, il ... plus un nouveau-né.'::text,'ne serait'::text,'n''aurait été'::text,'ne sera'::text,'Si le bébé était né l''année dernière, il ne serait plus un nouveau-né.'::text),
(371213,41246,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebek geçen yıl doğmuş olsaydı, artık yeni doğan ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Bebek geçen yıl doğmuş olsaydı, artık yeni doğan olmazdı.'::text),
(371214,41246,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a baba tavaly született volna, már ... újszülött.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha a baba tavaly született volna, már nem lenne újszülött.'::text),
(371217,41247,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man geht davon aus, dass das Neugeborene das ganze Fotoshooting ..., offensichtlich ein sehr lautes Baby.'::text,'verschlafen hat'::text,'verschläft'::text,'schlafend'::text,'Man geht davon aus, dass das Neugeborene das ganze Fotoshooting verschlafen hat, offensichtlich ein sehr lautes Baby.'::text),
(371221,41247,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважають, що новонароджене ... всю фотосесію, очевидно, дуже гучне немовля.'::text,'проспало'::text,'спить'::text,'сплячи'::text,'Вважають, що новонароджене проспало всю фотосесію, очевидно, дуже гучне немовля.'::text),
(371220,41247,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el recién nacido ... durante toda la sesión de fotos, obviamente un bebé muy ruidoso.'::text,'durmió'::text,'duerme'::text,'durmiendo'::text,'Se cree que el recién nacido durmió durante toda la sesión de fotos, obviamente un bebé muy ruidoso.'::text),
(371219,41247,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le nouveau-né ... pendant toute la séance photo, évidemment un bébé très bruyant.'::text,'a dormi'::text,'dort'::text,'dormant'::text,'On pense que le nouveau-né a dormi pendant toute la séance photo, évidemment un bébé très bruyant.'::text),
(371222,41247,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni doğanın bütün fotoğraf çekimi boyunca ... düşünülüyor, belli ki çok gürültülü bir bebek.'::text,'uyuduğu'::text,'uyuduğu'::text,'uyuyarak'::text,'Yeni doğanın bütün fotoğraf çekimi boyunca uyuduğu düşünülüyor, belli ki çok gürültülü bir bebek.'::text),
(371223,41247,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vélik, az újszülött ... az egész fotózást, nyilván egy nagyon hangos baba.'::text,'végigaludta'::text,'végigalussza'::text,'alva'::text,'Úgy vélik, az újszülött végigaludta az egész fotózást, nyilván egy nagyon hangos baba.'::text),
(371226,41248,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oma weigerte sich, das Neugeborene irgendwem ..., offensichtlich total bereit zu teilen.'::text,'zu geben'::text,'zu geben'::text,'gegeben zu haben'::text,'Oma weigerte sich, das Neugeborene irgendwem zu geben, offensichtlich total bereit zu teilen.'::text),
(371230,41248,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бабуся відмовилася ... новонароджене будь-кому, очевидно, дуже щедра.'::text,'дати'::text,'дати'::text,'дати'::text,'Бабуся відмовилася дати новонароджене будь-кому, очевидно, дуже щедра.'::text),
(371229,41248,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abuela se negó a ... el recién nacido a nadie, clarísimamente dispuesta a compartir.'::text,'dar'::text,'dar'::text,'haber dado'::text,'La abuela se negó a dar el recién nacido a nadie, clarísimamente dispuesta a compartir.'::text),
(371228,41248,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mamie a refusé de ... le nouveau-né à qui que ce soit, clairement très partageuse.'::text,'donner'::text,'donner'::text,'avoir donné'::text,'Mamie a refusé de donner le nouveau-né à qui que ce soit, clairement très partageuse.'::text),
(371231,41248,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nine yeni doğanı kimseye ... reddetti, belli ki paylaşmaya çok hevesli.'::text,'vermeyi'::text,'vermeyi'::text,'vermiş olmayı'::text,'Nine yeni doğanı kimseye vermeyi reddetti, belli ki paylaşmaya çok hevesli.'::text),
(371232,41248,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mama nem volt hajlandó ... az újszülöttet senkinek, nyilván nagyon szeret osztozni.'::text,'odaadni'::text,'odaadni'::text,'odaadni'::text,'A mama nem volt hajlandó odaadni az újszülöttet senkinek, nyilván nagyon szeret osztozni.'::text),
(371235,41249,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, du ... Oma mit dem Neugeborenen sehen sollen, sie hat echt gestrahlt.'::text,'hättest'::text,'musst'::text,'kannst nicht'::text,'Bro, du hättest Oma mit dem Neugeborenen sehen sollen, sie hat echt gestrahlt.'::text),
(371239,41249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ти ... бачити бабусю з тим новонародженим, вона реально сяяла.'::text,'мав би'::text,'мабуть, мав'::text,'не міг'::text,'Бро, ти мав би бачити бабусю з тим новонародженим, вона реально сяяла.'::text),
(371238,41249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, tú ... visto a la abuela con ese recién nacido, estaba radiante de verdad.'::text,'deberías haber'::text,'debes de haber'::text,'no puedes haber'::text,'Bro, tú deberías haber visto a la abuela con ese recién nacido, estaba radiante de verdad.'::text),
(371237,41249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, tu ... voir mamie avec ce nouveau-né, elle rayonnait grave.'::text,'aurais dû'::text,'as dû'::text,'n''as pas pu'::text,'Frérot, tu aurais dû voir mamie avec ce nouveau-né, elle rayonnait grave.'::text),
(371240,41249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, nineyi o yeni doğanla ..., resmen parlıyordu.'::text,'görmeliydin'::text,'görmüş olmalısın'::text,'görmüş olamazsın'::text,'Kanka, nineyi o yeni doğanla görmeliydin, resmen parlıyordu.'::text),
(371241,41249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a mamát azzal az újszülöttel, komolyan ragyogott.'::text,'látnod kellett volna'::text,'biztosan láttad'::text,'nem láthattad'::text,'Tesó, látnod kellett volna a mamát azzal az újszülöttel, komolyan ragyogott.'::text),
(371253,41251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Familie ließ das erste Foto des Neugeborenen vor der Deadline um 17 Uhr ...'::text,'machen'::text,'machen'::text,'machen'::text,'Die Familie ließ das erste Foto des Neugeborenen vor der Deadline um 17 Uhr machen.'::text),
(371257,41251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Родина домовилася, щоб перше фото новонародженого ... до дедлайну о 17:00.'::text,'зробили'::text,'зробили'::text,'зробили'::text,'Родина домовилася, щоб перше фото новонародженого зробили до дедлайну о 17:00.'::text),
(371256,41251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La familia hizo que le ... la primera foto al recién nacido antes del plazo de las 17:00.'::text,'sacaran'::text,'sacaran'::text,'sacaran'::text,'La familia hizo que le sacaran la primera foto al recién nacido antes del plazo de las 17:00.'::text),
(371255,41251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La famille a fait ... la première photo du nouveau-né avant la deadline de 17 h.'::text,'prendre'::text,'prendre'::text,'prendre'::text,'La famille a fait prendre la première photo du nouveau-né avant la deadline de 17 h.'::text),
(371258,41251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aile, yeni doğanın ilk fotoğrafını saat 17.00 teslim tarihinden önce ...'::text,'çektirdi'::text,'çektirdi'::text,'çektirdi'::text,'Aile, yeni doğanın ilk fotoğrafını saat 17.00 teslim tarihinden önce çektirdi.'::text),
(371259,41251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A család a 17 órás határidő előtt ... az újszülött első fotóját.'::text,'elkészíttette'::text,'elkészíttette'::text,'elkészíttette'::text,'A család a 17 órás határidő előtt elkészíttette az újszülött első fotóját.'::text),
(371262,41252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Teenager wünscht sich, dass das neugeborene Baby ... und ihn ansieht.'::text,'aufwacht'::text,'aufwachte'::text,'aufwachen wird'::text,'Der Teenager wünscht sich, dass das neugeborene Baby aufwacht und ihn ansieht.'::text),
(371266,41252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець-підліток хоче, щоб новонароджене немовля ... і подивилося на нього.'::text,'прокинулося'::text,'прокинулося'::text,'прокинеться'::text,'Хлопець-підліток хоче, щоб новонароджене немовля прокинулося і подивилося на нього.'::text),
(371265,41252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El adolescente desea que el bebé recién nacido se ... y lo mire.'::text,'despierte'::text,'despertara'::text,'despertará'::text,'El adolescente desea que el bebé recién nacido se despierte y lo mire.'::text),
(371264,41252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''ado aimerait que le nouveau-né se ... et le regarde.'::text,'réveille'::text,'réveillait'::text,'réveillera'::text,'L''ado aimerait que le nouveau-né se réveille et le regarde.'::text),
(371267,41252,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç çocuk, yeni doğan bebeğin ... ona bakmasını istiyor.'::text,'uyanıp'::text,'uyanıp'::text,'uyanacak'::text,'Genç çocuk, yeni doğan bebeğin uyanıp ona bakmasını istiyor.'::text),
(371268,41252,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tinédzser fiú azt szeretné, ha az újszülött baba ... és ránézne.'::text,'felébredne'::text,'felébredne'::text,'fel fog ébredni'::text,'A tinédzser fiú azt szeretné, ha az újszülött baba felébredne és ránézne.'::text),
(371271,41253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Urgroßmutter, ... Arme das Neugeborene halten, lächelt in die Kamera.'::text,'deren'::text,'die'::text,'die'::text,'Die Urgroßmutter, deren Arme das Neugeborene halten, lächelt in die Kamera.'::text),
(371275,41253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прабабуся, ... руки тримають новонароджене, усміхається в камеру.'::text,'чиї'::text,'яка'::text,'що'::text,'Прабабуся, чиї руки тримають новонароджене, усміхається в камеру.'::text),
(371274,41253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bisabuela, ... brazos sostienen al recién nacido, sonríe a la cámara.'::text,'cuyos'::text,'que'::text,'la cual'::text,'La bisabuela, cuyos brazos sostienen al recién nacido, sonríe a la cámara.'::text),
(371273,41253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arrière-grand-mère, ... les bras tiennent le nouveau-né, sourit à la caméra.'::text,'dont'::text,'qui'::text,'laquelle'::text,'L''arrière-grand-mère, dont les bras tiennent le nouveau-né, sourit à la caméra.'::text),
(371276,41253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kolları yeni doğanı ... büyük nine kameraya gülümsüyor.'::text,'tutan'::text,'tutan'::text,'tutan'::text,'Kolları yeni doğanı tutan büyük nine kameraya gülümsüyor.'::text),
(371277,41253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dédnagymama, ... karja az újszülöttet tartja, a kamerába mosolyog.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A dédnagymama, akinek a karja az újszülöttet tartja, a kamerába mosolyog.'::text),
(403491,44833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... seit 8 Uhr winzige Uhrenrädchen in dieser Werkstatt ein, echt legendär.'::text,'setzt'::text,'setzt'::text,'setzt'::text,'Bro, sie setzt seit 8 Uhr winzige Uhrenrädchen in dieser Werkstatt ein, echt legendär.'::text),
(403495,44833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... крихітні годинникові коліщатка в тій майстерні з восьмої ранку, реально легенда.'::text,'вставляє'::text,'вставляє'::text,'вставляє'::text,'Бро, вона вставляє крихітні годинникові коліщатка в тій майстерні з восьмої ранку, реально легенда.'::text),
(403494,44833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... ruedecitas de reloj en ese taller desde las 8:00, una auténtica crack.'::text,'lleva montando'::text,'está montando'::text,'monta'::text,'Bro, ella lleva montando ruedecitas de reloj en ese taller desde las 8:00, una auténtica crack.'::text),
(403493,44833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... de minuscules rouages d''horloge dans cet atelier depuis 8 h, trop une légende.'::text,'monte'::text,'monte'::text,'monte'::text,'Frérot, elle monte de minuscules rouages d''horloge dans cet atelier depuis 8 h, trop une légende.'::text),
(403496,44833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sabah 8''den beri o atölyede minicik saat çarklarını ..., resmen efsane.'::text,'takıyor'::text,'takıyor'::text,'takar'::text,'Kanka, sabah 8''den beri o atölyede minicik saat çarklarını takıyor, resmen efsane.'::text),
(403497,44833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, reggel 8 óta ... az apró óra-fogaskerekeket abban a műhelyben, komolyan legenda.'::text,'szereli be'::text,'szereli be'::text,'szereli be'::text,'Tesó, reggel 8 óta szereli be az apró óra-fogaskerekeket abban a műhelyben, komolyan legenda.'::text),
(403500,44834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie hat die Uhr fertig gemacht und dann in der Werkstatt nach dem Kuckuck ..., ziemlich ikonisch.'::text,'gegriffen'::text,'gegriffen'::text,'gegriffen'::text,'Alter, sie hat die Uhr fertig gemacht und dann in der Werkstatt nach dem Kuckuck gegriffen, ziemlich ikonisch.'::text),
(403504,44834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона доробила годинник, а потім ... до зозулі в майстерні, досить культово.'::text,'потягнулася'::text,'тягнулася'::text,'потягнулася'::text,'Чувак, вона доробила годинник, а потім потягнулася до зозулі в майстерні, досить культово.'::text),
(403503,44834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, terminó el reloj y luego ... hacia el cuco en el taller, bastante icónico.'::text,'se estiró'::text,'se estaba estirando'::text,'se ha estirado'::text,'Tío, terminó el reloj y luego se estiró hacia el cuco en el taller, bastante icónico.'::text),
(403502,44834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle a fini l''horloge et ensuite elle ... vers le coucou dans l''atelier, assez iconique.'::text,'a tendu la main'::text,'tendait la main'::text,'a tendu la main'::text,'Mec, elle a fini l''horloge et ensuite elle a tendu la main vers le coucou dans l''atelier, assez iconique.'::text),
(403505,44834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, saati bitirdi ve sonra atölyede guguk kuşuna ..., bayağı ikonik.'::text,'uzandı'::text,'uzanıyordu'::text,'uzanmış'::text,'Kanka, saati bitirdi ve sonra atölyede guguk kuşuna uzandı, bayağı ikonik.'::text),
(403506,44834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, befejezte az órát, aztán ... a kakukk felé a műhelyben, elég ikonikus.'::text,'felnyúlt'::text,'nyúlt fel'::text,'felnyúlt'::text,'Haver, befejezte az órát, aztán felnyúlt a kakukk felé a műhelyben, elég ikonikus.'::text),
(403509,44835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Werkstatt hat in diesem Quartal 40 Uhrwerke ..., und jedes hat die Prüfung bestanden.'::text,'fertiggestellt'::text,'fertiggestellt'::text,'fertiggestellt'::text,'Diese Werkstatt hat in diesem Quartal 40 Uhrwerke fertiggestellt, und jedes hat die Prüfung bestanden.'::text),
(403513,44835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця майстерня цього кварталу ... 40 годинникових механізмів, і кожен пройшов перевірку.'::text,'завершила'::text,'завершувала'::text,'завершує'::text,'Ця майстерня цього кварталу завершила 40 годинникових механізмів, і кожен пройшов перевірку.'::text),
(403512,44835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este taller ... 40 mecanismos de reloj este trimestre y todos han pasado el control.'::text,'ha terminado'::text,'ha estado terminando'::text,'está terminando'::text,'Este taller ha terminado 40 mecanismos de reloj este trimestre y todos han pasado el control.'::text),
(403511,44835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet atelier ... 40 mouvements d''horlogerie ce trimestre, et chacun a passé le contrôle.'::text,'a terminé'::text,'termine'::text,'termine'::text,'Cet atelier a terminé 40 mouvements d''horlogerie ce trimestre, et chacun a passé le contrôle.'::text),
(403514,44835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu atölye bu çeyrekte 40 saat mekanizmasını ... ve her biri kontrolden geçti.'::text,'tamamladı'::text,'tamamlıyor'::text,'tamamlıyor'::text,'Bu atölye bu çeyrekte 40 saat mekanizmasını tamamladı ve her biri kontrolden geçti.'::text),
(403515,44835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a műhely ebben a negyedévben 40 óraszerkezetet ..., és mindegyik átment az ellenőrzésen.'::text,'fejezett be'::text,'fejezett be'::text,'fejez be'::text,'Ez a műhely ebben a negyedévben 40 óraszerkezetet fejezett be, és mindegyik átment az ellenőrzésen.'::text),
(403518,44836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Uhr nicht in den Schraubstock gespannt hätte, ... die kleinen Teile überall in der Werkstatt herumgefallen.'::text,'wären'::text,'werden'::text,'sind'::text,'Wenn sie die Uhr nicht in den Schraubstock gespannt hätte, wären die kleinen Teile überall in der Werkstatt herumgefallen.'::text),
(403522,44836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не затиснула годинник у лещатах, дрібні деталі ... по всій майстерні.'::text,'розсипалися б'::text,'розсиплються'::text,'розсипалися'::text,'Якби вона не затиснула годинник у лещатах, дрібні деталі розсипалися б по всій майстерні.'::text),
(403521,44836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera sujetado el reloj en el tornillo de banco, las piezas pequeñas ... por todo el taller.'::text,'se habrían caído'::text,'se caerán'::text,'se cayeron'::text,'Si no hubiera sujetado el reloj en el tornillo de banco, las piezas pequeñas se habrían caído por todo el taller.'::text),
(403520,44836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas serré l''horloge dans l''étau, les petites pièces ... partout dans l''atelier.'::text,'seraient tombées'::text,'tomberont'::text,'sont tombées'::text,'Si elle n''avait pas serré l''horloge dans l''étau, les petites pièces seraient tombées partout dans l''atelier.'::text),
(403523,44836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saati mengeneye sıkıştırmasaydı, küçük parçalar bütün atölyeye ...'::text,'saçılırdı'::text,'saçılacak'::text,'saçıldı'::text,'Saati mengeneye sıkıştırmasaydı, küçük parçalar bütün atölyeye saçılırdı.'::text),
(403524,44836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem fogta volna be az órát a satuba, az apró alkatrészek ... az egész műhelyben.'::text,'szétszóródtak volna'::text,'szét fognak szóródni'::text,'szétszóródtak'::text,'Ha nem fogta volna be az órát a satuba, az apró alkatrészek szétszóródtak volna az egész műhelyben.'::text),
(403527,44837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In einer Werkstatt hat der Besitzer die Schraubenschlüssel typischerweise nach Größe ...'::text,'sortiert'::text,'sortieren'::text,'sortierend'::text,'In einer Werkstatt hat der Besitzer die Schraubenschlüssel typischerweise nach Größe sortiert.'::text),
(403531,44837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У майстерні власник зазвичай тримає ключі ... за розміром.'::text,'розкладеними'::text,'розкласти'::text,'розкладаючи'::text,'У майстерні власник зазвичай тримає ключі розкладеними за розміром.'::text),
(403530,44837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En un taller, el dueño suele tener las llaves inglesas ... por tamaño.'::text,'ordenadas'::text,'ordenar'::text,'ordenando'::text,'En un taller, el dueño suele tener las llaves inglesas ordenadas por tamaño.'::text),
(403529,44837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans un atelier, le propriétaire fait généralement ... les clés par taille.'::text,'ranger'::text,'ranger'::text,'rangeant'::text,'Dans un atelier, le propriétaire fait généralement ranger les clés par taille.'::text),
(403532,44837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir atölyede sahibi genellikle anahtarları boyuna göre ...'::text,'dizdirir'::text,'dizer'::text,'dizerek'::text,'Bir atölyede sahibi genellikle anahtarları boyuna göre dizdirir.'::text),
(403533,44837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy műhelyben a tulajdonos jellemzően méret szerint ... a villáskulcsokat.'::text,'rendezteti el'::text,'rendezi el'::text,'rendezve'::text,'Egy műhelyben a tulajdonos jellemzően méret szerint rendezteti el a villáskulcsokat.'::text),
(403536,44838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, sie ... eine größere Werkstatt, weil das Werkzeug buchstäblich überall ist!'::text,'hätte'::text,'hat'::text,'hätte'::text,'Sie wünschte, sie hätte eine größere Werkstatt, weil das Werkzeug buchstäblich überall ist!'::text),
(403540,44838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хотіла б, щоб у неї ... більша майстерня, бо інструменти буквально всюди!'::text,'була'::text,'є'::text,'була б'::text,'Вона хотіла б, щоб у неї була більша майстерня, бо інструменти буквально всюди!'::text),
(403539,44838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella quisiera ... un taller más grande, porque las herramientas están literalmente por todas partes!'::text,'tener'::text,'tiene'::text,'tendría'::text,'¡Ella quisiera tener un taller más grande, porque las herramientas están literalmente por todas partes!'::text),
(403538,44838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... un atelier plus grand, parce que les outils sont littéralement partout !'::text,'avoir'::text,'a'::text,'aurait'::text,'Elle aimerait avoir un atelier plus grand, parce que les outils sont littéralement partout !'::text),
(403541,44838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke daha büyük bir atölyesi ..., diye düşünüyor, çünkü aletler resmen her yerde!'::text,'olsa'::text,'var'::text,'olsaydı'::text,'Keşke daha büyük bir atölyesi olsa, diye düşünüyor, çünkü aletler resmen her yerde!'::text),
(403542,44838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha ... egy nagyobb műhelye, mert a szerszámok szó szerint mindenhol ott vannak!'::text,'lenne'::text,'van'::text,'lenne'::text,'Azt szeretné, ha lenne egy nagyobb műhelye, mert a szerszámok szó szerint mindenhol ott vannak!'::text),
(403554,44840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In dieser Stadt ist ... in der Mühlenstraße der Ort, an dem sie Kuckucksuhren repariert.'::text,'die Werkstatt'::text,'eine Werkstatt'::text,'Werkstatt'::text,'In dieser Stadt ist die Werkstatt in der Mühlenstraße der Ort, an dem sie Kuckucksuhren repariert.'::text),
(403558,44840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У цьому місті ... на Млинській вулиці — це місце, де вона ремонтує годинники із зозулею.'::text,'майстерня'::text,'майстерня'::text,'майстерня'::text,'У цьому місті майстерня на Млинській вулиці — це місце, де вона ремонтує годинники із зозулею.'::text),
(403557,44840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En esta ciudad, ... de la calle Mill es donde ella arregla relojes de cuco.'::text,'el taller'::text,'un taller'::text,'taller'::text,'En esta ciudad, el taller de la calle Mill es donde ella arregla relojes de cuco.'::text),
(403556,44840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans cette ville, ... de la rue Mill, c''est là qu''elle répare des coucous.'::text,'l''atelier'::text,'un atelier'::text,'atelier'::text,'Dans cette ville, l''atelier de la rue Mill, c''est là qu''elle répare des coucous.'::text),
(403559,44840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kasabada Mill Sokağı''ndaki ..., onun guguklu saatleri tamir ettiği yer.'::text,'atölye'::text,'bir atölye'::text,'atölye'::text,'Bu kasabada Mill Sokağı''ndaki atölye, onun guguklu saatleri tamir ettiği yer.'::text),
(403560,44840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a városban ... a Mill utcában az a hely, ahol kakukkos órákat javít.'::text,'a műhely'::text,'egy műhely'::text,'műhely'::text,'Ebben a városban a műhely a Mill utcában az a hely, ahol kakukkos órákat javít.'::text),
(403563,44841,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie setzt die winzigen Rädchen in der Werkstatt ein, ... dicker Schutzbrille.'::text,'trotz'::text,'wegen'::text,'obwohl'::text,'Sie setzt die winzigen Rädchen in der Werkstatt ein, trotz dicker Schutzbrille.'::text),
(403567,44841,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вставляє крихітні коліщатка в майстерні, ... носить товсті захисні окуляри.'::text,'попри те, що'::text,'через те, що'::text,'хоча'::text,'Вона вставляє крихітні коліщатка в майстерні, попри те, що носить товсті захисні окуляри.'::text),
(403566,44841,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Monta las ruedecitas en el taller ... lleva gafas de seguridad gruesas.'::text,'a pesar de que'::text,'debido a que'::text,'aunque'::text,'Monta las ruedecitas en el taller a pesar de que lleva gafas de seguridad gruesas.'::text),
(403565,44841,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle monte les minuscules rouages dans l''atelier ... d''épaisses lunettes de protection.'::text,'malgré'::text,'à cause de'::text,'bien que'::text,'Elle monte les minuscules rouages dans l''atelier malgré d''épaisses lunettes de protection.'::text),
(403568,44841,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalın koruyucu gözlük ..., atölyede minicik çarkları takıyor.'::text,'takmasına rağmen'::text,'taktığı için'::text,'taksa da'::text,'Kalın koruyucu gözlük takmasına rağmen, atölyede minicik çarkları takıyor.'::text),
(403569,44841,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beszereli az apró fogaskerekeket a műhelyben, ... vastag védőszemüveget visel.'::text,'annak ellenére, hogy'::text,'mert'::text,'bár'::text,'Beszereli az apró fogaskerekeket a műhelyben, annak ellenére, hogy vastag védőszemüveget visel.'::text),
(403572,44842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Werkstatt heute Abend schließt, ... sie jede Uhr in der Stadt. Eindeutig ein schneller Job.'::text,'repariert'::text,'repariert'::text,'repariert'::text,'Bis die Werkstatt heute Abend schließt, repariert sie jede Uhr in der Stadt. Eindeutig ein schneller Job.'::text),
(403576,44842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки майстерня сьогодні ввечері зачиниться, вона ... всі годинники в місті. Явно швидка робота.'::text,'відремонтує'::text,'відремонтує'::text,'ремонтує'::text,'Поки майстерня сьогодні ввечері зачиниться, вона відремонтує всі годинники в місті. Явно швидка робота.'::text),
(403575,44842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando cierre el taller esta noche, ella ... todos los relojes del pueblo. Claramente, un trabajo rapidito.'::text,'habrá reparado'::text,'reparará'::text,'repara'::text,'Para cuando cierre el taller esta noche, ella habrá reparado todos los relojes del pueblo. Claramente, un trabajo rapidito.'::text),
(403574,44842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fermeture de l''atelier ce soir, elle ... toutes les horloges de la ville. Clairement un boulot rapide.'::text,'aura réparé'::text,'réparera'::text,'répare'::text,'D''ici la fermeture de l''atelier ce soir, elle aura réparé toutes les horloges de la ville. Clairement un boulot rapide.'::text),
(403577,44842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atölye bu akşam kapanana kadar kasabadaki bütün saatleri ...; belli ki çabucak biten bir iş.'::text,'tamir etmiş olacak'::text,'tamir edecek'::text,'tamir ediyor'::text,'Atölye bu akşam kapanana kadar kasabadaki bütün saatleri tamir etmiş olacak; belli ki çabucak biten bir iş.'::text),
(403578,44842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ma este bezár a műhely, ... a város összes óráját. Nyilván gyors meló.'::text,'megjavítja'::text,'meg fogja javítani'::text,'javítja'::text,'Mire ma este bezár a műhely, megjavítja a város összes óráját. Nyilván gyors meló.'::text)
